export interface Trip {
    'رقم المركبة': string;
    'صافي التحميل': string;
    'الشهر': string;
    'السنة': string;
    'تاريخ التوزين الثاني': string;
    'السائق'?: string;
    [key: string]: any;
}

export interface Vehicle {
    'رقم المركبة': string;
    'سنة التصنيع': string;
    'سعة المركبة بالمتر المكعب': string;
    'كثافة التحميل': string;
    [key: string]: any;
}

export interface Fuel {
    'رقم المركبة': string;
    'السنة': string;
    jan?: string;
    feb?: string;
    mar?: string;
    apr?: string;
    may?: string;
    jun?: string;
    july?: string;
    aug?: string;
    sep?: string;
    oct?: string;
    nov?: string;
    dec?: string;
    [key: string]: any;
}

export interface Maintenance {
    'رقم المركبة': string;
    'السنة': string;
    'كلفة الصيانة': string;
    [key: string]: any;
}

export interface Area {
    'رقم المركبة': string;
    'المنطقة': string;
    'السنة'?: string;
    [key: string]: any;
}

export interface VehicleTableData {
    veh: string;
    area: string;
    drivers: string;
    year: string;
    cap_m3: number;
    cap_ton: number;
    trips: number;
    tons: number;
    fuel: number;
    maint: number;
    cost_trip: number;
    cost_ton: number;
}

export interface DriverStatsData {
    driver: string;
    trips: number;
    tons: number;
    avgTonsPerTrip: number;
    vehicles: string;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Trip, Vehicle, Fuel, Maintenance, Area, VehicleTableData, DriverStatsData } from './types';
import { CONFIG, MONTHS_ORDER } from './constants';
import { loadAllData } from './services/dataService';
import { generateFleetReport } from './services/geminiService';
import Header from './components/Header';
import KpiGrid from './components/KpiGrid';
import ChartSection from './components/ChartSection';
import TableSection from './components/TableSection';
import AiAnalysisSection from './components/AiAnalysisSection';
import UtilizationSection from './components/UtilizationSection';
import Loader from './components/Loader';
import AreaChartSection from './components/AreaChartSection';
import DriverStatsSection from './components/DriverStatsSection';

const App: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [tripsData, setTripsData] = useState<Trip[]>([]);
    const [vehiclesData, setVehiclesData] = useState<Vehicle[]>([]);
    const [fuelData, setFuelData] = useState<Fuel[]>([]);
    const [maintData, setMaintData] = useState<Maintenance[]>([]);
    const [areasData, setAreasData] = useState<Area[]>([]);

    const [selectedYear, setSelectedYear] = useState<string>('');
    const [comparisonYear, setComparisonYear] = useState<string>('');

    const [filters, setFilters] = useState<{ vehicles: Set<string>; months: Set<string> }>({
        vehicles: new Set(),
        months: new Set(),
    });
    const [isFiltering, setIsFiltering] = useState(false);

    const [aiReport, setAiReport] = useState<string>('');
    const [aiLoading, setAiLoading] = useState<boolean>(false);
    const [aiError, setAiError] = useState<string>('');

    const lineChartRef = useRef<HTMLDivElement>(null);
    const pieChartRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const { trips, vehicles, fuel, maint, areas } = await loadAllData();
                setTripsData(trips);
                setVehiclesData(vehicles);
                setFuelData(fuel);
                setMaintData(maint);
                setAreasData(areas);

                // تحديد السنة الافتراضية كأحدث سنة موجودة في البيانات
                const years = [...new Set(trips.map(t => t['السنة']).filter(Boolean))].sort().reverse();
                if (years.length > 0) {
                    setSelectedYear(years[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleYearChange = (year: string) => {
        setIsFiltering(true);
        setSelectedYear(year);
    };

    const handleComparisonYearChange = (year: string) => {
        setIsFiltering(true);
        setComparisonYear(year);
    };

    const handleFilterToggle = useCallback((type: 'vehicles' | 'months', value: string) => {
        setIsFiltering(true);
        setFilters(prev => {
            const newSet = new Set(prev[type]);
            if (newSet.has(value)) {
                newSet.delete(value);
            } else {
                newSet.add(value);
            }
            return { ...prev, [type]: newSet };
        });
    }, []);

    const resetFilters = useCallback(() => {
        setIsFiltering(true);
        setFilters({ vehicles: new Set(), months: new Set() });
        setComparisonYear('');
    }, []);

    const filteredTrips = useMemo(() => {
        let data = tripsData.filter(r => r['السنة'] === selectedYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, selectedYear, filters]);

    const comparisonTrips = useMemo(() => {
        if (!comparisonYear) return [];
        let data = tripsData.filter(r => r['السنة'] === comparisonYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, comparisonYear, filters]);

    useEffect(() => {
        if (isFiltering) {
            const timer = setTimeout(() => setIsFiltering(false), 300);
            return () => clearTimeout(timer);
        }
    }, [filteredTrips, isFiltering]);

    const allYearsList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['السنة']).filter(Boolean))].sort().reverse();
    }, [tripsData]);

    const allVehiclesList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort();
    }, [tripsData]);

    const getVehicleTableData = (trips: Trip[], year: string) => {
        const vehGroups: { [key: string]: { trips: number; tons: number; drivers: Set<string> } } = {};

        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!vehGroups[v]) vehGroups[v] = { trips: 0, tons: 0, drivers: new Set() };
            vehGroups[v].trips += 1;
            vehGroups[v].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['السائق']) vehGroups[v].drivers.add(r['السائق']);
        });

        return Object.keys(vehGroups).map(v => {
            const { trips, tons, drivers } = vehGroups[v];
            const vehRow = vehiclesData.find(x => x['رقم المركبة'] === v) || {};
            const areaRow = areasData.find(x => x['رقم المركبة'] === v && (x['السنة'] === year || !x['السنة'])) || {};
            const fuelRow = fuelData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const maintRow = maintData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};

            let fuel = 0;
            if(fuelRow) {
                const monthsToSum = filters.months.size > 0 ? Array.from(filters.months) : MONTHS_ORDER;
                monthsToSum.forEach(m => {
                    fuel += (Number(fuelRow[m as keyof Fuel]) || 0);
                });
            }

            const maint = Number(maintRow?.['كلفة الصيانة'] || 0);
            const cap_m3 = parseFloat(vehRow['سعة المركبة بالمتر المكعب'] || '0');
            const density = parseFloat(vehRow['كثافة التحميل'] || '0');
            const cap_ton = cap_m3 * density;
            const totalCost = fuel + maint;
            const cost_trip = trips ? totalCost / trips : 0;
            const cost_ton = tons ? totalCost / tons : 0;

            return {
                veh: v,
                area: areaRow['المنطقة'] || '',
                drivers: [...drivers].join(', '),
                year: vehRow['سنة التصنيع'] || '',
                cap_m3,
                cap_ton,
                trips,
                tons,
                fuel,
                maint,
                cost_trip,
                cost_ton,
            };
        });
    };

    const filteredVehicleTableData = useMemo<VehicleTableData[]>(() => 
        getVehicleTableData(filteredTrips, selectedYear), 
    [filteredTrips, vehiclesData, areasData, fuelData, maintData, filters.months, selectedYear]);

    const comparisonVehicleTableData = useMemo<VehicleTableData[]>(() => 
        comparisonYear ? getVehicleTableData(comparisonTrips, comparisonYear) : [], 
    [comparisonTrips, vehiclesData, areasData, fuelData, maintData, filters.months, comparisonYear]);

    const driverStatsData = useMemo<DriverStatsData[]>(() => {
        const driverGroups: { [key: string]: { trips: number; tons: number; vehicles: Set<string> } } = {};

        filteredTrips.forEach(r => {
            const driver = r['السائق'];
            if (!driver || driver.trim() === '') return;

            if (!driverGroups[driver]) {
                driverGroups[driver] = { trips: 0, tons: 0, vehicles: new Set() };
            }
            driverGroups[driver].trips += 1;
            driverGroups[driver].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['رقم المركبة']) {
                driverGroups[driver].vehicles.add(r['رقم المركبة']);
            }
        });

        return Object.entries(driverGroups).map(([driver, data]) => {
            const { trips, tons, vehicles } = data;
            const avgTonsPerTrip = trips > 0 ? tons / trips : 0;

            return {
                driver,
                trips,
                tons,
                avgTonsPerTrip,
                vehicles: [...vehicles].join(', '),
            };
        });
    }, [filteredTrips]);

    const areaDistributionData = useMemo(() => {
        const areaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                areaMap.set(a['رقم المركبة'], a['المنطقة']);
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = trip['رقم المركبة'];
            if (vehicleId) {
                const area = areaMap.get(vehicleId) || 'غير محدد';
                if (!tonsByArea[area]) {
                    tonsByArea[area] = 0;
                }
                tonsByArea[area] += (Number(trip['صافي التحميل'] || 0) / 1000);
            }
        });

        return Object.entries(tonsByArea)
            .map(([name, value]) => ({ name, value: Math.round(value) }))
            .sort((a, b) => b.value - a.value);

    }, [filteredTrips, areasData, selectedYear]);

    const handleGenerateReport = async (analysisType: string, options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }) => {
        setAiLoading(true);
        setAiError('');
        setAiReport('');
        try {
            const report = await generateFleetReport(filteredVehicleTableData, analysisType, options);
            setAiReport(report);
        } catch (err) {
            setAiError('حدث خطأ أثناء إنشاء التقرير. يرجى المحاولة مرة أخرى.');
            console.error(err);
        } finally {
            setAiLoading(false);
        }
    };


    if (loading) {
        return <Loader />;
    }

    return (
        <div className="bg-slate-50 text-slate-800 min-h-screen">
            <Header
                tripsData={tripsData}
                filters={filters}
                selectedYear={selectedYear}
                comparisonYear={comparisonYear}
                availableYears={allYearsList}
                onYearChange={handleYearChange}
                onComparisonYearChange={handleComparisonYearChange}
                onFilterToggle={handleFilterToggle}
                onResetFilters={resetFilters}
            />
            <main className="container mx-auto p-4 md:p-6">
                <KpiGrid 
                    filteredTrips={filteredTrips} 
                    comparisonTrips={comparisonTrips}
                    fuelData={fuelData} 
                    maintData={maintData} 
                    filters={filters}
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    vehicleTableData={filteredVehicleTableData}
                    comparisonVehicleTableData={comparisonVehicleTableData}
                />

                <ChartSection 
                    data={filteredTrips} 
                    comparisonData={comparisonTrips}
                    isLoading={isFiltering} 
                    filters={filters} 
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    chartRef={lineChartRef} 
                />

                <AreaChartSection data={areaDistributionData} isLoading={isFiltering} filters={filters} chartRef={pieChartRef} />
                <TableSection tableData={filteredVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${selectedYear}`} />

                {comparisonYear && (
                    <TableSection tableData={comparisonVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${comparisonYear} (للمقارنة)`} />
                )}

                <DriverStatsSection tableData={driverStatsData} filters={filters} />
                <AiAnalysisSection
                    vehicles={allVehiclesList}
                    onGenerateReport={handleGenerateReport}
                    report={aiReport}
                    isLoading={aiLoading}
                    error={aiError}
                    filters={filters}
                />
                <UtilizationSection tableData={filteredVehicleTableData} filters={filters} />
            </main>
        </div>
    );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Trip } from '../types';

interface HeaderProps {
    tripsData: Trip[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    availableYears: string[];
    onYearChange: (year: string) => void;
    onComparisonYearChange: (year: string) => void;
    onFilterToggle: (type: 'vehicles' | 'months', value: string) => void;
    onResetFilters: () => void;
}

const FilterDropdown: React.FC<{
    buttonText: string;
    items: string[];
    selectedItems: Set<string> | string;
    onToggle: (item: string) => void;
    isSingle?: boolean;
    colorClass?: string;
}> = ({ buttonText, items, selectedItems, onToggle, isSingle = false, colorClass = "bg-white text-slate-800" }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isSelected = (item: string) => {
        if (isSingle) return selectedItems === item;
        return (selectedItems as Set<string>).has(item);
    };

    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`px-4 py-2 border-none rounded-lg text-sm font-semibold cursor-pointer shadow-md transition hover:opacity-90 ${colorClass}`}
            >
                {buttonText} {isSingle && selectedItems ? `: ${selectedItems}` : '▼'}
            </button>
            {isOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-xl z-20 max-h-64 overflow-y-auto p-2 border border-slate-200">
                    {items.map(item => (
                        <label key={item} className="flex items-center space-x-2 p-2 rounded-md hover:bg-slate-100 cursor-pointer">
                            <input
                                type={isSingle ? "radio" : "checkbox"}
                                name={isSingle ? "single-select" : undefined}
                                value={item}
                                checked={isSelected(item)}
                                onChange={() => {
                                    onToggle(item);
                                    if (isSingle) setIsOpen(false);
                                }}
                                className="form-checkbox h-4 w-4 text-blue-600 rounded"
                            />
                            <span className="text-sm text-slate-700">{item}</span>
                        </label>
                    ))}
                    {isSingle && items.length > 0 && (
                        <button 
                            onClick={() => { onToggle(''); setIsOpen(false); }}
                            className="w-full text-right p-2 text-xs text-red-500 hover:bg-red-50 rounded mt-1 border-t border-slate-100"
                        >
                            إلغاء الاختيار
                        </button>
                    )}
                </div>
            )}
        </div>
    );
};

const Header: React.FC<HeaderProps> = ({ 
    tripsData, filters, selectedYear, comparisonYear, availableYears, 
    onYearChange, onComparisonYearChange, onFilterToggle, onResetFilters 
}) => {
    const vehicles = useMemo(() => [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort(), [tripsData]);
    const months = useMemo(() => [...new Set(tripsData.map(r => (r['الشهر'] || '').toLowerCase()).filter(Boolean))], [tripsData]);

    const printKPIs = () => {
        const kpiElement = document.getElementById('kpi-grid');
        if (kpiElement) {
            const printWindow = window.open('', '', 'height=800,width=1000');
            if (!printWindow) {
                alert('Please allow popups to print the report.');
                return;
            }

            const today = new Date().toLocaleDateString('ar-EG-u-nu-latn', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });

            const kpiCardNodes = Array.from(kpiElement.children);
            let cardsHtml = '';
            kpiCardNodes.forEach(cardNode => {
                const valueNode = cardNode.querySelector('.kpi-value-main');
                const labelNode = cardNode.querySelector('.kpi-label-text');
                const iconNode = cardNode.querySelector('.kpi-icon');

                const value = valueNode?.textContent || '';
                const icon = iconNode?.textContent || '';
                const label = labelNode?.textContent?.trim() || '';
                const colorClass = valueNode?.className.split(' ').find(c => c.startsWith('text-')) || 'text-slate-800';

                cardsHtml += `
                    <div class="kpi-card">
                        <div class="kpi-value ${colorClass}">${value}</div>
                        <div class="kpi-label">
                            <span>${icon}</span>
                            ${label}
                        </div>
                    </div>
                `;
            });

            const printContent = `
                <html>
                <head>
                    <title>طباعة مؤشرات الأداء الرئيسية</title>
                    <link rel="preconnect" href="https://fonts.googleapis.com">
                    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
                    <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap" rel="stylesheet">
                    <style>
                        body { font-family: 'Cairo', sans-serif; direction: rtl; margin: 20px; background-color: #fff; }
                        .print-header { text-align: center; margin-bottom: 25px; border-bottom: 2px solid #333; padding-bottom: 15px; }
                        .print-header h1 { font-size: 24px; margin: 0; color: #1e3a8a; }
                        .print-header h2 { font-size: 18px; margin: 5px 0 0; color: #4b5563; }
                        .kpi-grid-container { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; padding: 10px; }
                        .kpi-card { border: 1px solid #e5e7eb; border-radius: 12px; padding: 16px; text-align: center; background-color: #f9fafb; page-break-inside: avoid; }
                        .kpi-value { font-size: 28px; font-weight: 700; margin-bottom: 8px; }
                        .kpi-label { font-size: 14px; font-weight: 600; color: #374151; display: flex; align-items: center; justify-content: center; gap: 8px; }
                        .text-blue-600 { color: #2563eb; }
                        .text-sky-500 { color: #0ea5e9; }
                        /* ... remaining colors ... */
                    </style>
                </head>
                <body>
                    <div class="print-header">
                        <h1>مؤشرات الأداء - سنة ${selectedYear}</h1>
                        <h2>بلدية مؤتة والمزار - ${today}</h2>
                    </div>
                    <div class="kpi-grid-container">${cardsHtml}</div>
                </body>
                </html>
            `;
            printWindow.document.write(printContent);
            printWindow.document.close();
            setTimeout(() => { printWindow.print(); printWindow.close(); }, 500);
        }
    };

    return (
        <header className="bg-gradient-to-l from-blue-700 to-sky-600 text-white p-5 shadow-lg flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="text-center md:text-right">
                <h1 className="text-xl md:text-2xl font-bold leading-tight">بيانات نقل النفايات الذكية</h1>
                <h2 className="text-lg font-semibold">بلدية مؤتة والمزار</h2>
            </div>
            <div className="flex flex-wrap items-center justify-center gap-2">
                <FilterDropdown
                    buttonText="السنة"
                    items={availableYears}
                    selectedItems={selectedYear}
                    onToggle={onYearChange}
                    isSingle={true}
                    colorClass="bg-blue-800 text-white border border-blue-400"
                />
                <FilterDropdown
                    buttonText="مقارنة بـ"
                    items={availableYears.filter(y => y !== selectedYear)}
                    selectedItems={comparisonYear}
                    onToggle={onComparisonYearChange}
                    isSingle={true}
                    colorClass="bg-amber-500 text-white"
                />
                <div className="w-px h-8 bg-white/30 mx-1 hidden md:block"></div>
                <FilterDropdown
                    buttonText="المركبات"
                    items={vehicles}
                    selectedItems={filters.vehicles}
                    onToggle={(item) => onFilterToggle('vehicles', item)}
                />
                <FilterDropdown
                    buttonText="الأشهر"
                    items={months}
                    selectedItems={filters.months}
                    onToggle={(item) => onFilterToggle('months', item.toLowerCase())}
                />
                <button
                    onClick={onResetFilters}
                    className="px-3 py-2 border-none rounded-lg bg-red-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-red-600"
                >
                    إعادة تعيين
                </button>
                <button
                    onClick={printKPIs}
                    className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600"
                >
                    طباعة
                </button>
            </div>
        </header>
    );
};

export default Header;

import React from 'react';

interface KpiCardProps {
    value: string | number;
    label: string;
    icon: string;
    color: string;
    comparisonValue?: string | number | null;
}

const KpiCard: React.FC<KpiCardProps> = ({ value, label, icon, color, comparisonValue }) => {
    const renderDelta = () => {
        if (comparisonValue === undefined || comparisonValue === null) return null;

        const currentNum = typeof value === 'string' ? parseFloat(value.replace(/,/g, '')) : value;
        const prevNum = typeof comparisonValue === 'string' ? parseFloat(comparisonValue.replace(/,/g, '')) : comparisonValue;

        if (isNaN(currentNum) || isNaN(prevNum) || prevNum === 0) return null;

        const diff = currentNum - prevNum;
        const percent = (diff / prevNum) * 100;
        const isPositive = diff > 0;

        return (
            <div className={`text-xs mt-1 font-bold ${isPositive ? 'text-green-600' : 'text-red-600'}`}>
                {isPositive ? '↑' : '↓'} {Math.abs(percent).toFixed(1)}% 
                <span className="text-slate-400 font-normal mr-1">عن سنة المقارنة</span>
            </div>
        );
    };

    return (
        <div className="bg-white rounded-2xl p-5 shadow-lg transition-transform hover:-translate-y-1 border-t-4 border-transparent hover:border-current group" style={{ color: color.replace('text-', '') }}>
            <div className={`text-2xl md:text-3xl font-black mb-1 kpi-value-main ${color}`}>{value}</div>
            {renderDelta()}
            <div className="text-sm font-bold text-slate-700 flex items-center gap-2 mt-2">
                <span className="text-lg kpi-icon">{icon}</span>
                <span className="kpi-label-text">{label}</span>
            </div>
        </div>
    );
};

export default KpiCard;

import React, { useMemo } from 'react';
import { Trip, Fuel, Maintenance, VehicleTableData } from '../types';
import { MONTHS_ORDER } from '../constants';
import { formatNumber } from '../services/dataService';
import KpiCard from './KpiCard';

interface KpiGridProps {
    filteredTrips: Trip[];
    comparisonTrips: Trip[];
    fuelData: Fuel[];
    maintData: Maintenance[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    vehicleTableData: VehicleTableData[];
    comparisonVehicleTableData: VehicleTableData[];
}

const KpiGrid: React.FC<KpiGridProps> = ({ 
    filteredTrips, comparisonTrips, fuelData, maintData, filters, 
    selectedYear, comparisonYear, vehicleTableData, comparisonVehicleTableData 
}) => {

    const calculateStats = (trips: Trip[], year: string, tableData: VehicleTableData[]) => {
        if (!trips.length && !year) return null;

        const totalTons = trips.reduce((sum, trip) => sum + (Number(trip['صافي التحميل'] || 0) / 1000), 0);
        const totalTrips = trips.length;
        const activeVehicles = new Set(trips.map(r => r['رقم المركبة']).filter(Boolean));

        const sumFuelForVehicle = (veh: string) => {
            const row = fuelData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            if (!row) return 0;
            const monthsToSum = filters.months.size ? Array.from(filters.months) : MONTHS_ORDER;
            return monthsToSum.reduce((s, m) => s + (Number(row[m as keyof Fuel]) || 0), 0);
        };

        const maintForVehicle = (veh: string) => {
            const row = maintData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            return row ? (Number(row['كلفة الصيانة']) || 0) : 0;
        };

        let totalFuel = 0;
        let totalMaint = 0;
        activeVehicles.forEach(v => {
            totalFuel += sumFuelForVehicle(v);
            totalMaint += maintForVehicle(v);
        });

        const daysSet = new Set(trips.map(r => {
            const d = new Date(r['تاريخ التوزين الثاني']);
            return !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : null;
        }).filter(Boolean));
        const daysCount = daysSet.size;
        const avgTonsPerDay = daysCount > 0 ? totalTons / daysCount : 0;

        return {
            totalTons, totalTrips, totalFuel, totalMaint, avgTonsPerDay, daysCount,
            activeVehiclesCount: activeVehicles.size
        };
    };

    const currentStats = useMemo(() => calculateStats(filteredTrips, selectedYear, vehicleTableData), [filteredTrips, selectedYear, fuelData, maintData, filters]);
    const comparisonStats = useMemo(() => comparisonYear ? calculateStats(comparisonTrips, comparisonYear, comparisonVehicleTableData) : null, [comparisonTrips, comparisonYear, fuelData, maintData, filters]);

    if (!currentStats) return null;

    const kpiCards = [
        { value: Math.round(currentStats.totalTons), label: 'إجمالي الأطنان', icon: '🗑️', color: 'text-blue-600', comp: comparisonStats?.totalTons },
        { value: currentStats.totalTrips, label: 'إجمالي الرحلات', icon: '🚚', color: 'text-sky-500', comp: comparisonStats?.totalTrips },
        { value: Math.round(currentStats.totalFuel), label: 'كلفة الوقود', icon: '⛽', color: 'text-orange-500', comp: comparisonStats?.totalFuel },
        { value: Math.round(currentStats.totalMaint), label: 'كلفة الصيانة', icon: '🔧', color: 'text-red-600', comp: comparisonStats?.totalMaint },
        { value: currentStats.avgTonsPerDay.toFixed(1), label: 'متوسط الأطنان/يوم', icon: '📊', color: 'text-green-600', comp: comparisonStats?.avgTonsPerDay },
        { value: currentStats.activeVehiclesCount, label: 'المركبات النشطة', icon: '🚛', color: 'text-purple-600', comp: comparisonStats?.activeVehiclesCount },
    ];

    return (
        <div id="kpi-grid" className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
            {kpiCards.map(kpi => (
                <KpiCard 
                    key={kpi.label} 
                    value={formatNumber(kpi.value as number)} 
                    label={kpi.label} 
                    icon={kpi.icon} 
                    color={kpi.color} 
                    comparisonValue={kpi.comp !== undefined ? formatNumber(kpi.comp as number) : undefined}
                />
            ))}
        </div>
    );
};

export default KpiGrid;

import React, { useState, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Trip } from '../types';
import { MONTHS_ORDER } from '../constants';
import CollapsibleSection from './CollapsibleSection';
import { printChart } from '../services/printService';

interface ChartSectionProps {
    data: Trip[];
    comparisonData: Trip[];
    isLoading: boolean;
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    chartRef: React.RefObject<HTMLDivElement>;
}

const ChartSection: React.FC<ChartSectionProps> = ({ data, comparisonData, isLoading, filters, selectedYear, comparisonYear, chartRef }) => {
    const [metric, setMetric] = useState<'trips' | 'tons'>('trips');

    const chartData = useMemo(() => {
        // نستخدم الأشهر دائماً للمقارنة المؤسسية
        const combined = MONTHS_ORDER.map(month => {
            const currentTrips = data.filter(t => (t['الشهر'] || '').toLowerCase() === month);
            const compTrips = comparisonData.filter(t => (t['الشهر'] || '').toLowerCase() === month);

            const currentValue = metric === 'trips' 
                ? currentTrips.length 
                : currentTrips.reduce((s, t) => s + (Number(t['صافي التحميل'] || 0) / 1000), 0);

            const compValue = metric === 'trips' 
                ? compTrips.length 
                : compTrips.reduce((s, t) => s + (Number(t['صافي التحميل'] || 0) / 1000), 0);

            return {
                name: month,
                [selectedYear]: Math.round(currentValue),
                [comparisonYear || 'comp']: Math.round(compValue)
            };
        });

        return combined;
    }, [data, comparisonData, metric, selectedYear, comparisonYear]);

    const handlePrint = () => {
        const chartTitle = `مقارنة الأداء - ${metric === 'trips' ? 'الرحلات' : 'الأطنان'} - سنة ${selectedYear} ${comparisonYear ? 'مقابل ' + comparisonYear : ''}`;
        printChart(chartRef, chartTitle, filters);
    };

    return (
        <CollapsibleSection title="التحليل الزمني والمقارنة السنوية">
            <div className="flex flex-wrap items-center gap-4 mb-6 text-sm">
                <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button 
                        onClick={() => setMetric('trips')}
                        className={`px-4 py-1.5 rounded-md transition ${metric === 'trips' ? 'bg-white shadow-sm text-blue-600 font-bold' : 'text-slate-500'}`}
                    >عدد الرحلات</button>
                    <button 
                        onClick={() => setMetric('tons')}
                        className={`px-4 py-1.5 rounded-md transition ${metric === 'tons' ? 'bg-white shadow-sm text-blue-600 font-bold' : 'text-slate-500'}`}
                    >الأوزان (طن)</button>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    طباعة الرسم
                </button>
                {comparisonYear && (
                    <span className="text-xs text-slate-500 bg-amber-50 px-2 py-1 rounded border border-amber-200">
                        نمط المقارنة نشط: {selectedYear} (أزرق) vs {comparisonYear} (برتقالي)
                    </span>
                )}
            </div>
            <div className="h-96 w-full relative" ref={chartRef}>
                 {isLoading && (
                    <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg">
                        <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                    </div>
                )}
                <ResponsiveContainer>
                    <LineChart data={chartData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                        <Legend verticalAlign="top" height={36} />
                        <Line type="monotone" dataKey={selectedYear} name={`سنة ${selectedYear}`} stroke="#2563eb" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
                        {comparisonYear && (
                            <Line type="monotone" dataKey={comparisonYear} name={`سنة ${comparisonYear}`} stroke="#f59e0b" strokeWidth={3} strokeDasharray="5 5" dot={{ r: 4 }} />
                        )}
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </CollapsibleSection>
    );
};

export default ChartSection;

import React, { useState, useMemo, useRef } from 'react';
import { VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';

interface TableSectionProps {
    tableData: VehicleTableData[];
    filters: { vehicles: Set<string>; months: Set<string> };
    title?: string;
}

const TableSection: React.FC<TableSectionProps> = ({ tableData, filters, title = "جدول كفاءة المركبات" }) => {
    const [sortBy, setSortBy] = useState<keyof VehicleTableData>('tons');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const sortedData = useMemo(() => {
        const sorted = [...tableData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, 'ar');
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA;
            }
            return 0;
        });
        return sorted;
    }, [tableData, sortBy]);

    const totals = useMemo(() => {
        if (sortedData.length === 0) return null;
        const totalTrips = sortedData.reduce((s, r) => s + r.trips, 0);
        const totalTons = sortedData.reduce((s, r) => s + r.tons, 0);
        const totalFuel = sortedData.reduce((s, r) => s + r.fuel, 0);
        const totalMaint = sortedData.reduce((s, r) => s + r.maint, 0);
        const totalCost = totalFuel + totalMaint;

        const avgCostTrip = totalTrips > 0 ? totalCost / totalTrips : 0;
        const avgCostTon = totalTons > 0 ? totalCost / totalTons : 0;

        return { totalTrips, totalTons, totalFuel, totalMaint, avgCostTrip, avgCostTon };
    }, [sortedData]);

    const handlePrint = () => {
        printTable(tableContainerRef, title, filters);
    };

    const headers = [
        { key: 'veh', label: 'رقم المركبة' }, { key: 'area', label: 'المنطقة' },
        { key: 'year', label: 'الموديل' },
        { key: 'trips', label: 'الرحلات' }, { key: 'tons', label: 'الأطنان' },
        { key: 'fuel', label: 'الوقود' }, { key: 'maint', label: 'الصيانة' },
        { key: 'cost_ton', label: 'كلفة الطن' },
    ];

    return (
        <CollapsibleSection title={title}>
             <div className="flex items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="tableSort" className="ml-2 font-semibold">ترتيب:</label>
                    <select id="tableSort" value={sortBy} onChange={e => setSortBy(e.target.value as keyof VehicleTableData)}
                        className="p-2 border border-slate-300 rounded-lg">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    طباعة الجدول
                </button>
            </div>
            <div className="overflow-x-auto" ref={tableContainerRef}>
                <table id="vehicle-efficiency-table" className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-100">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-3 border-b border-slate-200 font-bold text-slate-700">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody>
                        {sortedData.map(row => (
                            <tr key={row.veh} className="hover:bg-blue-50 transition-colors">
                                <td className="p-3 border-b border-slate-200 font-bold">{row.veh}</td>
                                <td className="p-3 border-b border-slate-200">{row.area}</td>
                                <td className="p-3 border-b border-slate-200">{row.year}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.trips)}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.tons, 1)}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.fuel, 0)}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.maint, 0)}</td>
                                <td className="p-3 border-b border-slate-200 font-semibold text-blue-700">{formatNumber(row.cost_ton, 1)}</td>
                            </tr>
                        ))}
                        {totals && (
                            <tr className="font-bold bg-slate-200">
                                <td colSpan={3} className="p-3 border-b border-slate-300">الإجمالي / المتوسط</td>
                                <td className="p-3 border-b border-slate-300">{formatNumber(totals.totalTrips)}</td>
                                <td className="p-3 border-b border-slate-300">{formatNumber(totals.totalTons, 1)}</td>
                                <td className="p-3 border-b border-slate-300">{formatNumber(totals.totalFuel, 0)}</td>
                                <td className="p-3 border-b border-slate-300">{formatNumber(totals.totalMaint, 0)}</td>
                                <td className="p-3 border-b border-slate-300 text-blue-800">{formatNumber(totals.avgCostTon, 1)}</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

export default TableSection;

import React, { useMemo } from 'react';
import { Trip, Fuel, Maintenance, VehicleTableData } from '../types';
import { MONTHS_ORDER } from '../constants';
import { formatNumber } from '../services/dataService';
import KpiCard from './KpiCard';

interface KpiGridProps {
    filteredTrips: Trip[];
    comparisonTrips: Trip[];
    fuelData: Fuel[];
    maintData: Maintenance[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    vehicleTableData: VehicleTableData[];
    comparisonVehicleTableData: VehicleTableData[];
}

const KpiGrid: React.FC<KpiGridProps> = ({ 
    filteredTrips, comparisonTrips, fuelData, maintData, filters, 
    selectedYear, comparisonYear, vehicleTableData, comparisonVehicleTableData 
}) => {

    const calculateStats = (trips: Trip[], year: string, tableData: VehicleTableData[]) => {
        if (!trips.length && !year) return null;

        // Use explicit type parameter for reduce to avoid 'unknown' inference (potential fix for line 36-related error)
        const totalTons = trips.reduce<number>((sum, trip) => sum + (Number(trip['صافي التحميل'] || 0) / 1000), 0);
        const totalTrips = trips.length;
        const activeVehicles = new Set(trips.map(r => r['رقم المركبة']).filter(Boolean));

        // Explicit return type number to avoid 'unknown' in arithmetic later (fix for potential return type inference issues)
        const sumFuelForVehicle = (veh: string): number => {
            const row = fuelData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            if (!row) return 0;
            const monthsToSum = filters.months.size ? Array.from(filters.months) : MONTHS_ORDER;
            // Use explicit type parameter for reduce to avoid 'unknown' operator error (fix for line 36/37)
            return monthsToSum.reduce<number>((s, m) => s + (Number(row[m as keyof Fuel]) || 0), 0);
        };

        // Explicit return type number to avoid 'unknown' in arithmetic later
        const maintForVehicle = (veh: string): number => {
            const row = maintData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            return row ? (Number(row['كلفة الصيانة']) || 0) : 0;
        };

        let totalFuel = 0;
        let totalMaint = 0;
        // Fix for line 47 (totalFuel/totalMaint += ...) by ensuring return types are known numbers
        activeVehicles.forEach(v => {
            const fuelVal = sumFuelForVehicle(v);
            const maintVal = maintForVehicle(v);
            totalFuel += fuelVal;
            totalMaint += maintVal;
        });

        const daysSet = new Set(trips.map(r => {
            const d = new Date(r['تاريخ التوزين الثاني']);
            return !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : null;
        }).filter(Boolean));
        const daysCount = daysSet.size;
        const avgTonsPerDay = daysCount > 0 ? totalTons / daysCount : 0;

        return {
            totalTons, totalTrips, totalFuel, totalMaint, avgTonsPerDay, daysCount,
            activeVehiclesCount: activeVehicles.size
        };
    };

    const currentStats = useMemo(() => calculateStats(filteredTrips, selectedYear, vehicleTableData), [filteredTrips, selectedYear, fuelData, maintData, filters]);
    const comparisonStats = useMemo(() => comparisonYear ? calculateStats(comparisonTrips, comparisonYear, comparisonVehicleTableData) : null, [comparisonTrips, comparisonYear, fuelData, maintData, filters]);

    if (!currentStats) return null;

    const kpiCards = [
        { value: Math.round(currentStats.totalTons), label: 'إجمالي الأطنان', icon: '🗑️', color: 'text-blue-600', comp: comparisonStats?.totalTons },
        { value: currentStats.totalTrips, label: 'إجمالي الرحلات', icon: '🚚', color: 'text-sky-500', comp: comparisonStats?.totalTrips },
        { value: Math.round(currentStats.totalFuel), label: 'كلفة الوقود', icon: '⛽', color: 'text-orange-500', comp: comparisonStats?.totalFuel },
        { value: Math.round(currentStats.totalMaint), label: 'كلفة الصيانة', icon: '🔧', color: 'text-red-600', comp: comparisonStats?.totalMaint },
        { value: currentStats.avgTonsPerDay.toFixed(1), label: 'متوسط الأطنان/يوم', icon: '📊', color: 'text-green-600', comp: comparisonStats?.avgTonsPerDay },
        { value: currentStats.activeVehiclesCount, label: 'المركبات النشطة', icon: '🚛', color: 'text-purple-600', comp: comparisonStats?.activeVehiclesCount },
    ];

    return (
        <div id="kpi-grid" className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
            {kpiCards.map(kpi => (
                <KpiCard 
                    key={kpi.label} 
                    value={formatNumber(kpi.value as number)} 
                    label={kpi.label} 
                    icon={kpi.icon} 
                    color={kpi.color} 
                    comparisonValue={kpi.comp !== undefined ? formatNumber(kpi.comp as number) : undefined}
                />
            ))}
        </div>
    );
};

export default KpiGrid;

import { GoogleGenAI } from "@google/genai";
import { VehicleTableData } from "../types";

export async function generateFleetReport(
    data: VehicleTableData[],
    analysisType: string,
    options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }
): Promise<string> {

    let userRequest = '';

    switch (analysisType) {
        case 'general':
            userRequest = "Provide a general fleet-wide analysis, including the holistic ranking of all vehicles as specified in the critical instructions. Conclude with an overall assessment of the fleet's health and provide high-level strategic recommendations.";
            break;
        case 'holistic_ranking':
            userRequest = "Perform a holistic ranking of all vehicles from best to worst, as specified in the critical instructions. The ranking must be the primary focus of the report. Provide a detailed justification for each vehicle's position, explaining its strengths and weaknesses based on the provided data.";
            break;
        case 'detailed':
            userRequest = "Provide a detailed report for each vehicle individually. Analyze its performance, costs, and efficiency, and provide specific recommendations for each one.";
            break;
        case 'specific':
            if (!options.vehicleId) throw new Error('Vehicle ID is required for specific report.');
            userRequest = `Provide a detailed performance and cost analysis exclusively for vehicle number ${options.vehicleId}. Compare its performance to the fleet average if possible.`;
            break;
        case 'comparison':
            if (!options.vehicleIds || options.vehicleIds.length < 2) throw new Error('At least two Vehicle IDs are required for comparison.');
            userRequest = `Directly compare the performance, costs, and efficiency of the following vehicles: ${options.vehicleIds.join(', ')}. Highlight the key differences and declare a winner for different categories (e.g., most cost-effective, highest workload).`;
            break;
        case 'best_worst':
            userRequest = "Identify the top 3 best-performing and bottom 3 worst-performing vehicles. Base your evaluation on a combination of key metrics, primarily cost per ton and total tons collected. Justify your selections with data and provide clear reasons.";
            break;
        case 'custom':
            if (!options.customPrompt) throw new Error('A custom prompt is required.');
            userRequest = options.customPrompt;
            break;
        default:
            throw new Error('Invalid analysis type');
    }

    const fullPrompt = `
        You are an expert fleet management analyst. Your task is to analyze waste management vehicle data for the Mu'tah and Al-Mazar Municipality.

        **CRITICAL INSTRUCTIONS:**
        1.  All responses MUST be in formal Arabic.
        2.  All numbers in your response MUST be English numerals (e.g., 123, 45.6, 2024).
        3.  **Holistic Ranking:** When requested to perform a general analysis or ranking, you MUST rank all vehicles from best to worst. This ranking must be holistic, considering a combination of all provided variables, not just one. Key factors to weigh include cost-effectiveness (cost_ton, cost_trip), productivity (tons, trips), and manufacturing year (year). Present the ranking clearly (e.g., a numbered list) and provide a justification for each vehicle's position, explaining its strengths and weaknesses.
        4.  Provide specific, testable, and actionable recommendations. For example, suggest reassigning specific vehicles to different zones if data supports it ("انقل الضاغطة 7 إلى المنطقة الشرقية لتحسين الاستغلال").
        5.  The data provides total costs. When you mention costs, clarify they are totals for the entire period covered by the data.
        6.  The data columns are: veh (vehicle number), area (work zone), drivers, year (year of manufacture), cap_m3 (capacity in cubic meters), cap_ton (theoretical capacity in tons), trips (total trips), tons (total tons collected), fuel (total fuel cost), maint (total maintenance cost), cost_trip (average cost per trip), cost_ton (average cost per ton).

        **VEHICLE DATA (in JSON format):**
        ${JSON.stringify(data, null, 2)}

        **USER REQUEST:**
        ${userRequest}
    `;

    // Create new GoogleGenAI instance inside the function as per coding guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
        // Using 'gemini-3-pro-preview' for complex fleet analysis reasoning
        model: 'gemini-3-pro-preview',
        contents: fullPrompt,
    });

    return response.text || '';
}

