import { GoogleGenAI } from "@google/genai";
import { VehicleTableData } from "../types";

export async function generateFleetReport(
    data: VehicleTableData[],
    analysisType: string,
    options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }
): Promise<string> {

    // FIX: Always initialize GoogleGenAI inside the call with process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    // FIX: Using gemini-3-pro-preview for complex reasoning tasks
    const model = 'gemini-3-pro-preview';
    let userRequest = '';

    switch (analysisType) {
        case 'general':
            userRequest = "Provide a general fleet-wide analysis, including the holistic ranking of all vehicles as specified in the critical instructions. Conclude with an overall assessment of the fleet's health and provide high-level strategic recommendations.";
            break;
        case 'holistic_ranking':
            userRequest = "Perform a holistic ranking of all vehicles from best to worst, as specified in the critical instructions. The ranking must be the primary focus of the report. Provide a detailed justification for each vehicle's position, explaining its strengths and weaknesses based on the provided data.";
            break;
        case 'detailed':
            userRequest = "Provide a detailed report for each vehicle individually. Analyze its performance, costs, and efficiency, and provide specific recommendations for each one.";
            break;
        case 'specific':
            if (!options.vehicleId) throw new Error('Vehicle ID is required for specific report.');
            userRequest = `Provide a detailed performance and cost analysis exclusively for vehicle number ${options.vehicleId}. Compare its performance to the fleet average if possible.`;
            break;
        case 'comparison':
            if (!options.vehicleIds || options.vehicleIds.length < 2) throw new Error('At least two Vehicle IDs are required for comparison.');
            userRequest = `Directly compare the performance, costs, and efficiency of the following vehicles: ${options.vehicleIds.join(', ')}. Highlight the key differences and declare a winner for different categories (e.g., most cost-effective, highest workload).`;
            break;
        case 'best_worst':
            userRequest = "Identify the top 3 best-performing and bottom 3 worst-performing vehicles. Base your evaluation on a combination of key metrics, primarily cost per ton and total tons collected. Justify your selections with data and provide clear reasons.";
            break;
        case 'custom':
            if (!options.customPrompt) throw new Error('A custom prompt is required.');
            userRequest = options.customPrompt;
            break;
        default:
            throw new Error('Invalid analysis type');
    }

    const fullPrompt = `
        You are an expert fleet management analyst. Your task is to analyze waste management vehicle data for the Mu'tah and Al-Mazar Municipality.

        **CRITICAL INSTRUCTIONS:**
        1.  All responses MUST be in formal Arabic.
        2.  All numbers in your response MUST be English numerals (e.g., 123, 45.6, 2024).
        3.  **Holistic Ranking:** When requested to perform a general analysis or ranking, you MUST rank all vehicles from best to worst. This ranking must be holistic, considering a combination of all provided variables, not just one. Key factors to weigh include cost-effectiveness (cost_ton, cost_trip), productivity (tons, trips), and manufacturing year (year). Present the ranking clearly (e.g., a numbered list) and provide a justification for each vehicle's position, explaining its strengths and weaknesses.
        4.  Provide specific, testable, and actionable recommendations. For example, suggest reassigning specific vehicles to different zones if data supports it ("انقل الضاغطة 7 إلى المنطقة الشرقية لتحسين الاستغلال").
        5.  The data provides total costs. When you mention costs, clarify they are totals for the entire period covered by the data.
        6.  The data columns are: veh (vehicle number), area (work zone), drivers, year (year of manufacture), cap_m3 (capacity in cubic meters), cap_ton (theoretical capacity in tons), trips (total trips), tons (total tons collected), fuel (total fuel cost), maint (total maintenance cost), cost_trip (average cost per trip), cost_ton (average cost per ton).

        **VEHICLE DATA (in JSON format):**
        ${JSON.stringify(data, null, 2)}

        **USER REQUEST:**
        ${userRequest}
    `;

    // FIX: Using ai.models.generateContent with the model name and prompt directly
    const response = await ai.models.generateContent({
        model: model,
        contents: fullPrompt,
    });

    // FIX: Access .text property directly (not a method)
    return response.text || '';
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Trip, Vehicle, Fuel, Maintenance, Area, VehicleTableData, DriverStatsData } from './types';
import { CONFIG, MONTHS_ORDER } from './constants';
import { loadAllData } from './services/dataService';
import { generateFleetReport } from './services/geminiService';
import Header from './components/Header';
import KpiGrid from './components/KpiGrid';
import ChartSection from './components/ChartSection';
import TableSection from './components/TableSection';
import AiAnalysisSection from './components/AiAnalysisSection';
import UtilizationSection from './components/UtilizationSection';
import Loader from './components/Loader';
import AreaChartSection from './components/AreaChartSection';
import DriverStatsSection from './components/DriverStatsSection';

const App: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [tripsData, setTripsData] = useState<Trip[]>([]);
    const [vehiclesData, setVehiclesData] = useState<Vehicle[]>([]);
    const [fuelData, setFuelData] = useState<Fuel[]>([]);
    const [maintData, setMaintData] = useState<Maintenance[]>([]);
    const [areasData, setAreasData] = useState<Area[]>([]);

    const [selectedYear, setSelectedYear] = useState<string>('');
    const [comparisonYear, setComparisonYear] = useState<string>('');

    const [filters, setFilters] = useState<{ vehicles: Set<string>; months: Set<string> }>({
        vehicles: new Set(),
        months: new Set(),
    });
    const [isFiltering, setIsFiltering] = useState(false);

    const [aiReport, setAiReport] = useState<string>('');
    const [aiLoading, setAiLoading] = useState<boolean>(false);
    const [aiError, setAiError] = useState<string>('');

    const lineChartRef = useRef<HTMLDivElement>(null);
    const pieChartRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const { trips, vehicles, fuel, maint, areas } = await loadAllData();
                setTripsData(trips);
                setVehiclesData(vehicles);
                setFuelData(fuel);
                setMaintData(maint);
                setAreasData(areas);

                // استخراج السنوات المتاحة واختيار الأحدث تلقائياً
                const years = [...new Set(trips.map(t => t['السنة']).filter(Boolean))].sort().reverse();
                if (years.length > 0) {
                    setSelectedYear(years[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleYearChange = (year: string) => {
        setIsFiltering(true);
        setSelectedYear(year);
    };

    const handleComparisonYearChange = (year: string) => {
        setIsFiltering(true);
        setComparisonYear(year);
    };

    const handleFilterToggle = useCallback((type: 'vehicles' | 'months', value: string) => {
        setIsFiltering(true);
        setFilters(prev => {
            const newSet = new Set(prev[type]);
            if (newSet.has(value)) {
                newSet.delete(value);
            } else {
                newSet.add(value);
            }
            return { ...prev, [type]: newSet };
        });
    }, []);

    const resetFilters = useCallback(() => {
        setIsFiltering(true);
        setFilters({ vehicles: new Set(), months: new Set() });
        setComparisonYear('');
    }, []);

    const filteredTrips = useMemo(() => {
        let data = tripsData.filter(r => r['السنة'] === selectedYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, selectedYear, filters]);

    const comparisonTrips = useMemo(() => {
        if (!comparisonYear) return [];
        let data = tripsData.filter(r => r['السنة'] === comparisonYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, comparisonYear, filters]);

    useEffect(() => {
        if (isFiltering) {
            const timer = setTimeout(() => setIsFiltering(false), 300);
            return () => clearTimeout(timer);
        }
    }, [filteredTrips, isFiltering]);

    const allVehiclesList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort();
    }, [tripsData]);

    const getVehicleTableData = (trips: Trip[], year: string) => {
        const vehGroups: { [key: string]: { trips: number; tons: number; drivers: Set<string> } } = {};

        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!vehGroups[v]) vehGroups[v] = { trips: 0, tons: 0, drivers: new Set() };
            vehGroups[v].trips += 1;
            vehGroups[v].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['السائق']) vehGroups[v].drivers.add(r['السائق']);
        });

        return Object.keys(vehGroups).map(v => {
            const { trips, tons, drivers } = vehGroups[v];
            const vehRow = vehiclesData.find(x => x['رقم المركبة'] === v) || {};
            const areaRow = areasData.find(x => x['رقم المركبة'] === v && (x['السنة'] === year || !x['السنة'])) || {};
            const fuelRow = fuelData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const maintRow = maintData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};

            let fuel = 0;
            if(fuelRow) {
                const monthsToSum = filters.months.size > 0 ? Array.from(filters.months) : MONTHS_ORDER;
                monthsToSum.forEach(m => {
                    fuel += (Number(fuelRow[m as keyof Fuel]) || 0);
                });
            }

            const maint = Number(maintRow?.['كلفة الصيانة'] || 0);
            const cap_m3 = parseFloat(vehRow['سعة المركبة بالمتر المكعب'] || '0');
            const density = parseFloat(vehRow['كثافة التحميل'] || '0');
            const cap_ton = cap_m3 * density;
            const totalCost = fuel + maint;
            const cost_trip = trips ? totalCost / trips : 0;
            const cost_ton = tons ? totalCost / tons : 0;

            return {
                veh: v,
                area: areaRow['المنطقة'] || '',
                drivers: [...drivers].join(', '),
                year: vehRow['سنة التصنيع'] || '',
                cap_m3,
                cap_ton,
                trips,
                tons,
                fuel,
                maint,
                cost_trip,
                cost_ton,
            };
        });
    };

    const filteredVehicleTableData = useMemo<VehicleTableData[]>(() => 
        getVehicleTableData(filteredTrips, selectedYear), 
    [filteredTrips, vehiclesData, areasData, fuelData, maintData, filters.months, selectedYear]);

    const comparisonVehicleTableData = useMemo<VehicleTableData[]>(() => 
        comparisonYear ? getVehicleTableData(comparisonTrips, comparisonYear) : [], 
    [comparisonTrips, vehiclesData, areasData, fuelData, maintData, filters.months, comparisonYear]);

    const driverStatsData = useMemo<DriverStatsData[]>(() => {
        const driverGroups: { [key: string]: { trips: number; tons: number; vehicles: Set<string> } } = {};

        filteredTrips.forEach(r => {
            const driver = r['السائق'];
            if (!driver || driver.trim() === '') return;

            if (!driverGroups[driver]) {
                driverGroups[driver] = { trips: 0, tons: 0, vehicles: new Set() };
            }
            driverGroups[driver].trips += 1;
            driverGroups[driver].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['رقم المركبة']) {
                driverGroups[driver].vehicles.add(r['رقم المركبة']);
            }
        });

        return Object.entries(driverGroups).map(([driver, data]) => {
            const { trips, tons, vehicles } = data;
            const avgTonsPerTrip = trips > 0 ? tons / trips : 0;

            return {
                driver,
                trips,
                tons,
                avgTonsPerTrip,
                vehicles: [...vehicles].join(', '),
            };
        });
    }, [filteredTrips]);

    const areaDistributionData = useMemo(() => {
        const areaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                areaMap.set(a['رقم المركبة'], a['المنطقة']);
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = trip['رقم المركبة'];
            if (vehicleId) {
                const area = areaMap.get(vehicleId) || 'غير محدد';
                if (!tonsByArea[area]) {
                    tonsByArea[area] = 0;
                }
                tonsByArea[area] += (Number(trip['صافي التحميل'] || 0) / 1000);
            }
        });

        return Object.entries(tonsByArea)
            .map(([name, value]) => ({ name, value: Math.round(value) }))
            .sort((a, b) => b.value - a.value);

    }, [filteredTrips, areasData, selectedYear]);

    const handleGenerateReport = async (analysisType: string, options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }) => {
        setAiLoading(true);
        setAiError('');
        setAiReport('');
        try {
            const report = await generateFleetReport(filteredVehicleTableData, analysisType, options);
            setAiReport(report);
        } catch (err) {
            setAiError('حدث خطأ أثناء إنشاء التقرير. يرجى المحاولة مرة أخرى.');
            console.error(err);
        } finally {
            setAiLoading(false);
        }
    };


    if (loading) {
        return <Loader />;
    }

    return (
        <div className="bg-slate-50 text-slate-800 min-h-screen">
            <Header
                tripsData={tripsData}
                filters={filters}
                selectedYear={selectedYear}
                comparisonYear={comparisonYear}
                onYearChange={handleYearChange}
                onComparisonYearChange={handleComparisonYearChange}
                onFilterToggle={handleFilterToggle}
                onResetFilters={resetFilters}
            />
            <main className="container mx-auto p-4 md:p-6">
                <KpiGrid 
                    filteredTrips={filteredTrips} 
                    comparisonTrips={comparisonTrips}
                    fuelData={fuelData} 
                    maintData={maintData} 
                    filters={filters}
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    vehicleTableData={filteredVehicleTableData}
                    comparisonVehicleTableData={comparisonVehicleTableData}
                />

                <ChartSection 
                    data={filteredTrips} 
                    comparisonData={comparisonTrips}
                    isLoading={isFiltering} 
                    filters={filters} 
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    chartRef={lineChartRef} 
                />

                <AreaChartSection data={areaDistributionData} isLoading={isFiltering} filters={filters} chartRef={pieChartRef} />
                <TableSection tableData={filteredVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${selectedYear}`} />

                {comparisonYear && (
                    <TableSection tableData={comparisonVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${comparisonYear} (للمقارنة)`} />
                )}

                <DriverStatsSection tableData={driverStatsData} filters={filters} />
                <AiAnalysisSection
                    vehicles={allVehiclesList}
                    onGenerateReport={handleGenerateReport}
                    report={aiReport}
                    isLoading={aiLoading}
                    error={aiError}
                    filters={filters}
                />
                <UtilizationSection tableData={filteredVehicleTableData} filters={filters} />
            </main>
        </div>
    );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Trip } from '../types';

interface HeaderProps {
    tripsData: Trip[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    onYearChange: (year: string) => void;
    onComparisonYearChange: (year: string) => void;
    onFilterToggle: (type: 'vehicles' | 'months', value: string) => void;
    onResetFilters: () => void;
}

const FilterDropdown: React.FC<{
    buttonText: string;
    items: string[];
    selectedItems: Set<string> | string;
    onToggle: (item: string) => void;
    isSingle?: boolean;
    activeColor?: string;
}> = ({ buttonText, items, selectedItems, onToggle, isSingle = false, activeColor = 'bg-blue-700' }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isSelected = (item: string) => {
        if (isSingle) return selectedItems === item;
        return (selectedItems as Set<string>).has(item);
    };

    return (
        <div className="relative" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`px-4 py-2 border-none rounded-lg text-sm font-semibold cursor-pointer shadow-md transition hover:opacity-90 ${isSingle && selectedItems ? `${activeColor} text-white` : 'bg-white text-slate-800'}`}
            >
                {buttonText} {isSingle && selectedItems ? `: ${selectedItems}` : '▼'}
            </button>
            {isOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-xl z-10 max-h-64 overflow-y-auto p-2">
                    {items.map(item => (
                        <label key={item} className="flex items-center space-x-2 p-2 rounded-md hover:bg-slate-100 cursor-pointer">
                            <input
                                type={isSingle ? "radio" : "checkbox"}
                                name={isSingle ? "single-select" : undefined}
                                value={item}
                                checked={isSelected(item)}
                                onChange={() => {
                                    onToggle(item);
                                    if (isSingle) setIsOpen(false);
                                }}
                                className="form-checkbox h-4 w-4 text-blue-600 rounded"
                            />
                            <span className="text-sm text-slate-700">{item}</span>
                        </label>
                    ))}
                    {isSingle && selectedItems && (
                        <button 
                            onClick={() => { onToggle(''); setIsOpen(false); }}
                            className="w-full text-center p-2 text-xs text-red-500 hover:bg-red-50"
                        >
                            إلغاء التحديد
                        </button>
                    )}
                </div>
            )}
        </div>
    );
};

const Header: React.FC<HeaderProps> = ({ tripsData, filters, selectedYear, comparisonYear, onYearChange, onComparisonYearChange, onFilterToggle, onResetFilters }) => {
    const vehicles = useMemo(() => [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort(), [tripsData]);
    const months = useMemo(() => [...new Set(tripsData.map(r => (r['الشهر'] || '').toLowerCase()).filter(Boolean))], [tripsData]);
    const years = useMemo(() => [...new Set(tripsData.map(r => r['السنة']).filter(Boolean))].sort().reverse(), [tripsData]);

    const printKPIs = () => {
        const kpiElement = document.getElementById('kpi-grid');
        if (kpiElement) {
            const printWindow = window.open('', '', 'height=800,width=1000');
            if (!printWindow) {
                alert('Please allow popups to print the report.');
                return;
            }

            const today = new Date().toLocaleDateString('ar-EG-u-nu-latn', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });

            const kpiCardNodes = Array.from(kpiElement.children);
            let cardsHtml = '';
            kpiCardNodes.forEach(cardNode => {
                const valueNode = cardNode.querySelector('div:first-child');
                const labelNode = cardNode.querySelector('div:last-child');
                const iconNode = labelNode?.querySelector('span');

                const value = valueNode?.textContent || '';
                const icon = iconNode?.textContent || '';

                let label = '';
                if (labelNode) {
                    const labelClone = labelNode.cloneNode(true) as HTMLElement;
                    const iconClone = labelClone.querySelector('span');
                    if (iconClone) {
                        labelClone.removeChild(iconClone);
                    }
                    label = labelClone.textContent?.trim() || '';
                }

                const colorClass = valueNode?.className.split(' ').find(c => c.startsWith('text-')) || 'text-slate-800';

                cardsHtml += `
                    <div class="kpi-card">
                        <div class="kpi-value ${colorClass}">${value}</div>
                        <div class="kpi-label">
                            <span>${icon}</span>
                            ${label}
                        </div>
                    </div>
                `;
            });

            const printContent = `
                <html>
                <head>
                    <title>طباعة مؤشرات الأداء الرئيسية - ${selectedYear}</title>
                    <link rel="preconnect" href="https://fonts.googleapis.com">
                    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
                    <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap" rel="stylesheet">
                    <style>
                        body {
                            font-family: 'Cairo', sans-serif;
                            direction: rtl;
                            margin: 20px;
                            background-color: #fff;
                            -webkit-print-color-adjust: exact !important;
                            print-color-adjust: exact !important;
                        }
                        .print-header {
                            text-align: center;
                            margin-bottom: 25px;
                            border-bottom: 2px solid #333;
                            padding-bottom: 15px;
                        }
                        .print-header h1 {
                            font-size: 24px;
                            margin: 0;
                            color: #1e3a8a;
                        }
                        .print-header h2 {
                            font-size: 18px;
                            margin: 5px 0 0;
                            color: #4b5563;
                        }
                        .kpi-grid-container {
                            display: grid;
                            grid-template-columns: repeat(3, 1fr);
                            gap: 20px;
                            padding: 10px;
                        }
                        .kpi-card {
                            border: 1px solid #e5e7eb;
                            border-radius: 12px;
                            padding: 16px;
                            text-align: center;
                            background-color: #f9fafb;
                            box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
                            page-break-inside: avoid;
                        }
                        .kpi-value {
                            font-size: 28px;
                            font-weight: 700;
                            margin-bottom: 8px;
                        }
                        .kpi-label {
                            font-size: 14px;
                            font-weight: 600;
                            color: #374151;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            gap: 8px;
                        }
                        .kpi-label span {
                            font-size: 18px;
                        }
                        .text-blue-600 { color: #2563eb; }
                        .text-sky-500 { color: #0ea5e9; }
                        .text-orange-500 { color: #f97316; }
                        .text-red-600 { color: #dc2626; }
                        .text-green-600 { color: #16a34a; }
                        .text-pink-600 { color: #db2777; }
                        .text-purple-600 { color: #9333ea; }
                        .text-indigo-600 { color: #4f46e5; }
                        .text-teal-500 { color: #14b8a6; }
                        .text-amber-500 { color: #f59e0b; }
                        .text-slate-800 { color: #1e293b; }

                        @media print {
                            body { margin: 0; }
                            .print-header { margin: 20px; }
                            .kpi-grid-container { grid-template-columns: repeat(3, 1fr); margin: 20px; }
                        }
                    </style>
                </head>
                <body>
                    <div class="print-header">
                        <h1>مؤشرات الأداء لأسطول إدارة النفايات - سنة ${selectedYear}</h1>
                        <h2>بلدية مؤتة والمزار - ${today}</h2>
                    </div>
                    <div class="kpi-grid-container">
                        ${cardsHtml}
                    </div>
                </body>
                </html>
            `;
            printWindow.document.write(printContent);
            printWindow.document.close();
            setTimeout(() => {
                printWindow.print();
                printWindow.close();
            }, 500);
        }
    };

    return (
        <header className="bg-gradient-to-l from-blue-600 to-sky-500 text-white p-5 shadow-lg flex flex-col md:flex-row justify-between items-center gap-4">
            <div>
                <h1 className="text-xl md:text-2xl font-bold leading-tight">بيانات نقل النفايات</h1>
                <h2 className="text-lg md:text-xl font-semibold">بلدية مؤتة والمزار</h2>
            </div>
            <div className="flex flex-wrap items-center justify-center gap-2">
                <FilterDropdown
                    buttonText="السنة"
                    items={years}
                    selectedItems={selectedYear}
                    onToggle={onYearChange}
                    isSingle={true}
                    activeColor="bg-blue-800"
                />
                <FilterDropdown
                    buttonText="مقارنة مع"
                    items={years}
                    selectedItems={comparisonYear}
                    onToggle={onComparisonYearChange}
                    isSingle={true}
                    activeColor="bg-slate-700"
                />
                <div className="w-px h-8 bg-white/30 mx-2 hidden md:block"></div>
                <FilterDropdown
                    buttonText="المركبات"
                    items={vehicles}
                    selectedItems={filters.vehicles}
                    onToggle={(item) => onFilterToggle('vehicles', item)}
                />
                <FilterDropdown
                    buttonText="الأشهر"
                    items={months}
                    selectedItems={filters.months}
                    onToggle={(item) => onFilterToggle('months', item.toLowerCase())}
                />
                <button
                    onClick={onResetFilters}
                    className="px-3 py-2 border-none rounded-lg bg-red-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-red-600"
                >
                    إعادة تعيين
                </button>
                <button
                    onClick={printKPIs}
                    className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600"
                >
                    طباعة المؤشرات
                </button>
            </div>
        </header>
    );
};

export default Header;

