    area: string;
    population: number;
}

export interface VehicleTableData {
    veh: string;
    area: string;
    drivers: string;
    year: string;
    cap_m3: number;
    cap_ton: number;
    trips: number;
    tons: number;
    fuel: number;
    maint: number;
