import { Trip, Vehicle, Fuel, Maintenance, Area, Population } from '../types';
import { CONFIG } from '../constants';

async function fetchCSV<T>(url: string): Promise<T[]> {
    try {
        const response = await fetch(url);
        const text = await response.text();
        const lines = text.trim().split(/\r?\n/);
        if (lines.length < 2) return [];

        // استخدام Regex لفصل الأعمدة مع مراعاة الفواصل داخل علامات الاقتباس (مثل "12,500")
        const splitLine = (line: string) => {
            const result = line.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
            return result ? result.map(val => val.replace(/^"|"$/g, '').trim()) : line.split(",").map(v => v.trim());
        };

        const header = splitLine(lines.shift()!);

        return lines.map(line => {
            const values = splitLine(line);
            const obj: { [key: string]: string } = {};
            header.forEach((h, i) => {
                if (h) obj[h] = values[i] || "";
            });
            return obj as T;
        });
    } catch (error) {
        console.error("Error fetching CSV:", error);
        return [];
    }
}

export async function loadAllData() {
    const [trips, vehicles, fuel, maint, areas, rawPopulation] = await Promise.all([
        fetchCSV<Trip>(CONFIG.trips),
        fetchCSV<Vehicle>(CONFIG.vehicles),
        fetchCSV<Fuel>(CONFIG.fuel),
        fetchCSV<Maintenance>(CONFIG.maint),
        fetchCSV<Area>(CONFIG.areas),
        fetchCSV<any>(CONFIG.population)
    ]);

    // 1. طباعة أول 3 صفوف خام للتحقق من وصول البيانات وشكلها
    console.log("First 3 raw rows of Population CSV:", rawPopulation.slice(0, 3));

    // 2. معالجة بيانات السكان بمنطق تنظيف صارم
    const population: Population[] = rawPopulation.map(row => {
        const areaName = row['المنطقة'] || '';

        // المنطق الإلزامي المطلوب لتنظيف الأرقام
        const raw = row["عدد السكان"];
        const cleanedString = String(raw || '0')
            .replace(/,/g, '') // إزالة الفواصل
            .replace(/\s/g, '') // إزالة المسافات
            .replace(/"/g, ''); // إزالة علامات الاقتباس إن وجدت

        const popValue = Number(cleanedString);

