async function fetchCSV<T>(url: string): Promise<T[]> {
    const response = await fetch(url);
    const text = await response.text();
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) return [];
    const header = lines.shift()!.split(",");

    return lines.map(line => {
        const values = line.split(",");
        const obj: { [key: string]: string } = {};
        header.forEach((h, i) => {
            obj[h.trim()] = (values[i] || "").trim();
        });
        return obj as T;
    });
}

/**
 * وظيفة مساعدة لتقسيم سطر CSV مع مراعاة علامات الاقتباس
 */
function splitCsvLine(line: string): string[] {
    const values: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let char of line) {
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            values.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    values.push(current.trim());
    return values;
}

export async function loadAllData() {
    // جلب البيانات الأخرى بالطريقة التقليدية
    const [trips, vehicles, fuel, maint, areas] = await Promise.all([
        fetchCSV<Trip>(CONFIG.trips),
        fetchCSV<Vehicle>(CONFIG.vehicles),
        fetchCSV<Fuel>(CONFIG.fuel),
        fetchCSV<Maintenance>(CONFIG.maint),
        fetchCSV<Area>(CONFIG.areas),
    ]);

    // معالجة بيانات السكان بشكل مستقل ومنعزل (Isolated Logic)
    let population: Population[] = [];
    try {
        const popResponse = await fetch(CONFIG.population);
        const popText = await popResponse.text();
        const popLines = popText.trim().split(/\r?\n/);

        if (popLines.length >= 2) {
            // 1. استخراج العناوين والتأكد من شكلها
            const popHeader = splitCsvLine(popLines.shift()!).map(h => h.replace(/^"|"$/g, '').trim());

            const populationRows = popLines.map(line => {
                const values = splitCsvLine(line);
                const obj: any = {};
                popHeader.forEach((h, i) => {
                    obj[h] = (values[i] || "").replace(/^"|"$/g, '').trim();
                });
                return obj;
            });

            // سجلات التتبع الإلزامية
            console.log("Population CSV Headers:", popHeader);
            if (populationRows.length > 0) {
                console.log("Population Row Keys (Object.keys):", Object.keys(populationRows[0]));
                console.log("First 3 Population rows (Raw Data):", populationRows.slice(0, 3));
            }

            // 2. تحويل وتنظيف البيانات باستخدام المنطق المطلوب بدقة
            population = populationRows.map(row => {
                const raw = row["عدد السكان"];
                // المنطق الإلزامي لتحويل الرقم
                const popValue = Number(
                    String(raw)
                        .trim()
                        .replace(/,/g, '') // إزالة فواصل الآلاف
                        .replace(/\u00A0/g, '') // إزالة المسافات غير القابلة للكسر (non-breaking space)
                        .replace(/\s/g, '') // إزالة أي مسافات أخرى
                );

                if (isNaN(popValue)) {
                    console.warn("NaN population found in row:", row);
                }

                return {
                    area: String(row["المنطقة"] || "").trim(),
                    population: isNaN(popValue) ? 0 : popValue
                };
            }).filter(p => p.area !== "");

            // سجل التحقق النهائي
            const totalPop = population.reduce((sum, p) => sum + p.population, 0);
            console.log("TOTAL POPULATION (Final Calculated) =", totalPop);
        }
    } catch (error) {
        console.error("Critical error loading population data:", error);
    }

    return { trips, vehicles, fuel, maint, areas, population };
}

