        <CollapsibleSection title="تحليل الأجور المالية والرواتب">
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-4 mb-6">
                <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100">
                    <div className="text-xs text-emerald-600 font-bold mb-1">إجمالي فاتورة الرواتب</div>
                    <div className="text-2xl font-black text-emerald-700">{formatNumber(stats?.total)} د.أ</div>
                </div>
                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <div className="text-xs text-blue-600 font-bold mb-1">عدد العمال/الموظفين</div>
                    <div className="text-2xl font-black text-blue-700">{formatNumber(workers.length)} فرد</div>
                </div>
                <div className="bg-amber-50 p-4 rounded-xl border border-amber-100">
                    <div className="text-xs text-amber-600 font-bold mb-1">متوسط الرواتب</div>
                    <div className="text-2xl font-black text-amber-700">{formatNumber(stats?.avg, 1)} د.أ</div>
