                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 overflow-hidden">
                    <div className="text-xs text-slate-500 font-bold mb-1">توزيع الوظائف</div>
                    <div className="flex flex-wrap gap-1">
                        {stats && Object.entries(stats.roleGroups).map(([role, count]) => (
