interface SalaryAnalysisSectionProps {
    workers: Worker[];
    filters: { vehicles: Set<string>; months: Set<string> };
}

const SalaryAnalysisSection: React.FC<SalaryAnalysisSectionProps> = ({ workers, filters }) => {
    const [sortBy, setSortBy] = useState<keyof Worker>('salary');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const sortedData = useMemo(() => {
        const sorted = [...workers];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, 'ar');
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA; // التنازلي للأرقام
            }
            return 0;
        });
        return sorted;
    }, [workers, sortBy]);

    const stats = useMemo(() => {
        if (workers.length === 0) return null;
        const total = workers.reduce((sum, w) => sum + w.salary, 0);
        const avg = total / workers.length;

        // تجميع حسب الوظيفة
        const roleGroups: { [key: string]: number } = {};
        workers.forEach(w => {
            roleGroups[w.role] = (roleGroups[w.role] || 0) + 1;
        });

        return { total, avg, roleGroups };
