                </div>
                <div className="bg-amber-50 p-5 rounded-2xl border border-amber-100 shadow-sm transition-transform hover:scale-[1.01]">
                    <div className="flex items-center gap-2 mb-2">
                        <span className="text-xl">📊</span>
