// Declare Papa for global usage from script tag
declare var Papa: any;

async function fetchCSV<T>(url: string): Promise<T[]> {
    const response = await fetch(url);
    const text = await response.text();
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) return [];
    const header = lines.shift()!.split(",");

    return lines.map(line => {
        const values = line.split(",");
        const obj: { [key: string]: string } = {};
        header.forEach((h, i) => {
            obj[h.trim()] = (values[i] || "").trim();
        });
        return obj as T;
    });
}

/**
 * Helper to split CSV line considering quotes
 */
function splitCsvLine(line: string): string[] {
    const values: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let char of line) {
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            values.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    values.push(current.trim());
    return values;
}

/**
 * MANDATORY ISOLATED DATA-LOADING FUNCTION FOR WORKERS
 * Uses TSV delimiter as requested.
 */
export async function loadWorkersData(): Promise<Worker[]> {
    try {
        const response = await fetch(CONFIG.workers);
        const tsvText = await response.text();

        return new Promise((resolve) => {
            Papa.parse(tsvText, {
                header: true,
                delimiter: "\t", // CRITICAL FACT: TSV parsing
                skipEmptyLines: true,
                complete: (results: any) => {
                    const workerMap = new Map<string, Worker>();
                    let totalSalariesSum = 0;

                    results.data.forEach((row: any) => {
                        const name = String(row["الاسم"] || "").trim();
                        const role = String(row["الوظيفة"] || "").trim();
                        const area = String(row["المنطقة"] || "").trim();

                        // Strict Salary Parsing Logic (MANDATORY STEP 4)
                        const rawSalary = row["الراتب"];
                        const salary = Number(
                            String(rawSalary)
                                .replace(/[^\d.]/g, "")
                        );

                        // If salary is NaN (MANDATORY STEP 5)
                        if (isNaN(salary) && name !== "") {
                            console.log("NaN Salary detected for row:", row);
                        }

                        if (name && role) {
                            const workerObj: Worker = {
                                name,
                                role,
                                area,
                                salary: isNaN(salary) ? 0 : salary
                            };

                            // Deduplicate by name to reach the real staff count (81)
                            if (!workerMap.has(name) || (workerObj.salary > 0 && workerMap.get(name)!.salary === 0)) {
                                workerMap.set(name, workerObj);
                            }
                        }
                    });

                    const finalWorkers = Array.from(workerMap.values());
                    totalSalariesSum = finalWorkers.reduce((acc, curr) => acc + curr.salary, 0);

                    // MANDATORY LOGGING (STEP 7)
                    console.log("Total number of workers:", finalWorkers.length);
                    console.log("First worker object:", finalWorkers[0]);
                    console.log("Total salaries sum:", totalSalariesSum);

                    resolve(finalWorkers);
                },
                error: (err: any) => {
                    console.error("PapaParse error:", err);
                    resolve([]);
                }
            });
        });
    } catch (error) {
        console.error("Critical failure loading workers TSV:", error);
        return [];
    }
}

export async function loadAllData() {
    // Load standard fleet data
    const [trips, vehicles, fuel, maint, areas, workers] = await Promise.all([
        fetchCSV<Trip>(CONFIG.trips),
        fetchCSV<Vehicle>(CONFIG.vehicles),
        fetchCSV<Fuel>(CONFIG.fuel),
        fetchCSV<Maintenance>(CONFIG.maint),
        fetchCSV<Area>(CONFIG.areas),
        loadWorkersData() // Use the new isolated function
    ]);

    // Independent Population Processing
    let population: Population[] = [];
    try {
        const popResponse = await fetch(CONFIG.population);
        const popText = await popResponse.text();
        const popLines = popText.trim().split(/\r?\n/);

        if (popLines.length >= 2) {
            const popHeader = splitCsvLine(popLines.shift()!).map(h => h.replace(/^"|"$/g, '').trim());
            const populationRows = popLines.map(line => {
                const values = splitCsvLine(line);
                const obj: any = {};
                popHeader.forEach((h, i) => {
                    obj[h] = (values[i] || "").replace(/^"|"$/g, '').trim();
                });
                return obj;
            });

            population = populationRows.map(row => {
                const raw = row["عدد السكان"];
                const popValue = Number(String(raw).trim().replace(/,/g, '').replace(/\u00A0/g, '').replace(/\s/g, ''));
                return {
                    area: String(row["المنطقة"] || "").trim(),
                    population: isNaN(popValue) ? 0 : popValue
                };
            }).filter(p => p.area !== "");
        }
    } catch (error) {
        console.error("Error loading population:", error);
    }

    return { trips, vehicles, fuel, maint, areas, population, workers };
}

