// Declare Papa for global usage from script tag
declare var Papa: any;

async function fetchCSV<T>(url: string): Promise<T[]> {
    const response = await fetch(url);
    const text = await response.text();
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) return [];
    const header = lines.shift()!.split(",");

    return lines.map(line => {
        const values = line.split(",");
        const obj: { [key: string]: string } = {};
        header.forEach((h, i) => {
            obj[h.trim()] = (values[i] || "").trim();
        });
        return obj as T;
    });
}

/**
 * Helper to split CSV line considering quotes
 */
function splitCsvLine(line: string): string[] {
    const values: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let char of line) {
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            values.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    values.push(current.trim());
    return values;
}

/**
 * MANDATORY ISOLATED DATA-LOADING FUNCTION FOR WORKERS
 * Parses TSV using tab delimiter (\t).
 * Implements strict salary parsing and deduplication by name.
 */
export async function loadWorkersData(): Promise<Worker[]> {
    const url = "https://docs.google.com/spreadsheets/d/e/2PACX-1vSFzqaKeM6Il-c1ubOzGHSzDWgfbW3URTWvTcF76Xx3HP-W5o_SDRozUeO_v5z-xits7UFpNxjdfC3w/pub?gid=0&single=true&output=csv";

    try {
        const response = await fetch(url);
        const tsvText = await response.text();

        return new Promise((resolve) => {
            Papa.parse(tsvText, {
                header: true,
                delimiter: "\t", // CRITICAL: Must be tab-separated
                skipEmptyLines: true,
                complete: (results: any) => {
                    const workerMap = new Map<string, Worker>();

                    results.data.forEach((row: any) => {
                        // 4. Strict salary parsing logic (MANDATORY)
                        const rawSalary = row["الراتب"];
                        const salary = Number(
                            String(rawSalary)
                                .replace(/[^\d.]/g, "")
                        );

                        // 5. If salary is NaN (MANDATORY)
                        if (isNaN(salary) && (row["الاسم"] || row["الوظيفة"])) {
                            console.log("Full row with NaN salary detected:", row);
                        }

                        const name = row["الاسم"];
                        const role = row["الوظيفة"];
                        const area = row["المنطقة"];

                        if (name && role) {
                            const workerObj: Worker = {
                                name: String(name).trim(),
                                role: String(role).trim(),
                                area: String(area).trim(),
                                salary: isNaN(salary) ? 0 : salary
                            };

                            // Deduplication by name to reach the unique staff count of 81
                            // This ensures trip logs for the same person don't inflate the count.
                            if (!workerMap.has(workerObj.name) || (workerObj.salary > 0 && workerMap.get(workerObj.name)!.salary === 0)) {
                                workerMap.set(workerObj.name, workerObj);
                            }
                        }
                    });

                    const workersData = Array.from(workerMap.values());
                    const totalSalary = workersData.reduce((sum, w) => sum + w.salary, 0);

                    // 7. Mandatory Logs (MANDATORY)
                    console.log("Total number of workers:", workersData.length);
                    if (workersData.length > 0) {
                        console.log("First worker object:", workersData[0]);
                    }
                    console.log("Total salaries sum:", totalSalary);

                    resolve(workersData);
                },
                error: (err: any) => {
                    console.error("PapaParse failed:", err);
                    resolve([]);
                }
            });
        });
    } catch (error) {
        console.error("Critical error fetching workers data:", error);
        return [];
    }
}

export async function loadAllData() {
    // Load standard fleet data
    const [trips, vehicles, fuel, maint, areas, workers] = await Promise.all([
        fetchCSV<Trip>(CONFIG.trips),
        fetchCSV<Vehicle>(CONFIG.vehicles),
        fetchCSV<Fuel>(CONFIG.fuel),
        fetchCSV<Maintenance>(CONFIG.maint),
        fetchCSV<Area>(CONFIG.areas),
        loadWorkersData() // Use the new isolated function for workers
    ]);

    // Independent Population Processing
    let population: Population[] = [];
    try {
        const popResponse = await fetch(CONFIG.population);
        const popText = await popResponse.text();
        const popLines = popText.trim().split(/\r?\n/);

        if (popLines.length >= 2) {
            const popHeader = splitCsvLine(popLines.shift()!).map(h => h.replace(/^"|"$/g, '').trim());
            const populationRows = popLines.map(line => {
                const values = splitCsvLine(line);
                const obj: any = {};
                popHeader.forEach((h, i) => {
                    obj[h] = (values[i] || "").replace(/^"|"$/g, '').trim();
                });
                return obj;
            });

            population = populationRows.map(row => {
                const raw = row["عدد السكان"];
                const popValue = Number(String(raw).trim().replace(/,/g, '').replace(/\u00A0/g, '').replace(/\s/g, ''));
                return {
                    area: String(row["المنطقة"] || "").trim(),
                    population: isNaN(popValue) ? 0 : popValue
                };
            }).filter(p => p.area !== "");
        }
    } catch (error) {
        console.error("Error loading population:", error);
    }

    return { trips, vehicles, fuel, maint, areas, population, workers };
}

