// Declare Papa for global usage from script tag
declare var Papa: any;

async function fetchCSV<T>(url: string): Promise<T[]> {
    const response = await fetch(url);
    const text = await response.text();
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) return [];
    const header = lines.shift()!.split(",");

    return lines.map(line => {
        const values = line.split(",");
        const obj: { [key: string]: string } = {};
        header.forEach((h, i) => {
            obj[h.trim()] = (values[i] || "").trim();
        });
        return obj as T;
    });
}

/**
 * وظيفة مساعدة لتقسيم سطر CSV مع مراعاة علامات الاقتباس
 */
function splitCsvLine(line: string): string[] {
    const values: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let char of line) {
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            values.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    values.push(current.trim());
    return values;
}

/**
 * MANDATORY ISOLATED DATA-LOADING FUNCTION FOR WORKERS
 * Parses TSV using tab delimiter (\t).
 * Implements strict salary parsing and deduplication by name.
 */
export async function loadWorkersData(): Promise<Worker[]> {
    const url = "https://docs.google.com/spreadsheets/d/e/2PACX-1vSFzqaKeM6Il-c1ubOzGHSzDWgfbW3URTWvTcF76Xx3HP-W5o_SDRozUeO_v5z-xits7UFpNxjdfC3w/pub?gid=0&single=true&output=csv";

    try {
        const response = await fetch(url);
        const tsvText = await response.text();

        return new Promise((resolve) => {
            Papa.parse(tsvText, {
                header: true,
                delimiter: "\t", // CRITICAL: Must be tab-separated as per instructions
                skipEmptyLines: true,
                complete: (results: any) => {
                    const workerMap = new Map<string, Worker>();

                    results.data.forEach((row: any) => {
                        const rawName = row["الاسم"];
                        const rawRole = row["الوظيفة"];
                        const rawArea = row["المنطقة"];
                        const rawSalaryValue = row["الراتب"];

                        if (!rawName || !rawRole) return;

                        // 4. Strict salary parsing logic (MANDATORY)
                        let salary = Number(
                            String(rawSalaryValue)
                                .replace(/[^\d.]/g, "")
                        );

                        // 5. If salary is NaN (MANDATORY)
                        if (isNaN(salary)) {
                            console.log("Full row with NaN salary detected:", row);
                            salary = 0;
                        }

                        const name = String(rawName).trim();
                        const role = String(rawRole).trim();
                        const area = String(rawArea).trim();

                        const workerObj: Worker = {
                            name,
                            role,
                            area,
                            salary
                        };

                        // Deduplication by name to reach the unique staff count (81)
                        // This ensures that the multiple trip logs for the same person don't inflate the count.
                        if (!workerMap.has(name) || (workerObj.salary > 0 && workerMap.get(name)!.salary === 0)) {
                            workerMap.set(name, workerObj);
                        }
                    });

                    const finalWorkers = Array.from(workerMap.values());
                    const totalSalariesSum = finalWorkers.reduce((acc, curr) => acc + curr.salary, 0);

                    // 7. Mandatory Logs (MANDATORY)
                    console.log("Total number of workers:", finalWorkers.length);
                    if (finalWorkers.length > 0) {
                        console.log("First worker object:", finalWorkers[0]);
                    }
                    console.log("Total salaries sum:", totalSalariesSum);

                    resolve(finalWorkers);
                },
                error: (err: any) => {
                    console.error("PapaParse failed:", err);
                    resolve([]);
                }
            });
        });
    } catch (error) {
        console.error("Critical error fetching workers TSV:", error);
        return [];
    }
}

export async function loadAllData() {
    // جلب البيانات الأساسية
    const [trips, vehicles, fuel, maint, areas, workers] = await Promise.all([
        fetchCSV<Trip>(CONFIG.trips),
        fetchCSV<Vehicle>(CONFIG.vehicles),
        fetchCSV<Fuel>(CONFIG.fuel),
        fetchCSV<Maintenance>(CONFIG.maint),
        fetchCSV<Area>(CONFIG.areas),
        loadWorkersData() // Added the new isolated function call
    ]);

    // معالجة بيانات السكان بشكل مستقل ومنعزل (Isolated Logic)
    let population: Population[] = [];
    try {
        const popResponse = await fetch(CONFIG.population);
        const popText = await popResponse.text();
        const popLines = popText.trim().split(/\r?\n/);

        if (popLines.length >= 2) {
            // 1. استخراج العناوين والتأكد من شكلها
            const popHeader = splitCsvLine(popLines.shift()!).map(h => h.replace(/^"|"$/g, '').trim());

            const populationRows = popLines.map(line => {
                const values = splitCsvLine(line);
                const obj: any = {};
                popHeader.forEach((h, i) => {
                    obj[h] = (values[i] || "").replace(/^"|"$/g, '').trim();
                });
                return obj;
            });

            // سجلات التتبع الإلزامية
            console.log("Population CSV Headers:", popHeader);

            // 2. تحويل وتنظيف البيانات باستخدام المنطق المطلوب بدقة
            population = populationRows.map(row => {
                const raw = row["عدد السكان"];
                // المنطق الإلزامي لتحويل الرقم
                const popValue = Number(
                    String(raw)
                        .trim()
                        .replace(/,/g, '') // إزالة فواصل الآلاف
                        .replace(/\u00A0/g, '') // إزالة المسافات غير القابلة للكسر (non-breaking space)
                        .replace(/\s/g, '') // إزالة أي مسافات أخرى
                );

                if (isNaN(popValue)) {
                    console.warn("NaN population found in row:", row);
                }

                return {
                    area: String(row["المنطقة"] || "").trim(),
                    population: isNaN(popValue) ? 0 : popValue
                };
            }).filter(p => p.area !== "");

            // سجل التحقق النهائي
            const totalPop = population.reduce((sum, p) => sum + p.population, 0);
            console.log("TOTAL POPULATION (Final Calculated) =", totalPop);
        }
    } catch (error) {
        console.error("Critical error loading population data:", error);
    }

    return { trips, vehicles, fuel, maint, areas, population, workers };
}

// Utility function to format numbers
export const formatNumber = (num: number | undefined | null, digits: number = 0): string => {
    if (num === null || num === undefined || !isFinite(num)) return "—";
    return num.toLocaleString("en-US", {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
    });
};

