import React, { useMemo, useRef } from 'react';
import { Worker, VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { 
    PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend,
    BarChart, Bar, XAxis, YAxis, CartesianGrid
} from 'recharts';

interface FinancialManagementSectionProps {
    workers: Worker[];
    vehicleData: VehicleTableData[];
    selectedYear: string;
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6'];

const FinancialManagementSection: React.FC<FinancialManagementSectionProps> = ({ workers, vehicleData, selectedYear }) => {
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const financialSummary = useMemo(() => {
        const totalSalaries = workers.reduce((sum, w) => sum + w.salary, 0);
        const totalFuel = vehicleData.reduce((sum, v) => sum + v.fuel, 0);
        const totalMaint = vehicleData.reduce((sum, v) => sum + v.maint, 0);
        const totalTons = vehicleData.reduce((sum, v) => sum + v.tons, 0);

        const grandTotal = totalSalaries + totalFuel + totalMaint;
        const costPerTonOverall = totalTons > 0 ? grandTotal / totalTons : 0;

        return {
            totalSalaries,
            totalFuel,
            totalMaint,
            grandTotal,
            totalTons,
            costPerTonOverall,
            allocation: [
                { name: 'الرواتب السنوية', value: totalSalaries },
                { name: 'كلفة الوقود', value: totalFuel },
                { name: 'كلفة الصيانة', value: totalMaint }
            ]
        };
    }, [workers, vehicleData]);

    const areaFinancials = useMemo(() => {
        const areaMap = new Map<string, { fuel: number; maint: number; tons: number }>();

        vehicleData.forEach(v => {
            const area = v.area || 'غير محدد';
            const current = areaMap.get(area) || { fuel: 0, maint: 0, tons: 0 };
            areaMap.set(area, {
                fuel: current.fuel + v.fuel,
                maint: current.maint + v.maint,
                tons: current.tons + v.tons
            });
        });

        // توزيع الرواتب على المناطق بشكل تقريبي بناءً على منطقة عمل العامل
        const areaSalaries = new Map<string, number>();
        workers.forEach(w => {
            const area = w.area || 'غير محدد';
            areaSalaries.set(area, (areaSalaries.get(area) || 0) + w.salary);
        });

        const allAreas = Array.from(new Set([...areaMap.keys(), ...areaSalaries.keys()]));

        return allAreas.map(area => {
            const oper = areaMap.get(area) || { fuel: 0, maint: 0, tons: 0 };
            const salaries = areaSalaries.get(area) || 0;
            const total = oper.fuel + oper.maint + salaries;
            return {
                name: area,
                salaries,
                operational: oper.fuel + oper.maint,
                total,
                efficiency: oper.tons > 0 ? total / oper.tons : 0
            };
        }).sort((a, b) => b.total - a.total);
    }, [workers, vehicleData]);

    const formatCurrency = (val: number) => formatNumber(Math.round(val)) + ' د.أ';

    return (
        <CollapsibleSection title={`الإدارة المالية والتدقيق السنوي - سنة ${selectedYear}`} defaultOpen={false}>
            {/* المالية الكلية - KPIs */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-10">
                <div className="bg-gradient-to-br from-emerald-500 to-emerald-700 p-6 rounded-3xl shadow-lg text-white">
                    <div className="text-emerald-100 text-xs font-bold mb-2 opacity-80 text-right">إجمالي المصاريف السنوية</div>
                    <div className="text-3xl font-black">{formatCurrency(financialSummary.grandTotal)}</div>
                    <div className="mt-4 text-[10px] bg-white/20 p-2 rounded-xl text-center">تشمل الرواتب السنوية والوقود والصيانة</div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-blue-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة الطن المالية (شاملة)</div>
                    <div className="text-3xl font-black text-blue-600">{formatNumber(financialSummary.costPerTonOverall, 2)} <span className="text-sm font-normal text-slate-400">د.أ/طن</span></div>
                    <div className="mt-2 text-[10px] text-slate-500">إجمالي الميزانية السنوية ÷ إجمالي الأطنان</div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-amber-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة التشغيل (وقود + صيانة)</div>
                    <div className="text-3xl font-black text-amber-600">{formatCurrency(financialSummary.totalFuel + financialSummary.totalMaint)}</div>
                    <div className="mt-2 text-[10px] text-slate-500 text-center font-bold">
                        {Math.round(((financialSummary.totalFuel + financialSummary.totalMaint) / financialSummary.grandTotal) * 100)}% من الميزانية
                    </div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-indigo-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة الكادر (سنوي)</div>
                    <div className="text-3xl font-black text-indigo-600">{formatCurrency(financialSummary.totalSalaries)}</div>
                    <div className="mt-2 text-[10px] text-slate-500 text-center font-bold">
                        {Math.round((financialSummary.totalSalaries / financialSummary.grandTotal) * 100)}% من الميزانية
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
                {/* توزيع الميزانية */}
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 shadow-inner">
                    <h4 className="text-sm font-black text-slate-700 mb-6 text-right flex items-center justify-end gap-2">
                        توزيع بنود الميزانية السنوية
                        <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                    </h4>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={financialSummary.allocation}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={80}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {financialSummary.allocation.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip formatter={(val: number) => formatCurrency(val)} />
                                <Legend />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* كلفة المناطق */}
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 shadow-inner">
                    <h4 className="text-sm font-black text-slate-700 mb-6 text-right">مقارنة التكاليف السنوية حسب المناطق</h4>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={areaFinancials.slice(0, 5)} layout="vertical">
                                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                                <XAxis type="number" hide />
                                <YAxis dataKey="name" type="category" tick={{fontSize: 10, fontWeight: 700}} width={80} />
                                <Tooltip formatter={(val: number) => formatCurrency(val)} />
                                <Bar dataKey="total" fill="#4f46e5" radius={[0, 5, 5, 0]} barSize={20} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>

            {/* تفاصيل المناطق المالية */}
            <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-sm" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-50">
                        <tr>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase text-right pr-10">المنطقة</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">رواتب سنوية</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">تشغيل سنوي</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">إجمالي الإنفاق السنوي</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">الكلفة لكل طن</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {areaFinancials.map((area, idx) => (
                            <tr key={idx} className="hover:bg-slate-50 transition-colors">
                                <td className="p-4 font-bold text-slate-800 text-right pr-10">{area.name}</td>
                                <td className="p-4 text-slate-600">{formatCurrency(area.salaries)}</td>
                                <td className="p-4 text-slate-600">{formatCurrency(area.operational)}</td>
                                <td className="p-4 font-black text-emerald-700">{formatCurrency(area.total)}</td>
                                <td className="p-4 font-black text-blue-600">{formatNumber(area.efficiency, 1)} د.أ</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="mt-6 flex justify-end">
                <button 
                    onClick={() => printTable(tableContainerRef, 'التقرير المالي السنوي التفصيلي للمناطق', { vehicles: new Set(), months: new Set() })}
                    className="flex items-center gap-2 bg-slate-800 text-white px-6 py-2 rounded-xl text-xs font-bold hover:bg-slate-900 transition-all shadow-md"
                >
                    <span>🖨️</span>
                    طباعة التقرير المالي السنوي
                </button>
            </div>
        </CollapsibleSection>
    );
};

export default FinancialManagementSection;

import React, { useMemo, useRef, useState } from 'react';
import { Worker, VehicleTableData, Population } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
    ResponsiveContainer, Legend, Cell, ComposedChart, Line
} from 'recharts';

interface AreaIntelligenceSectionProps {
    workers: Worker[];
    vehicleData: VehicleTableData[];
    population: Population[];
    selectedYear: string;
}

const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#3b82f6'];

// القائمة المعتمدة للمناطق حسب طلب المستخدم
const ALLOWED_AREAS = ['الطيبة', 'مؤته', 'المزار', 'العراق', 'الهاشمية', 'سول', 'جعفر'];

const AreaIntelligenceSection: React.FC<AreaIntelligenceSectionProps> = ({ workers, vehicleData, population, selectedYear }) => {
    const tableContainerRef = useRef<HTMLDivElement>(null);
    const [activeMetric, setActiveMetric] = useState<'tons' | 'budget' | 'efficiency'>('tons');

    const areaAnalysis = useMemo(() => {
        const statsMap = new Map<string, any>();

        // تهيئة المناطق المعتمدة لضمان ظهورها حتى لو كانت البيانات صفرية
        ALLOWED_AREAS.forEach(area => {
            statsMap.set(area, { 
                name: area, 
                tons: 0, 
                trips: 0, 
                fuel: 0, 
                maint: 0, 
                workersCount: 0, 
                salaries: 0,
                population: 0,
                vehicles: new Set<string>() // تتبع أرقام الضاغطات الفريدة
            });
        });

        // 1. تجميع بيانات المركبات (أطنان، رحلات، وقود، صيانة) للمناطق المعتمدة فقط
        vehicleData.forEach(v => {
            let area = (v.area || '').trim();
            if (area === 'مؤتة') area = 'مؤته'; 

            if (ALLOWED_AREAS.includes(area)) {
                const current = statsMap.get(area);
                current.vehicles.add(v.veh); // إضافة رقم المركبة للطقم
                statsMap.set(area, {
                    ...current,
                    tons: current.tons + v.tons,
                    trips: current.trips + v.trips,
                    fuel: current.fuel + v.fuel,
                    maint: current.maint + v.maint,
                });
            }
        });

        // 2. إضافة بيانات العمال والرواتب للمناطق المعتمدة فقط
        workers.forEach(w => {
            let area = (w.area || '').trim();
            if (area === 'مؤتة') area = 'مؤته';

            if (ALLOWED_AREAS.includes(area)) {
                const current = statsMap.get(area);
                statsMap.set(area, {
                    ...current,
                    workersCount: current.workersCount + 1,
                    salaries: current.salaries + w.salary
                });
            }
        });

        // 3. إضافة بيانات السكان للمناطق المعتمدة فقط
        population.forEach(p => {
            let area = (p.area || '').trim();
            if (area === 'مؤتة') area = 'مؤته';

            if (ALLOWED_AREAS.includes(area)) {
                const current = statsMap.get(area);
                statsMap.set(area, { ...current, population: p.population });
            }
        });

        // 4. حساب المؤشرات النهائية
        return Array.from(statsMap.values()).map(item => {
            const operationalCost = item.fuel + item.maint;
            const totalBudget = operationalCost + item.salaries;
            const costPerTon = item.tons > 0 ? totalBudget / item.tons : 0;
            const tonsPerWorker = item.workersCount > 0 ? item.tons / item.workersCount : 0;
            const vehiclesCount = item.vehicles.size; // عدد الضاغطات الفريدة

            return {
                ...item,
                operationalCost,
                totalBudget,
                costPerTon,
                tonsPerWorker,
                vehiclesCount
            };
        }).sort((a, b) => b.tons - a.tons);
    }, [workers, vehicleData, population]);

    const topArea = useMemo(() => {
        if (!areaAnalysis.length) return null;
        return areaAnalysis.reduce((prev, current) => (prev.tons > current.tons) ? prev : current);
    }, [areaAnalysis]);

    const mostEfficient = useMemo(() => {
        if (!areaAnalysis.length) return null;
        const activeAreas = areaAnalysis.filter(a => a.tons > 1);
        if (activeAreas.length === 0) return null;
        return activeAreas.reduce((prev, current) => (prev.costPerTon < current.costPerTon) ? prev : current);
    }, [areaAnalysis]);

    const formatCurrency = (val: number) => formatNumber(Math.round(val)) + ' د.أ';

    return (
        <CollapsibleSection title={`تقرير مناطق بلدية مؤته والمزار - تحليل شامل ${selectedYear}`} defaultOpen={false}>
            {/* بطاقات التميز في المناطق */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white p-6 rounded-3xl shadow-xl border-r-8 border-indigo-500 relative overflow-hidden group">
                    <div className="absolute -left-4 -top-4 text-6xl opacity-10 group-hover:scale-110 transition-transform">🏆</div>
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-1 text-right">أعلى إنتاجية نفايات</div>
                    <div className="text-2xl font-black text-slate-800 text-right">{topArea?.name}</div>
                    <div className="text-indigo-600 font-bold text-sm text-right mt-1">{formatNumber(topArea?.tons || 0)} طن مرفوع</div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-xl border-r-8 border-emerald-500 relative overflow-hidden group">
                    <div className="absolute -left-4 -top-4 text-6xl opacity-10 group-hover:scale-110 transition-transform">💡</div>
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-1 text-right">الأكثر كفاءة مالية (كلفة/طن)</div>
                    <div className="text-2xl font-black text-slate-800 text-right">{mostEfficient?.name || '—'}</div>
                    <div className="text-emerald-600 font-bold text-sm text-right mt-1">
                        {mostEfficient ? `${formatNumber(mostEfficient.costPerTon, 1)} د.أ لكل طن` : 'لا توجد بيانات كافية'}
                    </div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-xl border-r-8 border-amber-500 relative overflow-hidden group">
                    <div className="absolute -left-4 -top-4 text-6xl opacity-10 group-hover:scale-110 transition-transform">👥</div>
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-1 text-right">أكبر كثافة كادر بشري</div>
                    <div className="text-2xl font-black text-slate-800 text-right">
                        {areaAnalysis.reduce((p, c) => (p.workersCount > c.workersCount) ? p : c, areaAnalysis[0])?.name}
                    </div>
                    <div className="text-amber-600 font-bold text-sm text-right mt-1">
                        {areaAnalysis.reduce((p, c) => (p.workersCount > c.workersCount) ? p : c, areaAnalysis[0])?.workersCount} موظف وعامل
                    </div>
                </div>
            </div>

            {/* الرسم البياني المقارن */}
            <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 mb-10 shadow-inner">
                <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setActiveMetric('tons')}
                            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${activeMetric === 'tons' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-500 hover:bg-slate-200'}`}
                        >
                            حسب الأطنان
                        </button>
                        <button 
                            onClick={() => setActiveMetric('budget')}
                            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${activeMetric === 'budget' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white text-slate-500 hover:bg-slate-200'}`}
                        >
                            حسب الميزانية
                        </button>
                        <button 
                            onClick={() => setActiveMetric('efficiency')}
                            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${activeMetric === 'efficiency' ? 'bg-amber-600 text-white shadow-lg' : 'bg-white text-slate-500 hover:bg-slate-200'}`}
                        >
                            كفاءة الموظف
                        </button>
                    </div>
                    <h4 className="text-sm font-black text-slate-700 flex items-center gap-2">
                        مقارنة الأداء في السبع مناطق المعتمدة
                        <span className="w-3 h-3 bg-indigo-500 rounded-full"></span>
                    </h4>
                </div>

                <div className="h-80 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={areaAnalysis}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                            <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 700}} axisLine={false} tickLine={false} />
                            <YAxis yAxisId="left" tick={{fontSize: 10}} axisLine={false} tickLine={false} />
