import React, { useState, useMemo, useRef } from 'react';
import { VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';

interface TableSectionProps {
    tableData: VehicleTableData[];
    filters: { vehicles: Set<string>; months: Set<string> };
    title?: string;
}

const TableSection: React.FC<TableSectionProps> = ({ tableData, filters, title = "جدول كفاءة المركبات" }) => {
    const [sortBy, setSortBy] = useState<keyof VehicleTableData>('tons');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const sortedData = useMemo(() => {
        const sorted = [...tableData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, 'ar');
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA;
            }
            return 0;
        });
        return sorted;
    }, [tableData, sortBy]);

    const totals = useMemo(() => {
        if (sortedData.length === 0) return null;
        const totalTrips = sortedData.reduce((s, r) => s + r.trips, 0);
        const totalTons = sortedData.reduce((s, r) => s + r.tons, 0);
        const totalFuel = sortedData.reduce((s, r) => s + r.fuel, 0);
        const totalMaint = sortedData.reduce((s, r) => s + r.maint, 0);
        const totalCost = totalFuel + totalMaint;

        const avgCostTrip = totalTrips > 0 ? totalCost / totalTrips : 0;
        const avgCostTon = totalTons > 0 ? totalCost / totalTons : 0;

        return { totalTrips, totalTons, totalFuel, totalMaint, avgCostTrip, avgCostTon };
    }, [sortedData]);

    const handlePrint = () => {
        printTable(tableContainerRef, title, filters);
    };

    const headers = [
        { key: 'veh', label: 'رقم المركبة' }, { key: 'area', label: 'المنطقة' },
        { key: 'drivers', label: 'السائق' }, { key: 'year', label: 'سنة التصنيع' },
        { key: 'cap_m3', label: 'السعة (م³)' }, { key: 'cap_ton', label: 'السعة النظرية (طن)' },
        { key: 'trips', label: 'عدد الرحلات' }, { key: 'tons', label: 'الوزن المنقول (طن)' },
        { key: 'fuel', label: 'كلفة الوقود' }, { key: 'maint', label: 'كلفة الصيانة' },
        { key: 'cost_trip', label: 'كلفة الرحلة' }, { key: 'cost_ton', label: 'كلفة الطن' },
    ];

    if (tableData.length === 0) return null;

    return (
        <CollapsibleSection title={title}>
             <div className="flex items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="tableSort" className="ml-2 font-semibold">ترتيب حسب:</label>
                    <select id="tableSort" value={sortBy} onChange={e => setSortBy(e.target.value as keyof VehicleTableData)}
                        className="p-2 border border-slate-300 rounded-lg">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    طباعة الجدول
                </button>
            </div>
            <div className="overflow-x-auto" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-100">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-2 border-b border-slate-200 font-semibold text-slate-600">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody>
                        {sortedData.map(row => (
                            <tr key={row.veh} className="hover:bg-slate-50">
                                <td className="p-2 border-b border-slate-200 font-bold">{row.veh}</td>
                                <td className="p-2 border-b border-slate-200">{row.area}</td>
                                <td className={`p-2 border-b border-slate-200 ${row.drivers.includes(',') ? 'text-xs' : ''}`}>{row.drivers}</td>
                                <td className="p-2 border-b border-slate-200">{row.year}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.cap_m3, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.cap_ton, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.trips)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.tons, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.fuel, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.maint, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-semibold text-blue-600">{formatNumber(row.cost_trip, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-semibold text-blue-600">{formatNumber(row.cost_ton, 1)}</td>
                            </tr>
                        ))}
                        {totals && (
                            <tr className="font-bold bg-slate-200">
                                <td className="p-2 border-b border-slate-300">الإجمالي/المتوسط</td>
                                <td colSpan={5} className="p-2 border-b border-slate-300"></td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalTrips)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalTons, 1)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalFuel, 1)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalMaint, 1)}</td>
                                <td className="p-2 border-b border-slate-300 text-blue-700">{formatNumber(totals.avgCostTrip, 1)}</td>
                                <td className="p-2 border-b border-slate-300 text-blue-700">{formatNumber(totals.avgCostTon, 1)}</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

export default TableSection;

import React, { useState } from 'react';
import CollapsibleSection from './CollapsibleSection';
import { printAiReport } from '../services/printService';

interface AiAnalysisSectionProps {
    vehicles: string[];
    onGenerateReport: (analysisType: string, options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }) => void;
    report: string;
    isLoading: boolean;
    error: string;
    filters: { vehicles: Set<string>; months: Set<string> };
}

const AiAnalysisSection: React.FC<AiAnalysisSectionProps> = ({ vehicles, onGenerateReport, report, isLoading, error, filters }) => {
    const [analysisType, setAnalysisType] = useState('general');
    const [specificVehicle, setSpecificVehicle] = useState(vehicles[0] || '');
    const [comparisonVehicles, setComparisonVehicles] = useState<string[]>([]);
    const [customPrompt, setCustomPrompt] = useState('');

    const handleGenerateClick = () => {
        const options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string } = {};
        if (analysisType === 'specific') {
            options.vehicleId = specificVehicle;
        } else if (analysisType === 'comparison') {
            if (comparisonVehicles.length < 2) {
                alert("يرجى اختيار مركبتين على الأقل للمقارنة.");
                return;
            }
            options.vehicleIds = comparisonVehicles;
        } else if (analysisType === 'custom') {
            if (!customPrompt.trim()) {
                alert("يرجى إدخال طلب مخصص.");
                return;
            }
            options.customPrompt = customPrompt;
        }
        onGenerateReport(analysisType, options);
    };

    const handleComparisonChange = (vehicle: string) => {
        setComparisonVehicles(prev =>
            prev.includes(vehicle) ? prev.filter(v => v !== vehicle) : [...prev, vehicle]
        );
    };

    const printReport = () => {
        if (!report || !report.trim()) {
            alert('لا يوجد تقرير لطباعته.');
            return;
        }
        printAiReport(
            report, 
            'تقرير تحليل الأسطول بالذكاء الاصطناعي', 
            filters
        );
    };

    return (
        <CollapsibleSection title="تحليل الأسطول بالذكاء الاصطناعي">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Controls */}
                <div className="md:col-span-1 space-y-4">
                    <h3 className="font-bold text-md text-slate-700">خيارات التحليل</h3>

                    <div>
                        <label className="block text-sm font-medium text-slate-600 mb-1">نوع التحليل:</label>
                        <select
                            value={analysisType}
                            onChange={(e) => setAnalysisType(e.target.value)}
                            className="w-full p-2 border border-slate-300 rounded-lg bg-white"
                        >
                            <option value="general">تحليل عام للأسطول</option>
                            <option value="holistic_ranking">تصنيف شامل للمركبات</option>
                            <option value="detailed">تقرير مفصل لكل مركبة</option>
                            <option value="specific">تقرير لمركبة محددة</option>
                            <option value="comparison">مقارنة بين مركبات</option>
                            <option value="best_worst">تحديد أفضل وأسوأ المركبات</option>
                            <option value="custom">طلب مخصص</option>
                        </select>
                    </div>

                    {analysisType === 'specific' && (
                        <div>
                            <label className="block text-sm font-medium text-slate-600 mb-1">اختر مركبة:</label>
                            <select
                                value={specificVehicle}
                                onChange={(e) => setSpecificVehicle(e.target.value)}
                                className="w-full p-2 border border-slate-300 rounded-lg bg-white"
                            >
                                {vehicles.map(v => <option key={v} value={v}>{v}</option>)}
                            </select>
                        </div>
                    )}

                    {analysisType === 'comparison' && (
                        <div>
                            <label className="block text-sm font-medium text-slate-600 mb-1">اختر المركبات للمقارنة:</label>
                            <div className="max-h-40 overflow-y-auto border border-slate-300 rounded-lg p-2 bg-white">
                                {vehicles.map(v => (
                                    <label key={v} className="flex items-center space-x-2 p-1">
                                        <input type="checkbox" checked={comparisonVehicles.includes(v)} onChange={() => handleComparisonChange(v)} />
                                        <span>{v}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                    )}

                    {analysisType === 'custom' && (
                        <div>
                            <label className="block text-sm font-medium text-slate-600 mb-1">اكتب طلبك:</label>
                            <textarea
                                value={customPrompt}
                                onChange={(e) => setCustomPrompt(e.target.value)}
                                rows={4}
                                placeholder="مثال: قم بتحليل أسباب ارتفاع تكلفة الطن في المركبات القديمة..."
                                className="w-full p-2 border border-slate-300 rounded-lg bg-white"
                            ></textarea>
                        </div>
                    )}

                    <button
                        onClick={handleGenerateClick}
                        disabled={isLoading}
                        className="w-full px-4 py-3 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 disabled:bg-slate-400 transition"
                    >
                        {isLoading ? 'جاري التحليل...' : 'تشغيل التحليل'}
                    </button>
                </div>

                {/* Report Display */}
                <div className="md:col-span-2">
                     <div className="flex justify-between items-center mb-2">
                        <h3 className="font-bold text-md text-slate-700">التقرير</h3>
                        {report && !isLoading && (
                            <button onClick={printReport} className="px-3 py-1.5 bg-emerald-500 text-white text-sm font-semibold rounded-lg hover:bg-emerald-600">
                                طباعة التقرير
                            </button>
                        )}
                    </div>
                    <div className="h-96 bg-slate-100 border border-slate-200 rounded-lg p-4 overflow-y-auto">
                        {isLoading && <div className="flex items-center justify-center h-full text-slate-600">يتم الآن إنشاء التقرير...</div>}
                        {error && <div className="text-red-600">{error}</div>}
                        {report && !isLoading && (
                            <div>
                                <pre className="whitespace-pre-wrap word-wrap break-words font-sans text-base leading-relaxed">{report}</pre>
                            </div>
                        )}
                         {!isLoading && !error && !report && <div className="flex items-center justify-center h-full text-slate-500">سيظهر التقرير هنا بعد تشغيل التحليل.</div>}
                    </div>
                </div>
            </div>
        </CollapsibleSection>
    );
};

export default AiAnalysisSection;

import React, { useState, useMemo, useRef } from 'react';
import { Worker } from '../types';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
    ResponsiveContainer, Cell
} from 'recharts';

interface SalaryAnalysisSectionProps {
    workers: Worker[];
}

const COLORS = ['#4f46e5', '#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const SalaryAnalysisSection: React.FC<SalaryAnalysisSectionProps> = ({ workers }) => {
    const [analysisMode, setAnalysisMode] = useState<'all' | 'job' | 'area'>('all');
    const [searchTerm, setSearchTerm] = useState('');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    // Search filter
    const filteredWorkers = useMemo(() => {
        return workers.filter(w => 
            w.name.includes(searchTerm) || 
            w.role.includes(searchTerm) || 
            w.area.includes(searchTerm)
        );
    }, [workers, searchTerm]);

    // Job Stats
    const jobStats = useMemo(() => {
        const map = new Map<string, { count: number; total: number }>();
        filteredWorkers.forEach(w => {
            const stats = map.get(w.role) || { count: 0, total: 0 };
            stats.count++;
            stats.total += w.salary;
            map.set(w.role, stats);
        });
        return Array.from(map.entries()).map(([name, data]) => ({
            name,
            count: data.count,
            total: data.total,
            avg: data.total / data.count
        })).sort((a, b) => b.total - a.total);
    }, [filteredWorkers]);

    // Area Stats
    const areaStats = useMemo(() => {
        const map = new Map<string, { count: number; total: number; roles: Map<string, number> }>();
        filteredWorkers.forEach(w => {
            const area = w.area || 'غير محدد';
            const stats = map.get(area) || { count: 0, total: 0, roles: new Map() };
            stats.count++;
            stats.total += w.salary;

            const roleCount = stats.roles.get(w.role) || 0;
            stats.roles.set(w.role, roleCount + 1);

            map.set(area, stats);
        });
        return Array.from(map.entries()).map(([name, data]) => ({
            name,
            count: data.count,
            total: data.total,
            avg: data.total / data.count,
            rolesBreakdown: Array.from(data.roles.entries())
                .map(([role, count]) => `${role} (${count})`)
                .join('، ')
        })).sort((a, b) => b.total - a.total);
    }, [filteredWorkers]);

    const overallStats = useMemo(() => {
        const count = filteredWorkers.length;
        const total = filteredWorkers.reduce((sum, w) => sum + w.salary, 0);
        const avg = count > 0 ? total / count : 0;
        return { count, total, avg };
    }, [filteredWorkers]);

    const formatCurrency = (val: number) => {
        return val.toLocaleString("en-US", {
            minimumFractionDigits: 0,
            maximumFractionDigits: 0
        });
    };

    const handlePrint = () => {
        const titles = {
            all: 'كشف الأجور السنوي التفصيلي',
            job: 'تحليل الأجور السنوية حسب الوظيفة',
            area: 'تحليل الأجور السنوية حسب المنطقة'
        };
        printTable(tableContainerRef, titles[analysisMode], { vehicles: new Set(), months: new Set() });
    };

    if (workers.length === 0) return null;

    return (
        <CollapsibleSection title="تحليل الميزانية السنوية للأجور">
            {/* Controls */}
            <div className="flex flex-wrap gap-4 mb-8 bg-slate-50 p-6 rounded-3xl border border-slate-100 items-end shadow-inner text-right">
                <div className="flex flex-col gap-1.5">
                    <label className="text-xs font-black text-slate-500 mr-1">تحليل حسب:</label>
                    <select 
                        value={analysisMode} 
                        onChange={(e) => setAnalysisMode(e.target.value as any)}
                        className="bg-white border-2 border-indigo-100 rounded-2xl p-3 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 min-w-[220px] transition-all"
                    >
                        <option value="all">كافة الموظفين</option>
                        <option value="job">حسب المسمى الوظيفي</option>
                        <option value="area">حسب المنطقة</option>
                    </select>
                </div>

                <div className="flex flex-col gap-1.5">
                    <label className="text-xs font-black text-slate-500 mr-1">بحث سريع:</label>
                    <input 
                        type="text"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder="ابحث بالاسم، الوظيفة أو المنطقة..."
                        className="bg-white border-2 border-slate-100 rounded-2xl p-3 text-sm outline-none focus:ring-2 focus:ring-blue-500 min-w-[300px] transition-all text-right"
                    />
                </div>

                <div className="flex flex-1 justify-end">
                    <button 
                        onClick={handlePrint} 
                        className="px-8 py-3 bg-slate-800 text-white rounded-2xl text-sm font-bold shadow-lg hover:bg-slate-900 transition-all active:scale-95 flex items-center gap-2"
                    >
                        <span>🖨️</span>
                        طباعة الكشف السنوي
                    </button>
                </div>
            </div>

            {/* KPIs */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-10">
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-indigo-600 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-indigo-600 transition-colors text-right">إجمالي عدد الكادر</div>
                    <div className="text-5xl font-black text-slate-800 flex items-baseline gap-2 justify-end">
                        <span className="text-sm font-normal text-slate-400">عامل</span>
                        {overallStats.count.toLocaleString()}
                    </div>
                </div>
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-emerald-500 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-emerald-600 transition-colors text-right">إجمالي الميزانية السنوية</div>
                    <div className="text-5xl font-black text-emerald-600 flex items-baseline gap-2 justify-end">
                        <span className="text-sm font-normal text-slate-400 italic">د.أ</span>
                        {formatCurrency(overallStats.total)}
                    </div>
                </div>
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-blue-500 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-blue-600 transition-colors text-right">متوسط الراتب السنوي</div>
                    <div className="text-5xl font-black text-blue-600 flex items-baseline gap-2 justify-end">
                        <span className="text-sm font-normal text-slate-400 italic">د.أ</span>
                        {formatCurrency(overallStats.avg)}
                    </div>
                </div>
            </div>

            {/* Distribution Charts */}
            {analysisMode !== 'all' && (
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 mb-10 shadow-inner">
                    <h4 className="text-sm font-black text-slate-700 mb-8 flex items-center gap-2 text-right">
                        <span className="w-3 h-3 bg-emerald-500 rounded-full"></span>
                        {analysisMode === 'job' ? 'توزيع الميزانية السنوية حسب الوظائف' : 'توزيع الميزانية السنوية حسب المناطق'}
                    </h4>
                    <div className="h-80 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart 
                                data={analysisMode === 'job' ? jobStats : areaStats}
                                margin={{ left: 20, right: 30, top: 10, bottom: 20 }}
                            >
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} axisLine={false} tickLine={false} />
                                <YAxis tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                                <Tooltip 
                                    cursor={{fill: '#f1f5f9'}}
                                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', textAlign: 'right' }}
                                />
                                <Bar dataKey="total" radius={[8, 8, 0, 0]} barSize={40}>
                                    {(analysisMode === 'job' ? jobStats : areaStats).map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Bar>
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            )}

            {/* Data Table */}
            <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-sm" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-50">
                        {analysisMode === 'all' ? (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">اسم الموظف</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">المسمى الوظيفي</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">المنطقة</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">الراتب السنوي (د.أ)</th>
                            </tr>
                        ) : analysisMode === 'job' ? (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">المسمى الوظيفي</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">عدد الموظفين</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">إجمالي الرواتب السنوية</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">متوسط الأجر السنوي</th>
                            </tr>
                        ) : (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">المنطقة</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">عدد العمال</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right">المسميات الوظيفية</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">إجمالي الرواتب السنوية</th>
                            </tr>
                        )}
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {analysisMode === 'all' && filteredWorkers.map((worker, idx) => (
                            <tr key={`${worker.name}-${idx}`} className="hover:bg-indigo-50/30 transition-colors">
                                <td className="p-5 font-bold text-slate-800 text-right pr-14">{worker.name}</td>
                                <td className="p-5">
                                    <span className="bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-xl text-[10px] font-black border border-indigo-100 shadow-sm uppercase">
                                        {worker.role}
                                    </span>
                                </td>
                                <td className="p-5 text-slate-500 font-medium">{worker.area}</td>
                                <td className="p-5 font-black text-emerald-700 text-lg">
                                    {formatCurrency(worker.salary)}
                                </td>
                            </tr>
                        ))}

                        {analysisMode === 'job' && jobStats.map((item, idx) => (
                            <tr key={`${item.name}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                <td className="p-5 font-black text-slate-800 text-right pr-14">{item.name}</td>
                                <td className="p-5 font-bold text-slate-600">{item.count}</td>
                                <td className="p-5 font-black text-emerald-700">{formatCurrency(item.total)} د.أ</td>
                                <td className="p-5 font-black text-blue-600">{formatCurrency(item.avg)} د.أ</td>
                            </tr>
                        ))}

                        {analysisMode === 'area' && areaStats.map((item, idx) => (
                            <tr key={`${item.name}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                <td className="p-5 font-black text-slate-800 text-right pr-14">{item.name}</td>
                                <td className="p-5 font-bold text-slate-600">{item.count}</td>
                                <td className="p-5 text-right">
                                    <div className="flex flex-wrap gap-1 justify-end">
                                        {item.rolesBreakdown.split('، ').map((role, rIdx) => (
                                            <span key={rIdx} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-md border border-slate-200">
                                                {role}
                                            </span>
                                        ))}
                                    </div>
                                </td>
                                <td className="p-5 font-black text-emerald-700">{formatCurrency(item.total)} د.أ</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="mt-8 p-6 bg-blue-50/50 rounded-3xl border-r-8 border-blue-400 text-[12px] text-blue-900 leading-relaxed font-bold text-right shadow-sm">
                * جميع الرواتب المعروضة هي رواتب سنوية (إجمالي 12 شهراً). يعتمد التحليل على كشف الرواتب الموحد لبلدية مؤتة والمزار (GID=386592046) مع تحويل القيم الشهرية إلى سنوية لضمان دقة التقارير الإجمالية وكفاءة الإنفاق لكل طن.
            </div>
        </CollapsibleSection>
    );
};

export default SalaryAnalysisSection;

import React, { useMemo, useRef } from 'react';
import { Worker, VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { 
    PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend,
    BarChart, Bar, XAxis, YAxis, CartesianGrid
} from 'recharts';

interface FinancialManagementSectionProps {
    workers: Worker[];
    vehicleData: VehicleTableData[];
    selectedYear: string;
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6'];

const FinancialManagementSection: React.FC<FinancialManagementSectionProps> = ({ workers, vehicleData, selectedYear }) => {
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const financialSummary = useMemo(() => {
        const totalSalaries = workers.reduce((sum, w) => sum + w.salary, 0);
        const totalFuel = vehicleData.reduce((sum, v) => sum + v.fuel, 0);
        const totalMaint = vehicleData.reduce((sum, v) => sum + v.maint, 0);
        const totalTons = vehicleData.reduce((sum, v) => sum + v.tons, 0);

        const grandTotal = totalSalaries + totalFuel + totalMaint;
        const costPerTonOverall = totalTons > 0 ? grandTotal / totalTons : 0;

        return {
            totalSalaries,
            totalFuel,
            totalMaint,
            grandTotal,
            totalTons,
            costPerTonOverall,
            allocation: [
                { name: 'الرواتب السنوية', value: totalSalaries },
                { name: 'كلفة الوقود', value: totalFuel },
                { name: 'كلفة الصيانة', value: totalMaint }
            ]
        };
    }, [workers, vehicleData]);

    const areaFinancials = useMemo(() => {
        const areaMap = new Map<string, { fuel: number; maint: number; tons: number }>();

        vehicleData.forEach(v => {
            const area = v.area || 'غير محدد';
            const current = areaMap.get(area) || { fuel: 0, maint: 0, tons: 0 };
            areaMap.set(area, {
                fuel: current.fuel + v.fuel,
                maint: current.maint + v.maint,
                tons: current.tons + v.tons
            });
        });

        // توزيع الرواتب على المناطق بشكل تقريبي بناءً على منطقة عمل العامل
        const areaSalaries = new Map<string, number>();
        workers.forEach(w => {
            const area = w.area || 'غير محدد';
            areaSalaries.set(area, (areaSalaries.get(area) || 0) + w.salary);
        });

        const allAreas = Array.from(new Set([...areaMap.keys(), ...areaSalaries.keys()]));

        return allAreas.map(area => {
            const oper = areaMap.get(area) || { fuel: 0, maint: 0, tons: 0 };
            const salaries = areaSalaries.get(area) || 0;
            const total = oper.fuel + oper.maint + salaries;
            return {
                name: area,
                salaries,
                operational: oper.fuel + oper.maint,
                total,
                efficiency: oper.tons > 0 ? total / oper.tons : 0
            };
        }).sort((a, b) => b.total - a.total);
    }, [workers, vehicleData]);

    const formatCurrency = (val: number) => formatNumber(Math.round(val)) + ' د.أ';

    return (
        <CollapsibleSection title={`الإدارة المالية والتدقيق السنوي - سنة ${selectedYear}`}>
            {/* المالية الكلية - KPIs */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-10">
                <div className="bg-gradient-to-br from-emerald-500 to-emerald-700 p-6 rounded-3xl shadow-lg text-white">
                    <div className="text-emerald-100 text-xs font-bold mb-2 opacity-80 text-right">إجمالي المصاريف السنوية</div>
                    <div className="text-3xl font-black">{formatCurrency(financialSummary.grandTotal)}</div>
                    <div className="mt-4 text-[10px] bg-white/20 p-2 rounded-xl text-center">تشمل الرواتب السنوية والوقود والصيانة</div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-blue-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة الطن المالية (شاملة)</div>
                    <div className="text-3xl font-black text-blue-600">{formatNumber(financialSummary.costPerTonOverall, 2)} <span className="text-sm font-normal text-slate-400">د.أ/طن</span></div>
                    <div className="mt-2 text-[10px] text-slate-500">إجمالي الميزانية السنوية ÷ إجمالي الأطنان</div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-amber-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة التشغيل (وقود + صيانة)</div>
                    <div className="text-3xl font-black text-amber-600">{formatCurrency(financialSummary.totalFuel + financialSummary.totalMaint)}</div>
                    <div className="mt-2 text-[10px] text-slate-500 text-center font-bold">
                        {Math.round(((financialSummary.totalFuel + financialSummary.totalMaint) / financialSummary.grandTotal) * 100)}% من الميزانية
                    </div>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-md border-b-4 border-indigo-500">
                    <div className="text-slate-400 text-xs font-bold mb-2 text-right">كلفة الكادر (سنوي)</div>
                    <div className="text-3xl font-black text-indigo-600">{formatCurrency(financialSummary.totalSalaries)}</div>
                    <div className="mt-2 text-[10px] text-slate-500 text-center font-bold">
                        {Math.round((financialSummary.totalSalaries / financialSummary.grandTotal) * 100)}% من الميزانية
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
                {/* توزيع الميزانية */}
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 shadow-inner">
                    <h4 className="text-sm font-black text-slate-700 mb-6 text-right flex items-center justify-end gap-2">
                        توزيع بنود الميزانية السنوية
                        <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                    </h4>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={financialSummary.allocation}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={80}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {financialSummary.allocation.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip formatter={(val: number) => formatCurrency(val)} />
                                <Legend />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* كلفة المناطق */}
                <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 shadow-inner">
                    <h4 className="text-sm font-black text-slate-700 mb-6 text-right">مقارنة التكاليف السنوية حسب المناطق</h4>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={areaFinancials.slice(0, 5)} layout="vertical">
                                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                                <XAxis type="number" hide />
                                <YAxis dataKey="name" type="category" tick={{fontSize: 10, fontWeight: 700}} width={80} />
                                <Tooltip formatter={(val: number) => formatCurrency(val)} />
                                <Bar dataKey="total" fill="#4f46e5" radius={[0, 5, 5, 0]} barSize={20} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>

            {/* تفاصيل المناطق المالية */}
            <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-sm" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-50">
                        <tr>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase text-right pr-10">المنطقة</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">رواتب سنوية</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">تشغيل سنوي</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">إجمالي الإنفاق السنوي</th>
                            <th className="p-4 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase">الكلفة لكل طن</th>
                        </tr>
                    </thead>
