import React, { useState, useMemo, useRef } from 'react';
import { Worker } from '../types';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
    ResponsiveContainer, Cell
} from 'recharts';

interface SalaryAnalysisSectionProps {
    workers: Worker[];
}

const COLORS = ['#4f46e5', '#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const SalaryAnalysisSection: React.FC<SalaryAnalysisSectionProps> = ({ workers }) => {
    const { t } = useLanguage();
    const [analysisMode, setAnalysisMode] = useState<'all' | 'job' | 'area'>('all');
    const [searchTerm, setSearchTerm] = useState('');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const roleMapping: {[key: string]: string} = {
        'سائق': t('role_driver'),
        'عامل وطن': t('role_cleaner'),
        'ميكانيكي': t('role_mechanic'),
        'مراقب': t('role_supervisor')
    };

    const filteredWorkers = useMemo(() => {
        return workers.filter(w => 
            w.name.includes(searchTerm) || 
            w.role.includes(searchTerm) || 
            w.area.includes(searchTerm)
        );
    }, [workers, searchTerm]);

    const jobStats = useMemo(() => {
        const map = new Map<string, { count: number; total: number }>();
        filteredWorkers.forEach(w => {
            const stats = map.get(w.role) || { count: 0, total: 0 };
            stats.count++;
            stats.total += w.salary;
            map.set(w.role, stats);
        });
        return Array.from(map.entries()).map(([name, data]) => ({
            name,
            displayName: roleMapping[name] || name,
            count: data.count,
            total: data.total,
            avg: data.total / data.count
        })).sort((a, b) => b.total - a.total);
    }, [filteredWorkers, t]);

    const areaStats = useMemo(() => {
        const map = new Map<string, { count: number; total: number; roles: Map<string, number> }>();
        filteredWorkers.forEach(w => {
            const area = w.area || 'غير محدد';
            const stats = map.get(area) || { count: 0, total: 0, roles: new Map() };
            stats.count++;
            stats.total += w.salary;

            const roleCount = stats.roles.get(w.role) || 0;
            stats.roles.set(w.role, roleCount + 1);

            map.set(area, stats);
        });
        return Array.from(map.entries()).map(([name, data]) => ({
            name,
            displayName: areaMapping[name] || name,
            count: data.count,
            total: data.total,
            avg: data.total / data.count,
            rolesBreakdown: Array.from(data.roles.entries())
                .map(([role, count]) => `${roleMapping[role] || role} (${count})`)
                .join(', ')
        })).sort((a, b) => b.total - a.total);
    }, [filteredWorkers, t]);

    const overallStats = useMemo(() => {
        const count = filteredWorkers.length;
        const total = filteredWorkers.reduce((sum, w) => sum + w.salary, 0);
        const avg = count > 0 ? total / count : 0;
        return { count, total, avg };
    }, [filteredWorkers]);

    const formatCurrency = (val: number) => {
        return val.toLocaleString("en-US", {
            minimumFractionDigits: 0,
            maximumFractionDigits: 0
        }) + ' ' + t('unit_jd');
    };

    const handlePrint = () => {
        printTable(tableContainerRef, t('sec_salary_analysis'), { vehicles: new Set(), months: new Set() });
    };

    if (workers.length === 0) return null;

    return (
        <CollapsibleSection title={t('sec_salary_analysis')}>
            <div className="flex flex-wrap gap-4 mb-8 bg-slate-50 p-6 rounded-3xl border border-slate-100 items-end shadow-inner text-right">
                <div className="flex flex-col gap-1.5">
                    <label className="text-xs font-black text-slate-500 mr-1">{t('chart_grouping')}</label>
                    <select 
                        value={analysisMode} 
                        onChange={(e) => setAnalysisMode(e.target.value as any)}
                        className="bg-white border-2 border-indigo-100 rounded-2xl p-3 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 min-w-[220px] transition-all"
                    >
                        <option value="all">{t('all_employees')}</option>
                        <option value="job">{t('by_job')}</option>
                        <option value="area">{t('by_area')}</option>
                    </select>
                </div>

                <div className="flex flex-col gap-1.5">
                    <label className="text-xs font-black text-slate-500 mr-1">{t('search_placeholder')}</label>
                    <input 
                        type="text"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder={t('search_placeholder')}
                        className="bg-white border-2 border-slate-100 rounded-2xl p-3 text-sm outline-none focus:ring-2 focus:ring-blue-500 min-w-[300px] transition-all text-right"
                    />
                </div>

                <div className="flex flex-1 justify-end">
                    <button 
                        onClick={handlePrint} 
                        className="px-8 py-3 bg-slate-800 text-white rounded-2xl text-sm font-bold shadow-lg hover:bg-slate-900 transition-all active:scale-95 flex items-center gap-2"
                    >
                        {t('print')}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-10">
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-indigo-600 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-indigo-600 transition-colors text-right">{t('th_emp_count')}</div>
                    <div className="text-5xl font-black text-slate-800 flex items-baseline gap-2 justify-end">
                        <span className="text-sm font-normal text-slate-400">{t('unit_worker')}</span>
                        {overallStats.count.toLocaleString()}
                    </div>
                </div>
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-emerald-500 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-emerald-600 transition-colors text-right">{t('th_total_salaries')}</div>
                    <div className="text-5xl font-black text-emerald-600 flex items-baseline gap-2 justify-end">
                        {formatCurrency(overallStats.total)}
                    </div>
                </div>
                <div className="bg-white p-7 rounded-3xl shadow-xl border-r-8 border-blue-500 transition-all hover:shadow-2xl hover:-translate-y-1 group">
                    <div className="text-slate-400 text-[10px] font-black uppercase mb-3 tracking-widest group-hover:text-blue-600 transition-colors text-right">{t('th_avg_annual_wage')}</div>
                    <div className="text-5xl font-black text-blue-600 flex items-baseline gap-2 justify-end">
                        {formatCurrency(overallStats.avg)}
                    </div>
                </div>
            </div>

            <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-sm" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-50">
                        {analysisMode === 'all' ? (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">{t('th_emp_name')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_job_title')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_area')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_annual_salary')}</th>
                            </tr>
                        ) : analysisMode === 'job' ? (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">{t('th_job_title')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_emp_count')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_total_salaries')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_avg_annual_wage')}</th>
                            </tr>
                        ) : (
                            <tr>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right pr-14">{t('th_area')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_emp_count')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest text-right">{t('th_job_title')}</th>
                                <th className="p-5 border-b border-slate-200 text-slate-500 font-black text-[10px] uppercase tracking-widest">{t('th_total_salaries')}</th>
                            </tr>
                        )}
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {analysisMode === 'all' && filteredWorkers.map((worker, idx) => (
                            <tr key={`${worker.name}-${idx}`} className="hover:bg-indigo-50/30 transition-colors">
                                <td className="p-5 font-bold text-slate-800 text-right pr-14">{worker.name}</td>
                                <td className="p-5">
                                    <span className="bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-xl text-[10px] font-black border border-indigo-100 shadow-sm uppercase">
                                        {roleMapping[worker.role] || worker.role}
                                    </span>
                                </td>
                                <td className="p-5 text-slate-500 font-medium">{areaMapping[worker.area] || worker.area}</td>
                                <td className="p-5 font-black text-emerald-700 text-lg">
                                    {formatCurrency(worker.salary)}
                                </td>
                            </tr>
                        ))}

                        {analysisMode === 'job' && jobStats.map((item, idx) => (
                            <tr key={`${item.name}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                <td className="p-5 font-black text-slate-800 text-right pr-14">{item.displayName}</td>
                                <td className="p-5 font-bold text-slate-600">{item.count}</td>
                                <td className="p-5 font-black text-emerald-700">{formatCurrency(item.total)}</td>
                                <td className="p-5 font-black text-blue-600">{formatCurrency(item.avg)}</td>
                            </tr>
                        ))}

                        {analysisMode === 'area' && areaStats.map((item, idx) => (
                            <tr key={`${item.name}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                <td className="p-5 font-black text-slate-800 text-right pr-14">{item.displayName}</td>
                                <td className="p-5 font-bold text-slate-600">{item.count}</td>
                                <td className="p-5 text-right">
                                    <div className="flex flex-wrap gap-1 justify-end">
                                        {item.rolesBreakdown.split(', ').map((role, rIdx) => (
                                            <span key={rIdx} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-md border border-slate-200">
                                                {role}
                                            </span>
                                        ))}
                                    </div>
                                </td>
                                <td className="p-5 font-black text-emerald-700">{formatCurrency(item.total)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

export default SalaryAnalysisSection;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Trip, Vehicle, Fuel, Maintenance, Area, VehicleTableData, DriverStatsData, Population, AreaPopulationStats, Worker } from './types';
import { CONFIG, MONTHS_ORDER } from './constants';
import { loadAllData } from './services/dataService';
import { generateFleetReport } from './services/geminiService';
import Header from './components/Header';
import KpiGrid from './components/KpiGrid';
import ChartSection from './components/ChartSection';
import TableSection from './components/TableSection';
import AiAnalysisSection from './components/AiAnalysisSection';
import UtilizationSection from './components/UtilizationSection';
import Loader from './components/Loader';
import AreaChartSection from './components/AreaChartSection';
import AreaIntelligenceSection from './components/AreaIntelligenceSection';
import DriverStatsSection from './components/DriverStatsSection';
import PopulationAnalysisSection from './components/PopulationAnalysisSection';
import SalaryAnalysisSection from './components/SalaryAnalysisSection';
import FinancialManagementSection from './components/FinancialManagementSection';
import AiChat from './components/AiChat';
import Sidebar from './components/Sidebar';
import { LanguageProvider } from './contexts/LanguageContext';

const AppContent: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [tripsData, setTripsData] = useState<Trip[]>([]);
    const [vehiclesData, setVehiclesData] = useState<Vehicle[]>([]);
    const [fuelData, setFuelData] = useState<Fuel[]>([]);
    const [maintData, setMaintData] = useState<Maintenance[]>([]);
    const [areasData, setAreasData] = useState<Area[]>([]);
    const [populationData, setPopulationData] = useState<Population[]>([]);
    const [workersData, setWorkersData] = useState<Worker[]>([]);

    const [selectedYear, setSelectedYear] = useState<string>('');
    const [comparisonYear, setComparisonYear] = useState<string>('');
    const [activeTab, setActiveTab] = useState<string>('kpi');
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    const [filters, setFilters] = useState<{ vehicles: Set<string>; months: Set<string> }>({
        vehicles: new Set(),
        months: new Set(),
    });
    const [isFiltering, setIsFiltering] = useState(false);

    const [aiReport, setAiReport] = useState<string>('');
    const [aiLoading, setAiLoading] = useState<boolean>(false);
    const [aiError, setAiError] = useState<string>('');

    const lineChartRef = useRef<HTMLDivElement>(null);
    const pieChartRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const { trips, vehicles, fuel, maint, areas, population, workers } = await loadAllData();
                setTripsData(trips);
                setVehiclesData(vehicles);
                setFuelData(fuel);
                setMaintData(maint);
                setAreasData(areas);
                setPopulationData(population || []);
                setWorkersData(workers || []);

                const years = [...new Set(trips.map(t => t['السنة']).filter(Boolean))].sort().reverse();
                if (years.length > 0) {
                    setSelectedYear(years[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleYearChange = (year: string) => {
        setIsFiltering(true);
        setSelectedYear(year);
    };

    const handleComparisonYearChange = (year: string) => {
        setIsFiltering(true);
        setComparisonYear(year);
    };

    const handleFilterToggle = useCallback((type: 'vehicles' | 'months', value: string) => {
        setIsFiltering(true);
        setFilters(prev => {
            const newSet = new Set(prev[type]);
            if (newSet.has(value)) {
                newSet.delete(value);
            } else {
                newSet.add(value);
            }
            return { ...prev, [type]: newSet };
        });
    }, []);

    const resetFilters = useCallback(() => {
        setIsFiltering(true);
        setFilters({ vehicles: new Set(), months: new Set() });
        setComparisonYear('');
    }, []);

    const filteredTrips = useMemo(() => {
        let data = tripsData.filter(r => r['السنة'] === selectedYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, selectedYear, filters]);

    const comparisonTrips = useMemo(() => {
        if (!comparisonYear) return [];
        let data = tripsData.filter(r => r['السنة'] === comparisonYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, comparisonYear, filters]);

    useEffect(() => {
        if (isFiltering) {
            const timer = setTimeout(() => setIsFiltering(false), 300);
            return () => clearTimeout(timer);
        }
    }, [filteredTrips, isFiltering]);

    const allVehiclesList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort();
    }, [tripsData]);

    const getVehicleTableData = (trips: Trip[], year: string) => {
        const vehGroups: { [key: string]: { trips: number; tons: number; drivers: Set<string> } } = {};

        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!vehGroups[v]) vehGroups[v] = { trips: 0, tons: 0, drivers: new Set() };
            vehGroups[v].trips += 1;
            vehGroups[v].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['السائق']) vehGroups[v].drivers.add(r['السائق']);
        });

        return Object.keys(vehGroups).map(v => {
            const { trips, tons, drivers } = vehGroups[v];
            const vehRow = vehiclesData.find(x => x['رقم المركبة'] === v) || {};
            const areaRow = areasData.find(x => x['رقم المركبة'] === v && (x['السنة'] === year || !x['السنة'])) || {};
            const fuelRow = fuelData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const maintRow = maintData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};

            let fuel = 0;
            if(fuelRow) {
                const monthsToSum = filters.months.size > 0 ? Array.from(filters.months) : MONTHS_ORDER;
                monthsToSum.forEach(m => {
                    fuel += (Number(fuelRow[m as keyof Fuel]) || 0);
                });
            }

            const maint = Number(maintRow?.['كلفة الصيانة'] || 0);
            const cap_m3 = parseFloat(vehRow['سعة المركبة بالمتر المكعب'] || '0');
            const density = parseFloat(vehRow['كثافة التحميل'] || '0');
            const cap_ton = cap_m3 * density;
            const totalCost = fuel + maint;
            const cost_trip = trips ? totalCost / trips : 0;
            const cost_ton = tons ? totalCost / tons : 0;

            return {
                veh: v,
                area: areaRow['المنطقة'] || '',
                drivers: [...drivers].join(', '),
                year: vehRow['سنة التصنيع'] || '',
                cap_m3,
                cap_ton,
                trips,
                tons,
                fuel,
                maint,
                cost_trip,
                cost_ton,
            };
        });
    };

    const filteredVehicleTableData = useMemo<VehicleTableData[]>(() => 
        getVehicleTableData(filteredTrips, selectedYear), 
    [filteredTrips, vehiclesData, areasData, fuelData, maintData, filters.months, selectedYear]);

    const comparisonVehicleTableData = useMemo<VehicleTableData[]>(() => 
        comparisonYear ? getVehicleTableData(comparisonTrips, comparisonYear) : [], 
    [comparisonTrips, vehiclesData, areasData, fuelData, maintData, filters.months, comparisonYear]);

    const driverStatsData = useMemo<DriverStatsData[]>(() => {
        const driverGroups: { [key: string]: { trips: number; tons: number; vehicles: Set<string> } } = {};

        filteredTrips.forEach(r => {
            const driver = r['السائق'];
            if (!driver || driver.trim() === '') return;

            if (!driverGroups[driver]) {
                driverGroups[driver] = { trips: 0, tons: 0, vehicles: new Set() };
            }
            driverGroups[driver].trips += 1;
            driverGroups[driver].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['رقم المركبة']) {
                driverGroups[driver].vehicles.add(r['رقم المركبة']);
            }
        });

        return Object.entries(driverGroups).map(([driver, data]) => {
            const { trips, tons, vehicles } = data;
            const avgTonsPerTrip = trips > 0 ? tons / trips : 0;

            return {
                driver,
                trips,
                tons,
                avgTonsPerTrip,
                vehicles: [...vehicles].join(', '),
            };
        });
    }, [filteredTrips]);

    const areaDistributionData = useMemo(() => {
        const areaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                areaMap.set(a['رقم المركبة'], a['المنطقة']);
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = trip['رقم المركبة'];
            if (vehicleId) {
                const area = areaMap.get(vehicleId) || 'غير محدد';
                if (!tonsByArea[area]) {
                    tonsByArea[area] = 0;
                }
                tonsByArea[area] += (Number(trip['صافي التحميل'] || 0) / 1000);
            }
        });

        return Object.entries(tonsByArea)
            .map(([name, value]) => ({ name, value: Math.round(value) }))
            .sort((a, b) => b.value - a.value);

    }, [filteredTrips, areasData, selectedYear]);

    const areaPopulationStats = useMemo<AreaPopulationStats[]>(() => {
        const vehAreaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                vehAreaMap.set(a['رقم المركبة'].trim(), a['المنطقة'].trim());
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = (trip['رقم المركبة'] || '').trim();
            const area = vehAreaMap.get(vehicleId) || 'غير مححدد';
            tonsByArea[area] = (tonsByArea[area] || 0) + (Number(trip['صافي التحميل'] || 0) / 1000);
        });

        return populationData.map(pop => {
            const areaName = pop.area.trim();
            const tons = tonsByArea[areaName] || 0;
            const population = pop.population || 0;
            const kgPerCapita = population > 0 ? (tons * 1000) / population : 0;
            return {
                area: areaName,
                population,
                totalTons: tons,
                kgPerCapita
            };
        }).sort((a, b) => b.kgPerCapita - a.kgPerCapita);
    }, [filteredTrips, areasData, populationData, selectedYear]);

    const totalPopulation = useMemo(() => {
        if (!populationData || !populationData.length) return 0;
        return populationData.reduce((sum, item) => sum + item.population, 0);
    }, [populationData]);

    const handleGenerateReport = async (analysisType: string, options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }) => {
        setAiLoading(true);
        setAiError('');
        setAiReport('');
        try {
            const report = await generateFleetReport(filteredVehicleTableData, analysisType, options);
            setAiReport(report);
        } catch (err) {
            setAiError('حدث خطأ أثناء إنشاء التقرير. يرجى المحاولة مرة أخرى.');
            console.error(err);
        } finally {
            setAiLoading(false);
        }
    };

    if (loading) {
        return <Loader />;
    }

    const renderActiveContent = () => {
        switch (activeTab) {
            case 'kpi':
                return (
                    <div className="animate-in fade-in duration-500">
                        <KpiGrid 
                            filteredTrips={filteredTrips} 
                            comparisonTrips={comparisonTrips}
                            fuelData={fuelData} 
                            maintData={maintData} 
                            filters={filters}
                            selectedYear={selectedYear}
                            comparisonYear={comparisonYear}
                            vehicleTableData={filteredVehicleTableData}
                            comparisonVehicleTableData={comparisonVehicleTableData}
                            totalPopulation={totalPopulation}
                            workers={workersData}
                        />
                    </div>
                );
            case 'charts':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <ChartSection 
                            data={filteredTrips} 
                            comparisonData={comparisonTrips}
                            isLoading={isFiltering} 
                            filters={filters} 
                            selectedYear={selectedYear}
                            comparisonYear={comparisonYear}
                            chartRef={lineChartRef} 
                        />
                    </div>
                );
            case 'financial':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <FinancialManagementSection 
                            workers={workersData} 
                            vehicleData={filteredVehicleTableData} 
                            selectedYear={selectedYear} 
                        />
                    </div>
                );
            case 'intelligence':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AreaIntelligenceSection 
                            workers={workersData} 
                            vehicleData={filteredVehicleTableData} 
                            population={populationData}
                            selectedYear={selectedYear}
                            filters={filters}
                        />
                    </div>
                );
            case 'distribution':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AreaChartSection data={areaDistributionData} isLoading={isFiltering} filters={filters} chartRef={pieChartRef} />
                    </div>
                );
            case 'population':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <PopulationAnalysisSection tableData={areaPopulationStats} filters={filters} />
                    </div>
                );
            case 'salaries':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <SalaryAnalysisSection workers={workersData} />
                    </div>
                );
            case 'vehicles':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500 space-y-6">
                        <TableSection tableData={filteredVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${selectedYear}`} />
                        {comparisonYear && (
                            <TableSection tableData={comparisonVehicleTableData} filters={filters} title={`كفاءة المركبات - سنة ${comparisonYear} (للمقارنة)`} />
                        )}
                    </div>
                );
            case 'drivers':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <DriverStatsSection tableData={driverStatsData} filters={filters} />
                    </div>
                );
            case 'ai':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AiAnalysisSection
                            vehicles={allVehiclesList}
                            onGenerateReport={handleGenerateReport}
                            report={aiReport}
                            isLoading={aiLoading}
                            error={aiError}
                            filters={filters}
                        />
                    </div>
                );
            case 'utilization':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <UtilizationSection tableData={filteredVehicleTableData} filters={filters} />
                    </div>
                );
            default:
                return null;
        }
    };

    return (
        <div className="bg-slate-50 text-slate-800 min-h-screen flex overflow-hidden">
            {/* Sidebar */}
            <Sidebar 
                activeTab={activeTab} 
                setActiveTab={setActiveTab} 
                isOpen={isSidebarOpen} 
                setIsOpen={setIsSidebarOpen}
            />

            {/* Main Content */}
            <div className={`flex-1 flex flex-col h-screen transition-all duration-300 ${isSidebarOpen ? 'mr-72' : 'mr-20'} overflow-y-auto`}>
                <Header
                    tripsData={tripsData}
                    filters={filters}
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    onYearChange={handleYearChange}
