import React, { useState, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Trip } from '../types';
import { MONTHS_ORDER } from '../constants';
import CollapsibleSection from './CollapsibleSection';
import { printChart } from '../services/printService';
import { useLanguage } from '../contexts/LanguageContext';

interface ChartSectionProps {
    data: Trip[];
    comparisonData: Trip[];
    isLoading: boolean;
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    chartRef: React.RefObject<HTMLDivElement>;
}

const ChartSection: React.FC<ChartSectionProps> = ({ data, comparisonData, isLoading, filters, selectedYear, comparisonYear, chartRef }) => {
    const { t, language } = useLanguage();
    const [groupBy, setGroupBy] = useState<'month' | 'day'>('month');
    const [metric, setMetric] = useState<'trips' | 'tons'>('trips');

    const chartData = useMemo(() => {
        const process = (trips: Trip[]) => {
            const grouped: { [key: string]: number } = {};
            trips.forEach(trip => {
                let key: string | null = null;
                if (groupBy === 'month') {
                    key = (trip['الشهر'] || '').toLowerCase();
                } else {
                    const date = new Date(trip['تاريخ التوزين الثاني']);
                    if (!isNaN(date.getTime())) {
                        key = date.toISOString().split('T')[0].split('-').slice(1).join('-'); 
                    }
                }
                if (!key) return;
                if (!grouped[key]) grouped[key] = 0;
                grouped[key] += metric === 'trips' ? 1 : Math.round((Number(trip['صافي التحميل'] || 0) / 1000));
            });
            return grouped;
        };

        const currentMap = process(data);
        const comparisonMap = process(comparisonData);

        const allKeys = [...new Set([...Object.keys(currentMap), ...Object.keys(comparisonMap)])];

        const merged = allKeys.map(key => ({
            name: key,
            current: currentMap[key] || 0,
            comparison: comparisonMap[key] || 0,
        }));

        if (groupBy === 'month') {
            merged.sort((a, b) => MONTHS_ORDER.indexOf(a.name) - MONTHS_ORDER.indexOf(b.name));
        } else {
            merged.sort((a, b) => a.name.localeCompare(b.name));
        }

        return merged;
    }, [data, comparisonData, groupBy, metric]);

    const handlePrint = () => {
        const chartTitle = `${t('sec_time_series')} - ${metric === 'trips' ? t('chart_trips') : t('chart_tons')} (${groupBy === 'month' ? t('chart_monthly') : t('chart_daily')})`;
        printChart(chartRef, chartTitle, filters, t, language);
    };

    return (
        <CollapsibleSection title={t('sec_time_series')}>
            <div className="flex flex-wrap items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="timeGroup" className="ml-2 font-semibold">{t('chart_grouping')}</label>
                    <select id="timeGroup" value={groupBy} onChange={e => setGroupBy(e.target.value as 'month' | 'day')}
                        className="p-2 border border-slate-300 rounded-lg">
                        <option value="month">{t('chart_monthly')}</option>
                        <option value="day">{t('chart_daily')}</option>
                    </select>
                </div>
                <div>
                    <label htmlFor="metric" className="ml-2 font-semibold">{t('chart_value')}</label>
                    <select id="metric" value={metric} onChange={e => setMetric(e.target.value as 'trips' | 'tons')}
                        className="p-2 border border-slate-300 rounded-lg">
                        <option value="trips">{t('chart_trips')}</option>
                        <option value="tons">{t('chart_tons')}</option>
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    {t('print')}
                </button>
            </div>
            <div className="h-96 w-full relative" ref={chartRef}>
                 {isLoading && (
                    <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg">
                        <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                    </div>
                )}
                <ResponsiveContainer>
                    <LineChart data={chartData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line 
                            type="monotone" 
                            dataKey="current" 
                            name={`${selectedYear} (${metric === 'trips' ? t('th_trips') : t('th_tons')})`} 
                            stroke="#2563eb" 
                            strokeWidth={3} 
                            activeDot={{ r: 8 }} 
                        />
                        {comparisonYear && (
                            <Line 
                                type="monotone" 
                                dataKey="comparison" 
                                name={`${comparisonYear} (${metric === 'trips' ? t('th_trips') : t('th_tons')})`} 
                                stroke="#94a3b8" 
                                strokeWidth={2} 
                                strokeDasharray="5 5"
                            />
                        )}
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </CollapsibleSection>
    );
};

export default ChartSection;

import React from 'react';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import CollapsibleSection from './CollapsibleSection';
import { printChart } from '../services/printService';
import { useLanguage } from '../contexts/LanguageContext';

interface AreaChartSectionProps {
    data: { name: string; value: number }[];
    isLoading: boolean;
    filters: { vehicles: Set<string>; months: Set<string> };
    chartRef: React.RefObject<HTMLDivElement>;
}

const COLORS = ['#0ea5e9', '#6366f1', '#a855f7', '#ec4899', '#f97316', '#eab308', '#84cc16', '#10b981', '#14b8a6', '#ef4444'];

const AreaChartSection: React.FC<AreaChartSectionProps> = ({ data, isLoading, filters, chartRef }) => {
    const { t, language } = useLanguage();

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const translatedData = React.useMemo(() => {
        return data.map(item => ({
            ...item,
            name: areaMapping[item.name] || item.name
        }));
    }, [data, t]);

    const CustomTooltip = ({ active, payload }: any) => {
        if (active && payload && payload.length) {
            const percent = payload[0].payload.percent || payload[0].percent;
            const percentDisplay = (isFinite(percent) && percent > 0) 
                ? `(${(percent * 100).toFixed(1)}%)`
                : '';

            return (
                <div className="bg-white p-2 border border-slate-200 rounded-lg shadow-sm">
                    <p className="font-bold">{`${payload[0].name}`}</p>
                    <p className="text-sm">{`${t('chart_amount')} ${payload[0].value.toLocaleString()} ${t('unit_ton')} ${percentDisplay}`}</p>
                </div>
            );
        }
        return null;
    };

    const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
        if (!isFinite(percent) || percent <= 0.02) {
            return null;
        }
        const RADIAN = Math.PI / 180;
        const radius = innerRadius + (outerRadius - innerRadius) * 0.6;
        const x = cx + radius * Math.cos(-midAngle * RADIAN);
        const y = cy + radius * Math.sin(-midAngle * RADIAN);

        return (
            <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" className="font-bold text-sm">
                {`${(percent * 100).toFixed(0)}%`}
            </text>
        );
    };

    const totalValue = translatedData.reduce((sum, entry) => sum + entry.value, 0);

    const handlePrint = () => {
        printChart(chartRef, t('sec_waste_dist'), filters, t, language);
    };

    return (
        <CollapsibleSection title={t('sec_waste_dist')}>
             <div className="flex items-center justify-end gap-4 mb-4 text-sm">
                <button 
                    onClick={handlePrint} 
                    className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600 disabled:bg-slate-400 disabled:cursor-not-allowed"
                    disabled={isLoading || totalValue === 0}
                >
                    {t('print')}
                </button>
            </div>
             <div className="h-96 w-full relative" ref={chartRef}>
                 {isLoading && (
                    <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg">
                        <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                    </div>
                )}
                {!isLoading && totalValue > 0 ? (
                    <ResponsiveContainer>
                        <PieChart>
                            <Pie
                                data={translatedData}
                                cx="50%"
                                cy="50%"
                                labelLine={false}
                                outerRadius={130}
                                fill="#8884d8"
                                dataKey="value"
                                nameKey="name"
                                label={renderCustomizedLabel}
                            >
                                {translatedData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                ))}
                            </Pie>
                            <Tooltip content={<CustomTooltip />} />
                            <Legend wrapperStyle={{fontSize: '0.875rem'}} />
                        </PieChart>
                    </ResponsiveContainer>
                ) : (
                    !isLoading && <div className="absolute inset-0 flex items-center justify-center text-slate-500">
                        {t('chart_no_data')}
                    </div>
                )}
             </div>
        </CollapsibleSection>
    );
};

export default AreaChartSection;

import React, { useState, useMemo, useRef } from 'react';
import { AreaPopulationStats } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';

interface PopulationAnalysisSectionProps {
    tableData: AreaPopulationStats[];
    filters: { vehicles: Set<string>; months: Set<string> };
}

const PopulationAnalysisSection: React.FC<PopulationAnalysisSectionProps> = ({ tableData, filters }) => {
    const { t, language } = useLanguage();
    const [sortBy, setSortBy] = useState<keyof AreaPopulationStats>('kgPerCapita');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const sortedData = useMemo(() => {
        const sorted = [...tableData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, language);
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA;
            }
            return 0;
        });
        return sorted;
    }, [tableData, sortBy, language]);

    const totals = useMemo(() => {
        if (sortedData.length === 0) return null;
        const totalPop = sortedData.reduce((sum, row) => sum + row.population, 0);
        const totalTons = sortedData.reduce((sum, row) => sum + row.totalTons, 0);
        const avgKg = totalPop > 0 ? (totalTons * 1000) / totalPop : 0;
        return { totalPop, totalTons, avgKg };
    }, [sortedData]);

    const handlePrint = () => {
        printTable(tableContainerRef, t('sec_pop_analysis'), filters, t, language);
    };

    const headers = [
        { key: 'area', label: t('th_area') },
        { key: 'population', label: t('th_pop') },
        { key: 'totalTons', label: t('th_tons') },
        { key: 'kgPerCapita', label: t('th_kg_capita') },
    ];

    if (tableData.length === 0) return null;

    return (
        <CollapsibleSection title={t('sec_pop_analysis')}>
            <div className="flex items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="popSort" className="ml-2 font-semibold">{t('chart_grouping')}</label>
                    <select id="popSort" value={sortBy} onChange={e => setSortBy(e.target.value as keyof AreaPopulationStats)}
                        className="p-2 border border-slate-300 rounded-lg">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    {t('print')}
                </button>
            </div>
            <div className="overflow-x-auto" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-100">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-2 border-b border-slate-200 font-semibold text-slate-600">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody>
                        {sortedData.map((row, idx) => (
                            <tr key={`${row.area}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                <td className="p-3 border-b border-slate-200 font-bold">{areaMapping[row.area] || row.area}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.population)}</td>
                                <td className="p-3 border-b border-slate-200">{formatNumber(row.totalTons, 1)}</td>
                                <td className="p-3 border-b border-slate-200 font-semibold text-indigo-600">
                                    {formatNumber(row.kgPerCapita, 3)}
                                </td>
                            </tr>
                        ))}
                        {totals && (
                            <tr className="bg-slate-200 font-black text-slate-800">
                                <td className="p-3 border-t-2 border-slate-300">{t('total_avg')}</td>
                                <td className="p-3 border-t-2 border-slate-300">{formatNumber(totals.totalPop)}</td>
                                <td className="p-3 border-t-2 border-slate-300">{formatNumber(totals.totalTons, 1)}</td>
                                <td className="p-3 border-t-2 border-slate-300 text-indigo-800">
                                    {formatNumber(totals.avgKg, 3)}
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
            <div className="mt-4 p-4 bg-blue-50 border border-blue-100 rounded-xl text-sm text-blue-800 leading-relaxed">
                <strong>{t('print_note')}</strong> {t('pop_analysis_note')}
            </div>
        </CollapsibleSection>
    );
};

export default PopulationAnalysisSection;

import React, { useState, useMemo, useRef } from 'react';
import { VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';

interface UtilizationSectionProps {
    tableData: VehicleTableData[];
    filters: { vehicles: Set<string>; months: Set<string> };
}

type UtilizationData = {
    veh: string;
    cap_ton: number;
    avgTonsPerTrip: number;
    utilization: number;
};

const UtilizationSection: React.FC<UtilizationSectionProps> = ({ tableData, filters }) => {
    const { t, language } = useLanguage();
    const [sortBy, setSortBy] = useState<keyof UtilizationData>('utilization');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const utilizationData = useMemo<UtilizationData[]>(() => {
        return tableData.map(v => {
            const avgTonsPerTrip = v.trips > 0 ? v.tons / v.trips : 0;
            const utilization = v.cap_ton > 0 ? (avgTonsPerTrip / v.cap_ton) * 100 : 0;
            return {
                veh: v.veh,
                cap_ton: v.cap_ton,
                avgTonsPerTrip,
                utilization
            };
        });
    }, [tableData]);

    const sortedData = useMemo(() => {
        const sorted = [...utilizationData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (sortBy === 'veh') {
                return String(valA).localeCompare(String(valB), language);
            }
            return (valB as number) - (valA as number);
        });
        return sorted;
    }, [utilizationData, sortBy, language]);

    const handlePrint = () => {
        printTable(tableContainerRef, t('sec_utilization'), filters, t, language);
    };

    const headers = [
        { key: 'veh', label: t('th_veh_no') },
        { key: 'cap_ton', label: t('th_cap_ton') },
        { key: 'avgTonsPerTrip', label: t('th_avg_load') },
        { key: 'utilization', label: t('th_utilization') },
    ];

    return (
        <CollapsibleSection title={t('sec_utilization')}>
            <div className="flex items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="utilizationSort" className="ml-2 font-semibold">{t('chart_grouping')}</label>
                    <select id="utilizationSort" value={sortBy} onChange={e => setSortBy(e.target.value as keyof UtilizationData)}
                        className="p-2 border border-slate-300 rounded-lg">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    {t('print')}
                </button>
            </div>
            <div className="overflow-x-auto" ref={tableContainerRef}>
                <table id="utilization-table" className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-100">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-2 border-b border-slate-200 font-semibold text-slate-600">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody>
                        {sortedData.map(row => (
                            <tr key={row.veh} className={`hover:bg-slate-50 ${row.utilization < 50 ? 'bg-red-100 underutilized' : ''}`}>
                                <td className="p-2 border-b border-slate-200">{row.veh}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.cap_ton, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.avgTonsPerTrip, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-bold">{formatNumber(row.utilization, 1)}%</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

