import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Trip, Vehicle, Fuel, Maintenance, Area, VehicleTableData, DriverStatsData, Population, AreaPopulationStats, Worker, Revenue, WasteTreatment, Distance } from './types';
import { CONFIG, MONTHS_ORDER } from './constants';
import { loadAllData } from './services/dataService';
import { generateFleetReport } from './services/geminiService';
import Header from './components/Header';
import KpiGrid from './components/KpiGrid';
import ChartSection from './components/ChartSection';
import TableSection from './components/TableSection';
import AiAnalysisSection from './components/AiAnalysisSection';
import UtilizationSection from './components/UtilizationSection';
import Loader from './components/Loader';
import AreaChartSection from './components/AreaChartSection';
import AreaIntelligenceSection from './components/AreaIntelligenceSection';
import DriverStatsSection from './components/DriverStatsSection';
import PopulationAnalysisSection from './components/PopulationAnalysisSection';
import SalaryAnalysisSection from './components/SalaryAnalysisSection';
import FinancialManagementSection from './components/FinancialManagementSection';
import AnnualSummarySection from './components/AnnualSummarySection';
import AiChat from './components/AiChat';
import Sidebar from './components/Sidebar';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';

const AppContent: React.FC = () => {
    const { language, t } = useLanguage();
    const [loading, setLoading] = useState(true);
    const [tripsData, setTripsData] = useState<Trip[]>([]);
    const [vehiclesData, setVehiclesData] = useState<Vehicle[]>([]);
    const [fuelData, setFuelData] = useState<Fuel[]>([]);
    const [maintData, setMaintData] = useState<Maintenance[]>([]);
    const [areasData, setAreasData] = useState<Area[]>([]);
    const [populationData, setPopulationData] = useState<Population[]>([]);
    const [workersData, setWorkersData] = useState<Worker[]>([]);
    const [revenuesData, setRevenuesData] = useState<Revenue[]>([]);
    const [treatmentData, setTreatmentData] = useState<WasteTreatment[]>([]);
    const [distanceData, setDistanceData] = useState<Distance[]>([]);

    const [selectedYear, setSelectedYear] = useState<string>('');
    const [comparisonYear, setComparisonYear] = useState<string>('');
    const [activeTab, setActiveTab] = useState<string>('summary');
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    const [filters, setFilters] = useState<{ vehicles: Set<string>; months: Set<string> }>({
        vehicles: new Set(),
        months: new Set(),
    });
    const [isFiltering, setIsFiltering] = useState(false);

    const [aiReport, setAiReport] = useState<string>('');
    const [aiLoading, setAiLoading] = useState<boolean>(false);
    const [aiError, setAiError] = useState<string>('');

    const lineChartRef = useRef<HTMLDivElement>(null);
    const pieChartRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const { trips, vehicles, fuel, maint, areas, population, workers, revenues, treatment, distance } = await loadAllData();
                setTripsData(trips);
                setVehiclesData(vehicles);
                setFuelData(fuel);
                setMaintData(maint);
                setAreasData(areas);
                setPopulationData(population || []);
                setWorkersData(workers || []);
                setRevenuesData(revenues || []);
                setTreatmentData(treatment || []);
                setDistanceData(distance || []);

                const years = [...new Set(trips.map(t => t['السنة']).filter(Boolean))].sort().reverse();
                if (years.length > 0) {
                    setSelectedYear(years[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleYearChange = (year: string) => {
        setIsFiltering(true);
        setSelectedYear(year);
    };

    const handleComparisonYearChange = (year: string) => {
        setIsFiltering(true);
        setComparisonYear(year);
    };

    const handleFilterToggle = useCallback((type: 'vehicles' | 'months', value: string) => {
        setIsFiltering(true);
        setFilters(prev => {
            const newSet = new Set(prev[type]);
            if (newSet.has(value)) {
                newSet.delete(value);
            } else {
                newSet.add(value);
            }
            return { ...prev, [type]: newSet };
        });
    }, []);

    const resetFilters = useCallback(() => {
        setIsFiltering(true);
        setFilters({ vehicles: new Set(), months: new Set() });
        setComparisonYear('');
    }, []);

    const filteredTrips = useMemo(() => {
        let data = tripsData.filter(r => r['السنة'] === selectedYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, selectedYear, filters]);

    const comparisonTrips = useMemo(() => {
        if (!comparisonYear) return [];
        let data = tripsData.filter(r => r['السنة'] === comparisonYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, comparisonYear, filters]);

    useEffect(() => {
        if (isFiltering) {
            const timer = setTimeout(() => setIsFiltering(false), 300);
            return () => clearTimeout(timer);
        }
    }, [filteredTrips, isFiltering]);

    const allVehiclesList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort();
    }, [tripsData]);

    const getVehicleTableData = (trips: Trip[], year: string) => {
        const vehGroups: { [key: string]: { trips: number; tons: number; drivers: Set<string> } } = {};

        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!vehGroups[v]) vehGroups[v] = { trips: 0, tons: 0, drivers: new Set() };
            vehGroups[v].trips += 1;
            vehGroups[v].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['السائق']) vehGroups[v].drivers.add(r['السائق']);
        });

        return Object.keys(vehGroups).map(v => {
            const { trips, tons, drivers } = vehGroups[v];
            const vehRow = vehiclesData.find(x => x['رقم المركبة'] === v) || {};
            const areaRow = areasData.find(x => x['رقم المركبة'] === v && (x['السنة'] === year || !x['السنة'])) || {};
            const fuelRow = fuelData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const maintRow = maintData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const distRow = distanceData.find(x => x['رقم المركبة'] === v && x['السنة'] === year);

            let fuel = 0;
            if(fuelRow) {
                const monthsToSum = filters.months.size > 0 ? Array.from(filters.months) : MONTHS_ORDER;
                monthsToSum.forEach(m => {
                    fuel += (Number(fuelRow[m as keyof Fuel]) || 0);
                });
            }

            const maint = Number(maintRow?.['كلفة الصيانة'] || 0);
            const cap_m3 = parseFloat(vehRow['سعة المركبة بالمتر المكعب'] || '0');
            const density = parseFloat(vehRow['كثافة التحميل'] || '0');
            const cap_ton = cap_m3 * density;
            const totalCost = fuel + maint;
            const cost_trip = trips ? totalCost / trips : 0;
            const cost_ton = tons ? totalCost / tons : 0;

            const distance = distRow ? (Number(distRow['المسافة المقطوعة (كم)']) || 0) : 0;
            const km_per_trip = trips ? distance / trips : 0;

            return {
                veh: v,
                area: areaRow['المنطقة'] || '',
                drivers: [...drivers].join(', '),
                year: vehRow['سنة التصنيع'] || '',
                cap_m3,
                cap_ton,
                trips,
                tons,
                fuel,
                maint,
                cost_trip,
                cost_ton,
                distance,
                km_per_trip
            };
        });
    };

    const filteredVehicleTableData = useMemo<VehicleTableData[]>(() => 
        getVehicleTableData(filteredTrips, selectedYear), 
    [filteredTrips, vehiclesData, areasData, fuelData, maintData, filters.months, selectedYear, distanceData]);

    const comparisonVehicleTableData = useMemo<VehicleTableData[]>(() => 
        comparisonYear ? getVehicleTableData(comparisonTrips, comparisonYear) : [], 
    [comparisonTrips, vehiclesData, areasData, fuelData, maintData, filters.months, comparisonYear, distanceData]);

    const driverStatsData = useMemo<DriverStatsData[]>(() => {
        const driverGroups: { [key: string]: { trips: number; tons: number; vehicles: Set<string> } } = {};

        filteredTrips.forEach(r => {
            const driver = r['السائق'];
            if (!driver || driver.trim() === '') return;

            if (!driverGroups[driver]) {
                driverGroups[driver] = { trips: 0, tons: 0, vehicles: new Set() };
            }
            driverGroups[driver].trips += 1;
            driverGroups[driver].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['رقم المركبة']) {
                driverGroups[driver].vehicles.add(r['رقم المركبة']);
            }
        });

        return Object.entries(driverGroups).map(([driver, data]) => {
            const { trips, tons, vehicles } = data;
            const avgTonsPerTrip = trips > 0 ? tons / trips : 0;

            return {
                driver,
                trips,
                tons,
                avgTonsPerTrip,
                vehicles: [...vehicles].join(', '),
            };
        });
    }, [filteredTrips]);

    const areaDistributionData = useMemo(() => {
        const areaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                areaMap.set(a['رقم المركبة'], a['المنطقة']);
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = trip['رقم المركبة'];
            if (vehicleId) {
                const area = areaMap.get(vehicleId) || 'غير محدد';
                if (!tonsByArea[area]) {
                    tonsByArea[area] = 0;
                }
                tonsByArea[area] += (Number(trip['صافي التحميل'] || 0) / 1000);
            }
        });

        return Object.entries(tonsByArea)
            .map(([name, value]) => ({ name, value: Math.round(value) }))
            .sort((a, b) => b.value - a.value);

    }, [filteredTrips, areasData, selectedYear]);

    const areaPopulationStats = useMemo<AreaPopulationStats[]>(() => {
        const vehAreaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                vehAreaMap.set(a['رقم المركبة'].trim(), a['المنطقة'].trim());
            }
        });

        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = (trip['رقم المركبة'] || '').trim();
            const area = vehAreaMap.get(vehicleId) || 'غير محدد';
            tonsByArea[area] = (tonsByArea[area] || 0) + (Number(trip['صافي التحميل'] || 0) / 1000);
        });

        const popDataForYear = populationData.filter(p => p.year === selectedYear);

        return popDataForYear.map(pop => {
            const areaName = pop.area.trim();
            const tons = tonsByArea[areaName] || 0;
            const population = pop.population || 0;
            const served = pop.served || 0;
            const kgPerCapita = population > 0 ? (tons * 1000) / population : 0;
            const coverageRate = population > 0 ? (served / population) * 100 : 0;

            return {
                area: areaName,
                population,
                served,
                totalTons: tons,
                kgPerCapita,
                coverageRate
            };
        }).sort((a, b) => b.kgPerCapita - a.kgPerCapita);
    }, [filteredTrips, areasData, populationData, selectedYear]);

    const populationTotals = useMemo(() => {
        let targetData = areaPopulationStats;

        if (filters.vehicles.size > 0) {
            const activeAreas = new Set(filteredVehicleTableData.map(v => v.area));
            targetData = areaPopulationStats.filter(p => activeAreas.has(p.area));
        }

        const totalPop = targetData.reduce((sum, item) => sum + item.population, 0);
        const totalServed = targetData.reduce((sum, item) => sum + item.served, 0);
        const coverageRate = totalPop > 0 ? (totalServed / totalPop) * 100 : 0;

        return { totalPop, totalServed, coverageRate };
    }, [areaPopulationStats, filters.vehicles, filteredVehicleTableData]);

    const financialTotals = useMemo(() => {
        const getYearRevenueDetail = (year: string) => {
            if (!year) return { total: 0, hh: 0, commercial: 0, recycling: 0 };
            const yearRevenues = revenuesData.filter(r => r.year === year);
            const hh = yearRevenues.reduce((sum, r) => sum + r.hhFees, 0);
            const commercial = yearRevenues.reduce((sum, r) => sum + r.commercialFees, 0);
            const recycling = yearRevenues.reduce((sum, r) => sum + r.recyclingRevenue, 0);
            return {
                total: hh + commercial + recycling,
                hh,
                commercial,
                recycling
            };
        };

        return {
            current: getYearRevenueDetail(selectedYear),
            comparison: getYearRevenueDetail(comparisonYear)
        };
    }, [revenuesData, selectedYear, comparisonYear]);

    const treatmentTotals = useMemo(() => {
        const getYearTreatment = (year: string) => {
            if (!year) return null;
            const yearTreat = treatmentData.find(t => t.year === year);
            if (!yearTreat) return null;
            const totalTreated = yearTreat.recyclablesTon + yearTreat.biowasteTon + yearTreat.otherTreatmentTon;
            return {
                ...yearTreat,
                totalTreated
            };
        };

        return {
            current: getYearTreatment(selectedYear),
            comparison: comparisonYear ? getYearTreatment(comparisonYear) : null
        };
    }, [treatmentData, selectedYear, comparisonYear]);

    const handleGenerateReport = async (analysisType: string, options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string }) => {
        setAiLoading(true);
        setAiError('');
        setAiReport('');
        try {
            const report = await generateFleetReport(filteredVehicleTableData, analysisType, options, language);
            setAiReport(report);
        } catch (err) {
            setAiError(language === 'ar' ? 'حدث خطأ أثناء إنشاء التقرير. يرجى المحاولة مرة أخرى.' : 'Error generating report. Please try again.');
            console.error(err);
        } finally {
            setAiLoading(false);
        }
    };

    if (loading) {
        return <Loader />;
    }

    const renderActiveContent = () => {
        switch (activeTab) {
            case 'summary':
                return (
                    <AnnualSummarySection 
                        filteredTrips={filteredTrips}
                        treatment={treatmentTotals.current}
                        populationData={populationData}
                        workers={workersData}
                        revenues={revenuesData}
                        vehicleTableData={filteredVehicleTableData}
                        selectedYear={selectedYear}
                    />
                );
            case 'kpi':
                return (
                    <div className="animate-in fade-in duration-500">
                        <KpiGrid 
                            filteredTrips={filteredTrips} 
                            comparisonTrips={comparisonTrips}
                            fuelData={fuelData} 
                            maintData={maintData} 
                            filters={filters}
                            selectedYear={selectedYear}
                            comparisonYear={comparisonYear}
                            vehicleTableData={filteredVehicleTableData}
                            comparisonVehicleTableData={comparisonVehicleTableData}
                            totalPopulation={populationTotals.totalPop}
                            totalServed={populationTotals.totalServed}
                            coverageRate={populationTotals.coverageRate}
                            workers={workersData}
                            revenueDetail={financialTotals.current}
                            comparisonRevenueDetail={financialTotals.comparison}
                            treatment={treatmentTotals.current}
                            comparisonTreatment={treatmentTotals.comparison}
                        />
                    </div>
                );
            case 'charts':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <ChartSection 
                            data={filteredTrips} 
                            comparisonData={comparisonTrips}
                            isLoading={isFiltering} 
                            filters={filters} 
                            selectedYear={selectedYear}
                            comparisonYear={comparisonYear}
                            chartRef={lineChartRef} 
                        />
                    </div>
                );
            case 'financial':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <FinancialManagementSection 
                            workers={workersData} 
                            vehicleData={filteredVehicleTableData} 
                            selectedYear={selectedYear} 
                        />
                    </div>
                );
            case 'intelligence':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AreaIntelligenceSection 
                            workers={workersData} 
                            vehicleData={filteredVehicleTableData} 
                            population={populationData.filter(p => p.year === selectedYear)}
                            selectedYear={selectedYear}
                            filters={filters}
                        />
                    </div>
                );
            case 'distribution':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AreaChartSection data={areaDistributionData} isLoading={isFiltering} filters={filters} chartRef={pieChartRef} />
                    </div>
                );
            case 'population':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <PopulationAnalysisSection tableData={areaPopulationStats} filters={filters} />
                    </div>
                );
            case 'salaries':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <SalaryAnalysisSection workers={workersData} />
                    </div>
                );
            case 'vehicles':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500 space-y-6">
                        <TableSection tableData={filteredVehicleTableData} filters={filters} />
                        {comparisonYear && (
                            <TableSection tableData={comparisonVehicleTableData} filters={filters} title={`${t('sec_veh_eff')} - ${t('year')} ${comparisonYear} (${t('comparison')})`} />
                        )}
                    </div>
                );
            case 'drivers':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <DriverStatsSection tableData={driverStatsData} filters={filters} />
                    </div>
                );
            case 'ai':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <AiAnalysisSection
                            vehicles={allVehiclesList}
                            onGenerateReport={handleGenerateReport}
                            report={aiReport}
                            isLoading={aiLoading}
                            error={aiError}
                            filters={filters}
                        />
                    </div>
                );
            case 'utilization':
                return (
                    <div className="animate-in slide-in-from-left-5 duration-500">
                        <UtilizationSection tableData={filteredVehicleTableData} filters={filters} />
                    </div>
                );
            default:
                return null;
        }
    };

    const isRtl = language === 'ar';

    return (
        <div className={`bg-slate-50 text-slate-800 min-h-screen flex overflow-hidden ${isRtl ? 'font-arabic' : 'font-sans'}`}>
            <Sidebar 
                activeTab={activeTab} 
                setActiveTab={setActiveTab} 
                isOpen={isSidebarOpen} 
                setIsOpen={setIsSidebarOpen}
            />

            <div className={`flex-1 flex flex-col h-screen transition-all duration-300 ${isSidebarOpen ? (isRtl ? 'mr-72' : 'ml-72') : (isRtl ? 'mr-20' : 'ml-20')} overflow-y-auto`}>
                <Header
                    tripsData={tripsData}
                    filters={filters}
                    selectedYear={selectedYear}
                    comparisonYear={comparisonYear}
                    activeTab={activeTab}
                    onYearChange={handleYearChange}
                    onComparisonYearChange={handleComparisonYearChange}
                    onFilterToggle={handleFilterToggle}
                    onResetFilters={resetFilters}
                />

                <main className={`container mx-auto p-4 md:p-6 pb-24 ${isRtl ? 'text-right' : 'text-left'}`}>
                    {renderActiveContent()}
                </main>

                <AiChat 
                    currentData={filteredVehicleTableData} 
                    comparisonData={comparisonVehicleTableData} 
                    selectedYear={selectedYear} 
                    comparisonYear={comparisonYear} 
                />
            </div>
        </div>
    );
};

const App: React.FC = () => {
    return (
        <LanguageProvider>
            <AppContent />
        </LanguageProvider>
    );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';

interface TableSectionProps {
    tableData: VehicleTableData[];
    filters: { vehicles: Set<string>; months: Set<string> };
    title?: string;
}

const TableSection: React.FC<TableSectionProps> = ({ tableData, filters, title }) => {
    const { t, language } = useLanguage();
    const [sortBy, setSortBy] = useState<keyof VehicleTableData>('tons');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const headers = [
        { key: 'veh', label: t('th_veh_no') }, 
        { key: 'area', label: t('th_area') },
        { key: 'drivers', label: t('th_driver') }, 
        { key: 'year', label: t('th_year') },
        { key: 'cap_m3', label: t('th_cap_m3') }, 
        { key: 'cap_ton', label: t('th_cap_ton') },
        { key: 'trips', label: t('th_trips') }, 
        { key: 'tons', label: t('th_tons') },
        { key: 'fuel', label: t('th_fuel') }, 
        { key: 'maint', label: t('th_maint') },
        { key: 'cost_trip', label: t('th_cost_trip') }, 
        { key: 'cost_ton', label: t('th_cost_ton') },
        { key: 'distance', label: t('th_distance') },
        { key: 'km_per_trip', label: t('th_km_trip') },
    ];

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const sortedData = useMemo(() => {
        const sorted = [...tableData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, language);
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA;
            }
            return 0;
        });
        return sorted;
    }, [tableData, sortBy, language]);

    const totals = useMemo(() => {
        if (sortedData.length === 0) return null;
        const totalTrips = sortedData.reduce((s, r) => s + r.trips, 0);
        const totalTons = sortedData.reduce((s, r) => s + r.tons, 0);
        const totalFuel = sortedData.reduce((s, r) => s + r.fuel, 0);
        const totalMaint = sortedData.reduce((s, r) => s + r.maint, 0);
        const totalDistance = sortedData.reduce((s, r) => s + r.distance, 0);
        const totalCost = totalFuel + totalMaint;

        const avgCostTrip = totalTrips > 0 ? totalCost / totalTrips : 0;
        const avgCostTon = totalTons > 0 ? totalCost / totalTons : 0;
        const avgKmTrip = totalTrips > 0 ? totalDistance / totalTrips : 0;

        return { totalTrips, totalTons, totalFuel, totalMaint, totalDistance, avgCostTrip, avgCostTon, avgKmTrip };
    }, [sortedData]);

    const handlePrint = () => {
        printTable(tableContainerRef, title || t('sec_veh_eff'), filters, t, language);
    };

    if (tableData.length === 0) return null;

    return (
        <CollapsibleSection title={title || t('sec_veh_eff')}>
             <div className="flex items-center gap-4 mb-4 text-sm">
                <div>
                    <label htmlFor="tableSort" className="ml-2 font-semibold">{t('chart_grouping')}</label>
                    <select id="tableSort" value={sortBy} onChange={e => setSortBy(e.target.value as keyof VehicleTableData)}
                        className="p-2 border border-slate-300 rounded-lg">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-3 py-2 border-none rounded-lg bg-emerald-500 text-white text-sm font-semibold cursor-pointer shadow-md transition hover:bg-emerald-600">
                    {t('print')}
                </button>
            </div>
            <div className="overflow-x-auto" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse">
                    <thead className="bg-slate-100">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-2 border-b border-slate-200 font-semibold text-slate-600">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody>
                        {sortedData.map(row => (
                            <tr key={row.veh} className="hover:bg-slate-50">
                                <td className="p-2 border-b border-slate-200 font-bold">{row.veh}</td>
                                <td className="p-2 border-b border-slate-200">{areaMapping[row.area] || row.area}</td>
                                <td className={`p-2 border-b border-slate-200 ${row.drivers.includes(',') ? 'text-xs' : ''}`}>{row.drivers}</td>
                                <td className="p-2 border-b border-slate-200">{row.year}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.cap_m3, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.cap_ton, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.trips)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.tons, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.fuel, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.maint, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-semibold text-blue-600">{formatNumber(row.cost_trip, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-semibold text-blue-600">{formatNumber(row.cost_ton, 1)}</td>
                                <td className="p-2 border-b border-slate-200">{formatNumber(row.distance, 1)}</td>
                                <td className="p-2 border-b border-slate-200 font-semibold text-indigo-600">{formatNumber(row.km_per_trip, 1)}</td>
                            </tr>
                        ))}
                        {totals && (
                            <tr className="font-bold bg-slate-200">
                                <td className="p-2 border-b border-slate-300">{t('total_avg')}</td>
                                <td colSpan={5} className="p-2 border-b border-slate-300"></td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalTrips)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalTons, 1)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalFuel, 1)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalMaint, 1)}</td>
                                <td className="p-2 border-b border-slate-300 text-blue-700">{formatNumber(totals.avgCostTrip, 1)}</td>
                                <td className="p-2 border-b border-slate-300 text-blue-700">{formatNumber(totals.avgCostTon, 1)}</td>
                                <td className="p-2 border-b border-slate-300">{formatNumber(totals.totalDistance, 1)}</td>
                                <td className="p-2 border-b border-slate-300 text-indigo-800" colSpan={1}>{formatNumber(totals.avgKmTrip, 1)}</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

export default TableSection;

import React, { useMemo } from 'react';
import { Trip, Fuel, Maintenance, VehicleTableData, Worker, WasteTreatment } from '../types';
import { MONTHS_ORDER } from '../constants';
import { formatNumber } from '../services/dataService';
import KpiCard from './KpiCard';
import { useLanguage } from '../contexts/LanguageContext';

interface KpiGridProps {
    filteredTrips: Trip[];
    comparisonTrips: Trip[];
    fuelData: Fuel[];
    maintData: Maintenance[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    vehicleTableData: VehicleTableData[];
    comparisonVehicleTableData: VehicleTableData[];
    totalPopulation?: number;
    totalServed?: number;
    coverageRate?: number;
    workers: Worker[];
    revenueDetail?: { total: number; hh: number; commercial: number; recycling: number } | null;
    comparisonRevenueDetail?: { total: number; hh: number; commercial: number; recycling: number } | null;
    treatment?: (WasteTreatment & { totalTreated: number }) | null;
    comparisonTreatment?: (WasteTreatment & { totalTreated: number }) | null;
}

const KpiGrid: React.FC<KpiGridProps> = ({ 
    filteredTrips, comparisonTrips, fuelData, maintData, filters, 
    selectedYear, comparisonYear, vehicleTableData, comparisonVehicleTableData,
    totalPopulation, totalServed, coverageRate, workers,
    revenueDetail, comparisonRevenueDetail,
    treatment, comparisonTreatment
}) => {
    const { t } = useLanguage();

    const calculateStats = (trips: Trip[], year: string, tableData: VehicleTableData[]) => {
        if (!trips.length && !year) return null;

        const totalTons = trips.reduce<number>((sum, trip) => sum + (Number(trip['صافي التحميل']) || 0) / 1000, 0);
        const totalTrips = trips.length;
        const activeVehicles = new Set(trips.map(r => r['رقم المركبة']).filter(Boolean));

        const sumFuelForVehicle = (veh: string): number => {
            const row = fuelData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            if (!row) return 0;
            const monthsToSum = filters.months.size ? Array.from(filters.months) : MONTHS_ORDER;
            return monthsToSum.reduce<number>((s, m) => s + (Number(row[m as keyof Fuel]) || 0), 0);
        };

        const maintForVehicle = (veh: string): number => {
            const row = maintData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            return row ? (Number(row['كلفة الصيانة']) || 0) : 0;
        };

        let totalFuel = 0;
        let totalMaint = 0;
        activeVehicles.forEach(v => {
            totalFuel += sumFuelForVehicle(v);
            totalMaint += maintForVehicle(v);
        });

        const daysSet = new Set(trips.map(r => {
            const d = new Date(r['تاريخ التوزين الثاني']);
            return !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : null;
        }).filter(Boolean));
        const daysCount = daysSet.size;
        const avgTonsPerDay = daysCount > 0 ? totalTons / daysCount : 0;

        const agg: { [key: string]: { trips: number; tons: number } } = {};
        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!agg[v]) agg[v] = { trips: 0, tons: 0 };
            agg[v].trips += 1;
            agg[v].tons += (Number(r['صافي التحميل'] || 0) / 1000);
        });

        let topTripsVeh = "—", topTripsVal = 0, topTonsVeh = "—", topTonsVal = 0;
        Object.entries(agg).forEach(([v, data]) => {
            if (data.trips > topTripsVal) {
                topTripsVal = data.trips;
                topTripsVeh = v;
            }
            if (data.tons > topTonsVal) {
                topTonsVal = data.tons;
                topTonsVeh = v;
            }
        });

        const activeVehicleDetails = tableData.filter(v => activeVehicles.has(v.veh));
        const totalCapacity = activeVehicleDetails.reduce((sum, v) => sum + v.cap_ton, 0);
        const avgCapacity = activeVehicles.size > 0 ? totalCapacity / activeVehicles.size : 0;

        return {
            totalTons, totalTrips, totalFuel, totalMaint, avgTonsPerDay, daysCount,
            activeVehiclesCount: activeVehicles.size,
            topTrips: topTripsVal > 0 ? `${topTripsVeh} | ${formatNumber(topTripsVal)}` : '—',
            topTons: topTonsVal > 0 ? `${topTonsVeh} | ${formatNumber(topTonsVal, 1)} ${t('unit_ton')}` : '—',
            avgCapacity
        };
    };

    const currentStats = useMemo(() => calculateStats(filteredTrips, selectedYear, vehicleTableData), [filteredTrips, selectedYear, fuelData, maintData, filters, vehicleTableData]);
    const comparisonStats = useMemo(() => comparisonYear ? calculateStats(comparisonTrips, comparisonYear, comparisonVehicleTableData) : null, [comparisonTrips, comparisonYear, fuelData, maintData, filters, comparisonVehicleTableData]);

    const totalSalaries = useMemo(() => {
        return workers.reduce((sum, w) => sum + w.salary, 0);
    }, [workers]);

    const metrics = useMemo(() => {
        if (!currentStats) return null;

        const totalCosts = currentStats.totalFuel + currentStats.totalMaint + totalSalaries;
        const costPerTon = currentStats.totalTons > 0 ? totalCosts / currentStats.totalTons : 0;
        const costPerTrip = currentStats.totalTrips > 0 ? totalCosts / currentStats.totalTrips : 0;
        const avgTonsPerTrip = currentStats.totalTrips > 0 ? currentStats.totalTons / currentStats.totalTrips : 0;
        const avgTripsPerDay = currentStats.daysCount > 0 ? currentStats.totalTrips / currentStats.daysCount : 0;

        const kgPerCapita = (totalPopulation && totalPopulation > 0) ? (currentStats.totalTons * 1000) / totalPopulation : 0;
        const costPerCapita = (totalPopulation && totalPopulation > 0) ? totalCosts / totalPopulation : 0;

        const avgTripsPerVehicle = currentStats.activeVehiclesCount > 0 ? currentStats.totalTrips / currentStats.activeVehiclesCount : 0;
        const areasCount = totalPopulation ? 7 : 0; 

        const currentRevenueTotal = revenueDetail?.total || 0;
        const costRecovery = totalCosts > 0 ? (currentRevenueTotal / totalCosts) * 100 : 0;

        const totalGenerated = currentStats.totalTons + (treatment?.totalTreated || 0);
        const recyclingRate = totalGenerated > 0 ? ((treatment?.recyclablesTon || 0) / totalGenerated) * 100 : 0;
        const alternativeTreatmentRate = totalGenerated > 0 ? ((treatment?.totalTreated || 0) / totalGenerated) * 100 : 0;

        // حساب عدد عمال الوطن فقط
        const cleanersCount = workers.filter(w => w.role === 'عامل وطن').length;
        const popPerCleaner = (totalPopulation && totalPopulation > 0 && cleanersCount > 0) 
            ? totalPopulation / cleanersCount 
            : 0;

        return { 
            totalCosts, costPerTon, costPerTrip, avgTonsPerTrip, avgTripsPerDay, 
            kgPerCapita, areasCount, costPerCapita, avgTripsPerVehicle, 
            costRecovery, totalGenerated, recyclingRate, alternativeTreatmentRate,
            cleanersCount, popPerCleaner
        };
    }, [currentStats, totalSalaries, totalPopulation, revenueDetail, treatment, workers]);

    if (!currentStats || !metrics) return null;

    const sections = [
        {
            title: t('sec_population'),
            cards: [
                { value: formatNumber(totalPopulation), label: t('kpi_total_pop'), icon: '👥', color: 'text-cyan-600', emphasized: true },
                { value: formatNumber(totalServed), label: t('kpi_served_pop'), icon: '🏠', color: 'text-emerald-600' },
                { value: formatNumber(coverageRate, 1) + '%', label: t('kpi_coverage_rate'), icon: '📡', color: 'text-indigo-600' },
                { value: formatNumber(metrics.popPerCleaner), label: t('kpi_pop_per_cleaner'), icon: '🚶', color: 'text-amber-600' },
                { value: formatNumber(metrics.areasCount), label: t('kpi_areas_served'), icon: '📍', color: 'text-rose-500' },
                { value: formatNumber(workers.length), label: t('kpi_workers_count'), icon: '👷', color: 'text-slate-700' }
            ]
        },
        {
            title: t('sec_operational'),
            cards: [
                { value: formatNumber(currentStats.totalTrips), label: t('kpi_total_trips'), icon: '🚚', color: 'text-sky-500', comp: comparisonStats?.totalTrips ? formatNumber(comparisonStats.totalTrips) : undefined, emphasized: true },
                { value: formatNumber(currentStats.daysCount), label: t('kpi_op_days'), icon: '📅', color: 'text-pink-600', comp: comparisonStats?.daysCount ? formatNumber(comparisonStats.daysCount) : undefined },
                { value: formatNumber(metrics.avgTripsPerDay, 1), label: t('kpi_avg_trips_day'), icon: '🔄', color: 'text-sky-600' },
                { value: formatNumber(metrics.avgTonsPerTrip, 1), label: t('kpi_avg_load_trip'), icon: '⚖️', color: 'text-slate-600' },
                { value: formatNumber(currentStats.avgTonsPerDay, 1), label: t('kpi_avg_tons_day'), icon: '📊', color: 'text-green-600', comp: comparisonStats?.avgTonsPerDay ? formatNumber(comparisonStats.avgTonsPerDay, 1) : undefined }
            ]
        },
        {
            title: t('sec_waste_production'),
            cards: [
                { value: formatNumber(Math.round(metrics.totalGenerated)), label: t('kpi_total_tons'), icon: '🗑️', color: 'text-blue-600', emphasized: true },
                { value: formatNumber(metrics.kgPerCapita, 1) + ' ' + t('unit_kg'), label: t('kpi_per_capita_waste'), icon: '👤', color: 'text-indigo-500' },
                { value: formatNumber(currentStats.avgTonsPerDay, 1), label: t('kpi_daily_waste_rate'), icon: '📈', color: 'text-teal-600' }
            ]
        },
        {
            title: t('sec_treatment'),
            cards: [
                { value: formatNumber(metrics.recyclingRate, 1) + '%', label: t('kpi_recycling_rate'), icon: '♻️', color: 'text-emerald-600', emphasized: true },
                { value: formatNumber(metrics.alternativeTreatmentRate, 1) + '%', label: t('kpi_alt_treatment_rate'), icon: '🧪', color: 'text-indigo-600' },
                { value: formatNumber(treatment?.totalTreated, 1) + ' ' + t('unit_ton'), label: t('kpi_total_treated'), icon: '⚙️', color: 'text-blue-500' },
                { value: formatNumber(treatment?.recyclablesTon, 1) + ' ' + t('unit_ton'), label: t('kpi_recyclables'), icon: '📦', color: 'text-amber-500' },
                { value: formatNumber(treatment?.biowasteTon, 1) + ' ' + t('unit_ton'), label: t('kpi_biowaste'), icon: '🍎', color: 'text-orange-600' }
            ]
        },
        {
            title: t('sec_fleet'),
            cards: [
                { value: formatNumber(currentStats.activeVehiclesCount), label: t('kpi_active_vehicles'), icon: '🚛', color: 'text-purple-600', comp: comparisonStats?.activeVehiclesCount ? formatNumber(comparisonStats.activeVehiclesCount) : undefined, emphasized: true },
                { value: formatNumber(currentStats.avgCapacity, 1), label: t('kpi_avg_capacity'), icon: '📦', color: 'text-amber-500', comp: comparisonStats?.avgCapacity ? formatNumber(comparisonStats.avgCapacity, 1) : undefined },
                { value: currentStats.topTrips, label: t('kpi_top_trips_veh'), icon: '🏆', color: 'text-indigo-600', comp: comparisonStats?.topTrips },
                { value: currentStats.topTons, label: t('kpi_top_weight_veh'), icon: '🏗️', color: 'text-teal-500', comp: comparisonStats?.topTons },
                { value: formatNumber(metrics.avgTripsPerVehicle, 1), label: t('kpi_avg_trips_veh'), icon: '🚜', color: 'text-orange-600' }
            ]
        },
        {
            title: t('sec_financial'),
            cards: [
                { value: formatNumber(Math.round(metrics.totalCosts)) + ' ' + t('unit_jd'), label: t('kpi_total_annual_expenses'), icon: '📈', color: 'text-emerald-800', emphasized: true },
                { value: formatNumber(Math.round(revenueDetail?.total || 0)) + ' ' + t('unit_jd'), label: t('kpi_total_revenue'), icon: '💰', color: 'text-blue-800', comp: comparisonRevenueDetail?.total ? formatNumber(Math.round(comparisonRevenueDetail.total)) : undefined, emphasized: true },
                { value: formatNumber(Math.round(revenueDetail?.hh || 0)) + ' ' + t('unit_jd'), label: t('kpi_hh_revenue'), icon: '🏠', color: 'text-blue-600' },
                { value: formatNumber(Math.round(revenueDetail?.commercial || 0)) + ' ' + t('unit_jd'), label: t('kpi_commercial_revenue'), icon: '🏢', color: 'text-indigo-600' },
                { value: formatNumber(metrics.costRecovery, 1) + '%', label: t('kpi_cost_recovery'), icon: '📈', color: 'text-indigo-700' },
                { value: formatNumber(Math.round(totalSalaries)), label: t('kpi_total_salaries'), icon: '💵', color: 'text-emerald-700' },
                { value: formatNumber(Math.round(currentStats.totalFuel)), label: t('kpi_fuel_cost'), icon: '⛽', color: 'text-orange-500', comp: comparisonStats?.totalFuel ? formatNumber(Math.round(comparisonStats.totalFuel)) : undefined },
                { value: formatNumber(Math.round(currentStats.totalMaint)), label: t('kpi_maint_cost'), icon: '🔧', color: 'text-red-600', comp: comparisonStats?.totalMaint ? formatNumber(Math.round(comparisonStats.totalMaint)) : undefined },
                { value: formatNumber(metrics.costPerTon, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_ton'), icon: '💰', color: 'text-amber-600' },
                { value: formatNumber(metrics.costPerTrip, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_trip'), icon: '🎟️', color: 'text-blue-700' },
                { value: formatNumber(metrics.costPerCapita, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_capita'), icon: '🏷️', color: 'text-slate-800' }
            ]
        }
    ];

    const getGridColsClass = (count: number) => {
        if (count <= 3) return "md:grid-cols-3";
        if (count === 5) return "md:grid-cols-3 lg:grid-cols-5";
        return "md:grid-cols-3 lg:grid-cols-4";
    };

    return (
        <div id="kpi-grid" className="space-y-12 mb-12">
            {sections.map((section, sIdx) => (
                <div key={sIdx} className="space-y-6 bg-slate-50/40 p-8 rounded-[40px] border border-slate-100/50 shadow-sm transition-all duration-300">
                    <div className="flex items-center gap-4 px-2">
                        <div className="h-10 w-2 bg-blue-600 rounded-full shadow-sm shadow-blue-200"></div>
                        <h3 className="text-xl font-black text-slate-800 tracking-tight">
                            {section.title}
                        </h3>
                        <div className="flex-1 h-px bg-gradient-to-l from-slate-200 to-transparent"></div>
                    </div>

                    <div className={`grid grid-cols-1 sm:grid-cols-2 ${getGridColsClass(section.cards.length)} gap-6 justify-center`}>
                        {section.cards.map((kpi, kIdx) => (
                            <div key={`${sIdx}-${kIdx}`} className={kpi.emphasized ? 'transform lg:scale-105 z-10' : ''}>
                                <KpiCard 
                                    value={kpi.value} 
                                    label={kpi.label} 
                                    icon={kpi.icon} 
                                    color={kpi.color} 
                                    comparisonValue={kpi.comp}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default KpiGrid;

import React, { useMemo } from 'react';
import { Trip, WasteTreatment, Population, Worker, Revenue, VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import KpiCard from './KpiCard';
import { useLanguage } from '../contexts/LanguageContext';

interface AnnualSummarySectionProps {
    filteredTrips: Trip[];
    treatment?: (WasteTreatment & { totalTreated: number }) | null;
    populationData: Population[];
    workers: Worker[];
    revenues: Revenue[];
    vehicleTableData: VehicleTableData[];
    selectedYear: string;
}

const AnnualSummarySection: React.FC<AnnualSummarySectionProps> = ({ 
    filteredTrips, treatment, populationData, workers, revenues, vehicleTableData, selectedYear 
}) => {
    const { t } = useLanguage();

    const stats = useMemo(() => {
        // 1. النفايات
        const totalCollectedTons = filteredTrips.reduce((sum, trip) => sum + (Number(trip['صافي التحميل']) || 0) / 1000, 0);
        const totalTreated = treatment?.totalTreated || 0;
        const totalGeneratedTons = totalCollectedTons + totalTreated;

        const yearPopData = populationData.filter(p => p.year === selectedYear);
        const totalPopulation = yearPopData.reduce((sum, p) => sum + p.population, 0);
        const totalServed = yearPopData.reduce((sum, p) => sum + p.served, 0);

        const wastePerCapita = totalPopulation > 0 ? (totalGeneratedTons * 1000) / totalPopulation / 365 : 0;

        // 2. الخدمة
        const coverageRate = totalPopulation > 0 ? (totalServed / totalPopulation) * 100 : 0;

        // 3. المؤشرات المالية
        const totalSalaries = workers.reduce((sum, w) => sum + w.salary, 0);
        const totalFuel = vehicleTableData.reduce((sum, v) => sum + v.fuel, 0);
        const totalMaint = vehicleTableData.reduce((sum, v) => sum + v.maint, 0);
        const totalCost = totalSalaries + totalFuel + totalMaint;

        const costPerTon = totalGeneratedTons > 0 ? totalCost / totalGeneratedTons : 0;
        const costPerCapita = totalPopulation > 0 ? totalCost / totalPopulation : 0;

        // حساب نسبة كلفة القدرة على التحمل (Cost Affordability)
        // الحد المسموح به للبلديات من الفئة الثانية هو 4.9 دينار للفرد سنوياً
        const affordabilityLimit = 4.9;
        const costAffordability = (costPerCapita / affordabilityLimit) * 100;

        const yearRevenues = revenues.filter(r => r.year === selectedYear);
        const totalRevenue = yearRevenues.reduce((sum, r) => sum + r.hhFees + r.commercialFees + r.recyclingRevenue, 0);

        const costRecovery = totalCost > 0 ? (totalRevenue / totalCost) * 100 : 0;

        // 4. المعالجة
        const recyclingRate = totalGeneratedTons > 0 ? ((treatment?.recyclablesTon || 0) / totalGeneratedTons) * 100 : 0;
        const diversionRate = totalGeneratedTons > 0 ? (totalTreated / totalGeneratedTons) * 100 : 0;

        return {
            totalGeneratedTons,
            wastePerCapita,
            totalPopulation,
            coverageRate,
            totalCost,
            costPerTon,
            costPerCapita,
            costAffordability,
            totalRevenue,
            costRecovery,
            recyclingRate,
            diversionRate
        };
    }, [filteredTrips, treatment, populationData, workers, revenues, vehicleTableData, selectedYear]);

    const groups = [
        {
            title: t('group_waste'),
            cards: [
                { value: formatNumber(Math.round(stats.totalGeneratedTons)) + ' ' + t('unit_ton'), label: t('kpi_sum_total_waste'), icon: '🗑️', color: 'text-blue-600' },
                { value: formatNumber(stats.wastePerCapita, 2) + ' ' + t('unit_kg'), label: t('kpi_sum_waste_capita'), icon: '👤', color: 'text-sky-500' },
            ]
        },
        {
            title: t('group_service'),
            cards: [
                { value: formatNumber(stats.totalPopulation), label: t('kpi_total_pop'), icon: '👥', color: 'text-cyan-600' },
                { value: formatNumber(stats.coverageRate, 1) + '%', label: t('kpi_sum_coverage'), icon: '📡', color: 'text-emerald-600' },
            ]
        },
        {
            title: t('group_financial'),
            cards: [
                { value: formatNumber(Math.round(stats.totalCost)) + ' ' + t('unit_jd'), label: t('kpi_sum_total_cost'), icon: '📈', color: 'text-indigo-600' },
                { value: formatNumber(stats.costPerTon, 1) + ' ' + t('unit_jd'), label: t('kpi_sum_cost_ton'), icon: '💰', color: 'text-amber-600' },
                { value: formatNumber(stats.costPerCapita, 1) + ' ' + t('unit_jd'), label: t('kpi_sum_cost_capita'), icon: '🏷️', color: 'text-slate-700' },
                { 
                    value: formatNumber(stats.costAffordability, 1) + '%', 
                    label: t('kpi_sum_cost_affordability'), 
                    icon: '🛡️', 
                    color: stats.costAffordability > 100 ? 'text-red-600' : 'text-indigo-600' 
                },
                { value: formatNumber(Math.round(stats.totalRevenue)) + ' ' + t('unit_jd'), label: t('kpi_sum_total_revenue'), icon: '💵', color: 'text-blue-700' },
                { value: formatNumber(stats.costRecovery, 1) + '%', label: t('kpi_sum_cost_recovery'), icon: '⚖️', color: 'text-teal-600' },
            ]
        },
        {
            title: t('group_treatment'),
            cards: [
                { value: formatNumber(stats.recyclingRate, 1) + '%', label: t('kpi_sum_recycling'), icon: '♻️', color: 'text-emerald-700' },
                { value: formatNumber(stats.diversionRate, 1) + '%', label: t('kpi_sum_diversion'), icon: '🧪', color: 'text-purple-600' },
            ]
        }
    ];

    return (
        <div id="annual-summary-content" className="space-y-10 animate-in fade-in duration-500">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 flex justify-between items-center">
                <h2 className="text-2xl font-black text-slate-800">{t('sec_annual_summary')} - {selectedYear}</h2>
                <div className="px-6 py-2 bg-blue-50 text-blue-700 rounded-2xl font-bold border border-blue-100">
                    {t('primary_kpi')}
                </div>
            </div>

            {groups.map((group, gIdx) => (
                <div key={gIdx} className="space-y-6">
                    <div className="flex items-center gap-4 px-2">
                        <div className="h-8 w-1.5 bg-slate-300 rounded-full"></div>
                        <h3 className="text-lg font-bold text-slate-600 tracking-tight">
                            {group.title}
                        </h3>
                        <div className="flex-1 h-px bg-slate-100"></div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6">
                        {group.cards.map((kpi, kIdx) => (
                            <KpiCard 
                                key={`${gIdx}-${kIdx}`}
                                value={kpi.value} 
                                label={kpi.label} 
                                icon={kpi.icon} 
                                color={kpi.color} 
                            />
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default AnnualSummarySection;

import React, { useMemo } from 'react';
import { Trip, Fuel, Maintenance, VehicleTableData, Worker, WasteTreatment } from '../types';
import { MONTHS_ORDER } from '../constants';
import { formatNumber } from '../services/dataService';
import KpiCard from './KpiCard';
import { useLanguage } from '../contexts/LanguageContext';

interface KpiGridProps {
    filteredTrips: Trip[];
    comparisonTrips: Trip[];
    fuelData: Fuel[];
    maintData: Maintenance[];
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    vehicleTableData: VehicleTableData[];
    comparisonVehicleTableData: VehicleTableData[];
    totalPopulation?: number;
    totalServed?: number;
    coverageRate?: number;
    workers: Worker[];
    revenueDetail?: { total: number; hh: number; commercial: number; recycling: number } | null;
    comparisonRevenueDetail?: { total: number; hh: number; commercial: number; recycling: number } | null;
    treatment?: (WasteTreatment & { totalTreated: number }) | null;
    comparisonTreatment?: (WasteTreatment & { totalTreated: number }) | null;
}

const KpiGrid: React.FC<KpiGridProps> = ({ 
    filteredTrips, comparisonTrips, fuelData, maintData, filters, 
    selectedYear, comparisonYear, vehicleTableData, comparisonVehicleTableData,
    totalPopulation, totalServed, coverageRate, workers,
    revenueDetail, comparisonRevenueDetail,
    treatment, comparisonTreatment
}) => {
    const { t } = useLanguage();

    const calculateStats = (trips: Trip[], year: string, tableData: VehicleTableData[]) => {
        if (!trips.length && !year) return null;

        const totalTons = trips.reduce<number>((sum, trip) => sum + (Number(trip['صافي التحميل']) || 0) / 1000, 0);
        const totalTrips = trips.length;
        const activeVehicles = new Set(trips.map(r => r['رقم المركبة']).filter(Boolean));

        const sumFuelForVehicle = (veh: string): number => {
            const row = fuelData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            if (!row) return 0;
            const monthsToSum = filters.months.size ? Array.from(filters.months) : MONTHS_ORDER;
            return monthsToSum.reduce<number>((s, m) => s + (Number(row[m as keyof Fuel]) || 0), 0);
        };

        const maintForVehicle = (veh: string): number => {
            const row = maintData.find(x => x['رقم المركبة'] === veh && x['السنة'] === year);
            return row ? (Number(row['كلفة الصيانة']) || 0) : 0;
        };

        let totalFuel = 0;
        let totalMaint = 0;
        activeVehicles.forEach(v => {
            totalFuel += sumFuelForVehicle(v);
            totalMaint += maintForVehicle(v);
        });

        const daysSet = new Set(trips.map(r => {
            const d = new Date(r['تاريخ التوزين الثاني']);
            return !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : null;
        }).filter(Boolean));
        const daysCount = daysSet.size;
        const avgTonsPerDay = daysCount > 0 ? totalTons / daysCount : 0;

        const agg: { [key: string]: { trips: number; tons: number } } = {};
        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!agg[v]) agg[v] = { trips: 0, tons: 0 };
            agg[v].trips += 1;
            agg[v].tons += (Number(r['صافي التحميل'] || 0) / 1000);
        });

        let topTripsVeh = "—", topTripsVal = 0, topTonsVeh = "—", topTonsVal = 0;
        Object.entries(agg).forEach(([v, data]) => {
            if (data.trips > topTripsVal) {
                topTripsVal = data.trips;
                topTripsVeh = v;
            }
            if (data.tons > topTonsVal) {
                topTonsVal = data.tons;
                topTonsVeh = v;
            }
        });

        const activeVehicleDetails = tableData.filter(v => activeVehicles.has(v.veh));
        const totalCapacity = activeVehicleDetails.reduce((sum, v) => sum + v.cap_ton, 0);
        const avgCapacity = activeVehicles.size > 0 ? totalCapacity / activeVehicles.size : 0;

        return {
            totalTons, totalTrips, totalFuel, totalMaint, avgTonsPerDay, daysCount,
            activeVehiclesCount: activeVehicles.size,
            topTrips: topTripsVal > 0 ? `${topTripsVeh} | ${formatNumber(topTripsVal)}` : '—',
            topTons: topTonsVal > 0 ? `${topTonsVeh} | ${formatNumber(topTonsVal, 1)} ${t('unit_ton')}` : '—',
            avgCapacity
        };
    };

    const currentStats = useMemo(() => calculateStats(filteredTrips, selectedYear, vehicleTableData), [filteredTrips, selectedYear, fuelData, maintData, filters, vehicleTableData]);
    const comparisonStats = useMemo(() => comparisonYear ? calculateStats(comparisonTrips, comparisonYear, comparisonVehicleTableData) : null, [comparisonTrips, comparisonYear, fuelData, maintData, filters, comparisonVehicleTableData]);

    const totalSalaries = useMemo(() => {
        return workers.reduce((sum, w) => sum + w.salary, 0);
    }, [workers]);

    const metrics = useMemo(() => {
        if (!currentStats) return null;

        const totalCosts = currentStats.totalFuel + currentStats.totalMaint + totalSalaries;
        const costPerTon = currentStats.totalTons > 0 ? totalCosts / currentStats.totalTons : 0;
        const costPerTrip = currentStats.totalTrips > 0 ? totalCosts / currentStats.totalTrips : 0;
        const avgTonsPerTrip = currentStats.totalTrips > 0 ? currentStats.totalTons / currentStats.totalTrips : 0;
        const avgTripsPerDay = currentStats.daysCount > 0 ? currentStats.totalTrips / currentStats.daysCount : 0;

        const kgPerCapita = (totalPopulation && totalPopulation > 0) ? (currentStats.totalTons * 1000) / totalPopulation : 0;
        const costPerCapita = (totalPopulation && totalPopulation > 0) ? totalCosts / totalPopulation : 0;

        // حساب نسبة كلفة القدرة على التحمل (Cost Affordability)
        // الحد المسموح به هو 4.9 دينار للفرد سنوياً
        const affordabilityLimit = 4.9;
        const costAffordability = (costPerCapita / affordabilityLimit) * 100;

        const avgTripsPerVehicle = currentStats.activeVehiclesCount > 0 ? currentStats.totalTrips / currentStats.activeVehiclesCount : 0;
        const areasCount = totalPopulation ? 7 : 0; 

        const currentRevenueTotal = revenueDetail?.total || 0;
        const costRecovery = totalCosts > 0 ? (currentRevenueTotal / totalCosts) * 100 : 0;

        const totalGenerated = currentStats.totalTons + (treatment?.totalTreated || 0);
        const recyclingRate = totalGenerated > 0 ? ((treatment?.recyclablesTon || 0) / totalGenerated) * 100 : 0;
        const alternativeTreatmentRate = totalGenerated > 0 ? ((treatment?.totalTreated || 0) / totalGenerated) * 100 : 0;

        // حساب عدد عمال الوطن فقط
        const cleanersCount = workers.filter(w => w.role === 'عامل وطن').length;
        const popPerCleaner = (totalPopulation && totalPopulation > 0 && cleanersCount > 0) 
            ? totalPopulation / cleanersCount 
            : 0;

        return { 
            totalCosts, costPerTon, costPerTrip, avgTonsPerTrip, avgTripsPerDay, 
            kgPerCapita, areasCount, costPerCapita, costAffordability, avgTripsPerVehicle, 
            costRecovery, totalGenerated, recyclingRate, alternativeTreatmentRate,
            cleanersCount, popPerCleaner
        };
    }, [currentStats, totalSalaries, totalPopulation, revenueDetail, treatment, workers]);

    if (!currentStats || !metrics) return null;

    const sections = [
        {
            title: t('sec_population'),
            cards: [
                { value: formatNumber(totalPopulation), label: t('kpi_total_pop'), icon: '👥', color: 'text-cyan-600', emphasized: true },
                { value: formatNumber(totalServed), label: t('kpi_served_pop'), icon: '🏠', color: 'text-emerald-600' },
                { value: formatNumber(coverageRate, 1) + '%', label: t('kpi_coverage_rate'), icon: '📡', color: 'text-indigo-600' },
                { value: formatNumber(metrics.popPerCleaner), label: t('kpi_pop_per_cleaner'), icon: '🚶', color: 'text-amber-600' },
                { value: formatNumber(metrics.areasCount), label: t('kpi_areas_served'), icon: '📍', color: 'text-rose-500' },
                { value: formatNumber(workers.length), label: t('kpi_workers_count'), icon: '👷', color: 'text-slate-700' }
            ]
        },
        {
            title: t('sec_operational'),
            cards: [
                { value: formatNumber(currentStats.totalTrips), label: t('kpi_total_trips'), icon: '🚚', color: 'text-sky-500', comp: comparisonStats?.totalTrips ? formatNumber(comparisonStats.totalTrips) : undefined, emphasized: true },
                { value: formatNumber(currentStats.daysCount), label: t('kpi_op_days'), icon: '📅', color: 'text-pink-600', comp: comparisonStats?.daysCount ? formatNumber(comparisonStats.daysCount) : undefined },
                { value: formatNumber(metrics.avgTripsPerDay, 1), label: t('kpi_avg_trips_day'), icon: '🔄', color: 'text-sky-600' },
                { value: formatNumber(metrics.avgTonsPerTrip, 1), label: t('kpi_avg_load_trip'), icon: '⚖️', color: 'text-slate-600' },
                { value: formatNumber(currentStats.avgTonsPerDay, 1), label: t('kpi_avg_tons_day'), icon: '📊', color: 'text-green-600', comp: comparisonStats?.avgTonsPerDay ? formatNumber(comparisonStats.avgTonsPerDay, 1) : undefined }
            ]
        },
        {
            title: t('sec_waste_production'),
            cards: [
                { value: formatNumber(Math.round(metrics.totalGenerated)), label: t('kpi_total_tons'), icon: '🗑️', color: 'text-blue-600', emphasized: true },
                { value: formatNumber(metrics.kgPerCapita, 1) + ' ' + t('unit_kg'), label: t('kpi_per_capita_waste'), icon: '👤', color: 'text-indigo-500' },
                { value: formatNumber(currentStats.avgTonsPerDay, 1), label: t('kpi_daily_waste_rate'), icon: '📈', color: 'text-teal-600' }
            ]
        },
        {
            title: t('sec_treatment'),
            cards: [
                { value: formatNumber(metrics.recyclingRate, 1) + '%', label: t('kpi_recycling_rate'), icon: '♻️', color: 'text-emerald-600', emphasized: true },
                { value: formatNumber(metrics.alternativeTreatmentRate, 1) + '%', label: t('kpi_alt_treatment_rate'), icon: '🧪', color: 'text-indigo-600' },
                { value: formatNumber(treatment?.totalTreated, 1) + ' ' + t('unit_ton'), label: t('kpi_total_treated'), icon: '⚙️', color: 'text-blue-500' },
                { value: formatNumber(treatment?.recyclablesTon, 1) + ' ' + t('unit_ton'), label: t('kpi_recyclables'), icon: '📦', color: 'text-amber-500' },
                { value: formatNumber(treatment?.biowasteTon, 1) + ' ' + t('unit_ton'), label: t('kpi_biowaste'), icon: '🍎', color: 'text-orange-600' }
            ]
        },
        {
            title: t('sec_fleet'),
            cards: [
                { value: formatNumber(currentStats.activeVehiclesCount), label: t('kpi_active_vehicles'), icon: '🚛', color: 'text-purple-600', comp: comparisonStats?.activeVehiclesCount ? formatNumber(comparisonStats.activeVehiclesCount) : undefined, emphasized: true },
                { value: formatNumber(currentStats.avgCapacity, 1), label: t('kpi_avg_capacity'), icon: '📦', color: 'text-amber-500', comp: comparisonStats?.avgCapacity ? formatNumber(comparisonStats.avgCapacity, 1) : undefined },
                { value: currentStats.topTrips, label: t('kpi_top_trips_veh'), icon: '🏆', color: 'text-indigo-600', comp: comparisonStats?.topTrips },
                { value: currentStats.topTons, label: t('kpi_top_weight_veh'), icon: '🏗️', color: 'text-teal-500', comp: comparisonStats?.topTons },
                { value: formatNumber(metrics.avgTripsPerVehicle, 1), label: t('kpi_avg_trips_veh'), icon: '🚜', color: 'text-orange-600' }
            ]
        },
        {
            title: t('sec_financial'),
            cards: [
                { value: formatNumber(Math.round(metrics.totalCosts)) + ' ' + t('unit_jd'), label: t('kpi_total_annual_expenses'), icon: '📈', color: 'text-emerald-800', emphasized: true },
                { value: formatNumber(Math.round(revenueDetail?.total || 0)) + ' ' + t('unit_jd'), label: t('kpi_total_revenue'), icon: '💰', color: 'text-blue-800', comp: comparisonRevenueDetail?.total ? formatNumber(Math.round(comparisonRevenueDetail.total)) : undefined, emphasized: true },
                { value: formatNumber(Math.round(revenueDetail?.hh || 0)) + ' ' + t('unit_jd'), label: t('kpi_hh_revenue'), icon: '🏠', color: 'text-blue-600' },
                { value: formatNumber(Math.round(revenueDetail?.commercial || 0)) + ' ' + t('unit_jd'), label: t('kpi_commercial_revenue'), icon: '🏢', color: 'text-indigo-600' },
                { value: formatNumber(metrics.costRecovery, 1) + '%', label: t('kpi_cost_recovery'), icon: '📈', color: 'text-indigo-700' },
                { value: formatNumber(Math.round(totalSalaries)), label: t('kpi_total_salaries'), icon: '💵', color: 'text-emerald-700' },
                { value: formatNumber(Math.round(currentStats.totalFuel)), label: t('kpi_fuel_cost'), icon: '⛽', color: 'text-orange-500', comp: comparisonStats?.totalFuel ? formatNumber(Math.round(comparisonStats.totalFuel)) : undefined },
                { value: formatNumber(Math.round(currentStats.totalMaint)), label: t('kpi_maint_cost'), icon: '🔧', color: 'text-red-600', comp: comparisonStats?.totalMaint ? formatNumber(Math.round(comparisonStats.totalMaint)) : undefined },
                { value: formatNumber(metrics.costPerTon, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_ton'), icon: '💰', color: 'text-amber-600' },
                { value: formatNumber(metrics.costPerTrip, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_trip'), icon: '🎟️', color: 'text-blue-700' },
                { value: formatNumber(metrics.costPerCapita, 1) + ' ' + t('unit_jd'), label: t('kpi_cost_per_capita'), icon: '🏷️', color: 'text-slate-800' },
                { 
                    value: formatNumber(metrics.costAffordability, 1) + '%', 
                    label: t('kpi_cost_affordability'), 
                    icon: '🛡️', 
                    color: metrics.costAffordability > 100 ? 'text-red-600' : 'text-indigo-600' 
                },
            ]
        }
    ];

    const getGridColsClass = (count: number) => {
        if (count <= 3) return "md:grid-cols-3";
        if (count === 5) return "md:grid-cols-3 lg:grid-cols-5";
        return "md:grid-cols-3 lg:grid-cols-4";
    };

    return (
        <div id="kpi-grid" className="space-y-12 mb-12">
            {sections.map((section, sIdx) => (
                <div key={sIdx} className="space-y-6 bg-slate-50/40 p-8 rounded-[40px] border border-slate-100/50 shadow-sm transition-all duration-300">
                    <div className="flex items-center gap-4 px-2">
                        <div className="h-10 w-2 bg-blue-600 rounded-full shadow-sm shadow-blue-200"></div>
                        <h3 className="text-xl font-black text-slate-800 tracking-tight">
                            {section.title}
                        </h3>
                        <div className="flex-1 h-px bg-gradient-to-l from-slate-200 to-transparent"></div>
                    </div>

                    <div className={`grid grid-cols-1 sm:grid-cols-2 ${getGridColsClass(section.cards.length)} gap-6 justify-center`}>
                        {section.cards.map((kpi, kIdx) => (
                            <div key={`${sIdx}-${kIdx}`} className={kpi.emphasized ? 'transform lg:scale-105 z-10' : ''}>
                                <KpiCard 
                                    value={kpi.value} 
                                    label={kpi.label} 
                                    icon={kpi.icon} 
                                    color={kpi.color} 
                                    comparisonValue={kpi.comp}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default KpiGrid;

import React, { createContext, useContext, useState, useEffect } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem('app_theme') as Theme;
    return saved || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  });

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('app_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
