                        }
                        .section-title {
                            font-size: 20px;
                            font-weight: 700;
                            color: #1e293b;
                            border-${language === 'ar' ? 'right' : 'left'}: 5px solid #2563eb;
                            padding-${language === 'ar' ? 'right' : 'left'}: 15px;
                            margin-bottom: 20px;
                            background: #f8fafc;
                            padding-top: 5px;
                            padding-bottom: 5px;
                        }
                        .kpi-grid-container {
                            display: grid;
                            grid-template-columns: repeat(3, 1fr);
                            gap: 15px;
                        }
