                                </>
                            )}
                            {activeMetric === 'efficiency' && (
                                <>
                                    <Bar yAxisId="left" dataKey="tonsPerWorker" name={t('th_avg_load')} fill="#f59e0b" radius={[6, 6, 0, 0]} />
