import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

interface KpiExplanationModalProps {
    isOpen: boolean;
    onClose: () => void;
    label: string;
}

const KpiExplanationModal: React.FC<KpiExplanationModalProps> = ({ isOpen, onClose, label }) => {
    const { t, language } = useLanguage();

    if (!isOpen) return null;

    // Map labels to explanation keys
    const getExplanationKey = (lbl: string) => {
        const lowerLabel = lbl.toLowerCase();
        if (lowerLabel.includes('إجمالي') || lowerLabel.includes('total tons')) return 'exp_total_tons';
        if (lowerLabel.includes('كلفة الطن') || lowerLabel.includes('cost per ton')) return 'exp_cost_ton';
        if (lowerLabel.includes('استرداد') || lowerLabel.includes('recovery')) return 'exp_cost_recovery';
        if (lowerLabel.includes('تغطية') || lowerLabel.includes('coverage')) return 'exp_coverage_rate';
        if (lowerLabel.includes('تدوير') || lowerLabel.includes('recycling')) return 'exp_recycling_rate';
        if (lowerLabel.includes('استغلال') || lowerLabel.includes('utilization')) return 'exp_utilization';
        if (lowerLabel.includes('الفرد') || lowerLabel.includes('capita')) return 'exp_waste_capita';
        return null;
    };

    const key = getExplanationKey(label);
    const exp = key ? (t(key) as any) : null;

    const isRtl = language === 'ar';

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div 
                className="bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[32px] shadow-2xl overflow-hidden border border-slate-100 dark:border-slate-800"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 text-white flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <span className="text-2xl">💡</span>
                        <h3 className="font-black text-xl tracking-tight">{t('kpi_guide')}</h3>
                    </div>
                    <button 
                        onClick={onClose}
                        className="p-2 hover:bg-white/20 rounded-full transition-colors"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>

                {/* Content */}
                <div className={`p-8 max-h-[70vh] overflow-y-auto ${isRtl ? 'text-right' : 'text-left'} space-y-6 custom-scrollbar`}>
                    <div className="border-b border-slate-100 dark:border-slate-800 pb-4">
                        <span className="text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest">{t('menu_kpi')}</span>
