                    {!exp ? (
                        <div className="py-10 text-center text-slate-500">{isRtl ? 'عذراً، لا يوجد شرح مفصل متاح لهذا المؤشر حالياً.' : 'Sorry, no detailed explanation available for this indicator yet.'}</div>
                    ) : (
                        <div className="grid gap-6">
                            <Section icon="❓" title={t('what_is_it')} content={exp.what} color="blue" />
                            <Section icon="🎯" title={t('why_important')} content={exp.why} color="emerald" />
                            <Section icon="🧮" title={t('how_calculated')} content={exp.how} color="indigo" />
                            <Section icon="📈" title={t('how_to_read')} content={exp.read} color="amber" />
                            <Section icon="⚡" title={t('decisions')} content={exp.decisions} color="rose" />
                            <div className="mt-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 flex items-center justify-between">
                                <span className="text-xs font-bold text-slate-500">{t('data_source')}</span>
                                <span className="text-xs font-black text-slate-700 dark:text-slate-200">{exp.source}</span>
                            </div>
