interface KpiExplanationModalProps {
    isOpen: boolean;
    onClose: () => void;
    label: string;
}

const KpiExplanationModal: React.FC<KpiExplanationModalProps> = ({ isOpen, onClose, label }) => {
    const { t, language } = useLanguage();

    if (!isOpen) return null;

    // Mapping label text to specific explanations
    const getExplanation = (lbl: string) => {
        const lowerLabel = lbl.toLowerCase();
        if (lowerLabel.includes('إجمالي النفايات') || lowerLabel.includes('total transported waste') || lowerLabel.includes('إجمالي الأطنان') || lowerLabel.includes('total tons')) {
            return t('exp_total_waste') as any;
        }
        if (lowerLabel.includes('تولد النفايات للفرد يومياً') || lowerLabel.includes('daily waste generation')) {
            if (lowerLabel.includes('nswms')) return t('exp_waste_nswms') as any;
            return t('exp_waste_capita') as any;
        }
        if (lowerLabel.includes('كلفة الطن') || lowerLabel.includes('cost per ton')) {
            return t('exp_cost_ton') as any;
        }
        if (lowerLabel.includes('استرداد') || lowerLabel.includes('recovery')) {
            return t('exp_cost_recovery') as any;
        }
        // Add more mappings as needed
        return null;
    };

    const exp = getExplanation(label);
    const isRtl = language === 'ar';

    return (
        <div 
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300"
            onClick={onClose}
