                    <button 
                        onClick={onClose}
                        className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-500"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>

                {/* Content */}
                <div className={`p-8 space-y-6 ${isRtl ? 'text-right' : 'text-left'}`}>
                    {exp ? (
                        <>
                            <div className="space-y-2">
                                <h4 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest">{t('kpi_exp_represents')}</h4>
                                <p className="text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{exp.rep}</p>
                            </div>
                            <div className="space-y-2">
                                <h4 className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{t('kpi_exp_based_on')}</h4>
                                <p className="text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{exp.basis}</p>
                            </div>
                            <div className="space-y-2">
                                <h4 className="text-sm font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest">{t('kpi_exp_understanding')}</h4>
                                <p className="text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{exp.und}</p>
                            </div>
                        </>
