import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

interface KpiExplanationModalProps {
    isOpen: boolean;
    onClose: () => void;
    label: string;
}

const KpiExplanationModal: React.FC<KpiExplanationModalProps> = ({ isOpen, onClose, label }) => {
    const { t, language } = useLanguage();

    if (!isOpen) return null;

    // Robust matching logic for all indicators in Summary and Grid
    const getExplanation = (lbl: string) => {
        const lowerLabel = lbl.toLowerCase();

        // 1. Waste Quantities
        if (lowerLabel.includes('إجمالي النفايات') || lowerLabel.includes('total transported waste') || lowerLabel.includes('إجمالي الأطنان') || lowerLabel.includes('total tons')) {
            return t('exp_total_waste') as any;
        }
        if (lowerLabel.includes('معدل الإنتاج اليومي') || lowerLabel.includes('daily waste (t/d)') || lowerLabel.includes('أطنان / يوم')) {
            return t('exp_daily_waste_rate') as any;
        }
        if (lowerLabel.includes('إجمالي الرحلات') || lowerLabel.includes('total trips')) {
            return t('exp_total_trips') as any;
        }

        // 2. Per Capita Generation
        if (lowerLabel.includes('تولد النفايات للفرد يومياً') || lowerLabel.includes('daily waste generation') || lowerLabel.includes('نصيب الفرد') || lowerLabel.includes('waste/capita') || lowerLabel.includes('إنتاج الفرد')) {
            if (lowerLabel.includes('nswms')) return t('exp_waste_nswms') as any;
            return t('exp_waste_capita') as any;
        }

        // 3. Costs
        if (lowerLabel.includes('كلفة الطن') || lowerLabel.includes('cost per ton')) {
            return t('exp_cost_ton') as any;
        }
        if (lowerLabel.includes('إجمالي كلفة') || lowerLabel.includes('total management cost') || lowerLabel.includes('إجمالي المصاريف') || lowerLabel.includes('total annual exp')) {
            return t('exp_total_cost') as any;
        }
        if (lowerLabel.includes('كلفة الفرد') || lowerLabel.includes('cost per capita')) {
            return t('exp_cost_capita') as any;
        }
        if (lowerLabel.includes('كلفة الرحلة') || lowerLabel.includes('cost per trip')) {
            return t('exp_cost_trip') as any;
        }
        if (lowerLabel.includes('كلفة الوقود') || lowerLabel.includes('fuel cost')) {
            return t('exp_fuel_cost') as any;
        }
        if (lowerLabel.includes('كلفة الصيانة') || lowerLabel.includes('maint. cost')) {
            return t('exp_maint_cost') as any;
        }
        if (lowerLabel.includes('إجمالي الرواتب') || lowerLabel.includes('total salaries')) {
            return t('exp_salaries_total') as any;
        }

        // 4. Financials & Recovery
        if (lowerLabel.includes('استرداد التكاليف') || lowerLabel.includes('recovery')) {
            return t('exp_cost_recovery') as any;
        }
        if (lowerLabel.includes('القدرة على التحمل') || lowerLabel.includes('affordability')) {
            return t('exp_affordability') as any;
        }
        if (lowerLabel.includes('إجمالي الإيرادات') || lowerLabel.includes('total revenue')) {
            return t('exp_total_revenue') as any;
        }
        if (lowerLabel.includes('رسوم المنازل') || lowerLabel.includes('household fees')) {
            return t('exp_revenue_hh') as any;
        }
        if (lowerLabel.includes('المحال التجارية') || lowerLabel.includes('commercial waste fees')) {
            return t('exp_revenue_comm') as any;
        }

        // 5. Coverage & Population
        if (lowerLabel.includes('إجمالي عدد السكان') || lowerLabel.includes('total population') || lowerLabel.includes('pop')) {
            return t('exp_total_pop') as any;
        }
        if (lowerLabel.includes('السكان المخدومون') || lowerLabel.includes('served pop')) {
            return t('exp_served_pop') as any;
        }
        if (lowerLabel.includes('تغطية') || lowerLabel.includes('coverage')) {
            return t('exp_coverage_rate') as any;
        }
        if (lowerLabel.includes('عامل وطن') || lowerLabel.includes('sanitation worker')) {
            return t('exp_pop_per_cleaner') as any;
        }

        // 6. Treatment & Recycling
        if (lowerLabel.includes('تدوير') || lowerLabel.includes('recycling rate')) {
            return t('exp_recycling_rate') as any;
        }
        if (lowerLabel.includes('تحويل') || lowerLabel.includes('diversion')) {
            return t('exp_diversion_rate') as any;
        }

        // 7. Fleet & Staff
        if (lowerLabel.includes('المركبات النشطة') || lowerLabel.includes('active vehicles')) {
            return t('exp_active_vehicles') as any;
        }
        if (lowerLabel.includes('أيام تشغيلية') || lowerLabel.includes('operating days')) {
            return t('exp_op_days') as any;
        }
        if (lowerLabel.includes('متوسط عدد الرحلات') || lowerLabel.includes('avg trips')) {
            return t('exp_avg_trips') as any;
        }
        if (lowerLabel.includes('حمولة الرحلة') || lowerLabel.includes('avg load')) {
            return t('exp_avg_load') as any;
        }
        if (lowerLabel.includes('عدد العاملين') || lowerLabel.includes('total staff')) {
            return t('exp_workers_count') as any;
        }
        if (lowerLabel.includes('متوسط سعة') || lowerLabel.includes('avg capacity')) {
            return t('exp_avg_capacity') as any;
        }

        return null;
    };

    const exp = getExplanation(label);
    const isRtl = language === 'ar';

    return (
        <div 
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300"
            onClick={onClose}
        >
            <div 
                className="bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 dark:border-slate-800 animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header with Visual Icon */}
                <div className="bg-slate-50 dark:bg-slate-800/80 p-8 flex justify-between items-center border-b border-slate-100 dark:border-slate-700 backdrop-blur-sm sticky top-0 z-10">
                    <div className="flex items-center gap-4">
