                            <span className="text-3xl">📊</span>
                        </div>
                        <div>
                            <h3 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight leading-none">{label}</h3>
                            <p className="text-slate-400 dark:text-slate-500 text-sm font-bold mt-1 uppercase tracking-[0.2em]">{t('kpi_exp_title')}</p>
                        </div>
                    </div>
                    <button 
                        onClick={onClose}
                        className="p-3 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-all text-slate-500 group active:scale-90"
                    >
                        <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>

                {/* Content Area with Split Cards */}
                <div className={`p-8 space-y-8 overflow-y-auto ${isRtl ? 'text-right' : 'text-left'} custom-scrollbar`}>
                    {exp ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* Represents Section - Full Width */}
                            <div className="col-span-1 md:col-span-2 bg-blue-50/40 dark:bg-blue-900/20 p-8 rounded-3xl border border-blue-100/50 dark:border-blue-900/30 transition-all hover:shadow-lg">
