import React, { useState, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Trip } from '../types';
import { MONTHS_ORDER } from '../constants';
import CollapsibleSection from './CollapsibleSection';
import { printChart } from '../services/printService';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

interface ChartSectionProps {
    data: Trip[];
    comparisonData: Trip[];
    isLoading: boolean;
    filters: { vehicles: Set<string>; months: Set<string> };
    selectedYear: string;
    comparisonYear: string;
    chartRef: React.RefObject<HTMLDivElement>;
}

const ChartSection: React.FC<ChartSectionProps> = ({ data, comparisonData, isLoading, filters, selectedYear, comparisonYear, chartRef }) => {
    const { t, language } = useLanguage();
    const { theme } = useTheme();
    const [groupBy, setGroupBy] = useState<'month' | 'day'>('month');
    const [metric, setMetric] = useState<'trips' | 'tons'>('trips');

    const isDark = theme === 'dark';
    const axisColor = isDark ? '#94a3b8' : '#64748b';
    const gridColor = isDark ? '#334155' : '#e2e8f0';

    const chartData = useMemo(() => {
        const process = (trips: Trip[]) => {
            const grouped: { [key: string]: number } = {};
            trips.forEach(trip => {
                let key: string | null = null;
                if (groupBy === 'month') {
                    key = (trip['الشهر'] || '').toLowerCase();
                } else {
                    const date = new Date(trip['تاريخ التوزين الثاني']);
                    if (!isNaN(date.getTime())) {
                        key = date.toISOString().split('T')[0].split('-').slice(1).join('-'); 
                    }
                }
                if (!key) return;
                if (!grouped[key]) grouped[key] = 0;
                grouped[key] += metric === 'trips' ? 1 : Math.round((Number(trip['صافي التحميل'] || 0) / 1000));
            });
            return grouped;
        };

        const currentMap = process(data);
        const comparisonMap = process(comparisonData);

        const allKeys = [...new Set([...Object.keys(currentMap), ...Object.keys(comparisonMap)])];

        const merged = allKeys.map(key => ({
            name: key,
            displayName: groupBy === 'month' ? t(key) : key,
            current: currentMap[key] || 0,
            comparison: comparisonMap[key] || 0,
        }));

        if (groupBy === 'month') {
            merged.sort((a, b) => MONTHS_ORDER.indexOf(a.name) - MONTHS_ORDER.indexOf(b.name));
        } else {
            merged.sort((a, b) => a.name.localeCompare(b.name));
        }

        return merged;
    }, [data, comparisonData, groupBy, metric, t]);

    const handlePrint = () => {
        const chartTitle = `${t('sec_time_series')} - ${metric === 'trips' ? t('chart_trips') : t('chart_tons')} (${groupBy === 'month' ? t('chart_monthly') : t('chart_daily')})`;
        printChart(chartRef, chartTitle, filters, t, language);
    };

    return (
        <CollapsibleSection title={t('sec_time_series')}>
            <div className="flex flex-wrap items-center gap-4 mb-4 text-sm">
                <div className="flex items-center gap-2">
                    <label className="font-semibold text-slate-700 dark:text-slate-300">{t('chart_grouping')}</label>
                    <select value={groupBy} onChange={e => setGroupBy(e.target.value as 'month' | 'day')}
                        className="p-2 border border-slate-300 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100">
                        <option value="month">{t('chart_monthly')}</option>
                        <option value="day">{t('chart_daily')}</option>
                    </select>
                </div>
                <div className="flex items-center gap-2">
                    <label className="font-semibold text-slate-700 dark:text-slate-300">{t('chart_value')}</label>
                    <select value={metric} onChange={e => setMetric(e.target.value as 'trips' | 'tons')}
                        className="p-2 border border-slate-300 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100">
                        <option value="trips">{t('chart_trips')}</option>
                        <option value="tons">{t('chart_tons')}</option>
                    </select>
                </div>
                <button onClick={handlePrint} className="px-4 py-2 bg-emerald-500 text-white rounded-lg font-bold shadow-md hover:bg-emerald-600 transition-all">
                    {t('print')}
                </button>
            </div>
            <div className="h-96 w-full relative" ref={chartRef}>
                 {isLoading && (
                    <div className="absolute inset-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg">
                        <div className="w-12 h-12 border-4 border-slate-200 dark:border-slate-700 border-t-blue-600 rounded-full animate-spin"></div>
                    </div>
                )}
                <ResponsiveContainer>
                    <LineChart data={chartData} margin={{ top: 10, right: 30, left: 20, bottom: 10 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke={gridColor} vertical={false} />
                        <XAxis dataKey="displayName" tick={{ fill: axisColor, fontSize: 12, fontWeight: 700 }} stroke={gridColor} />
                        <YAxis tick={{ fill: axisColor, fontSize: 12 }} stroke={gridColor} />
                        <Tooltip 
                            contentStyle={{ 
                                backgroundColor: isDark ? '#1e293b' : '#fff', 
                                borderColor: isDark ? '#334155' : '#e2e8f0', 
                                color: isDark ? '#f1f5f9' : '#1e293b',
                                borderRadius: '12px',
                                boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                                textAlign: language === 'ar' ? 'right' : 'left'
                            }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '20px', fontWeight: 700 }} />
                        <Line 
                            type="monotone" 
                            dataKey="current" 
                            name={`${selectedYear} (${metric === 'trips' ? t('th_trips') : t('th_tons')})`} 
                            stroke="#2563eb" 
                            strokeWidth={4} 
                            dot={{ r: 4 }}
                            activeDot={{ r: 8, strokeWidth: 0 }} 
                        />
                        {comparisonYear && (
                            <Line 
                                type="monotone" 
                                dataKey="comparison" 
                                name={`${comparisonYear} (${metric === 'trips' ? t('th_trips') : t('th_tons')})`} 
                                stroke="#94a3b8" 
                                strokeWidth={2} 
                                strokeDasharray="5 5"
                                dot={{ r: 3 }}
                            />
                        )}
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </CollapsibleSection>
    );
};

export default ChartSection;

import React, { useState, useMemo, useRef } from 'react';
import { VehicleTableData } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';

interface TableSectionProps {
    tableData: VehicleTableData[];
    filters: { vehicles: Set<string>; months: Set<string> };
    title?: string;
}

const TableSection: React.FC<TableSectionProps> = ({ tableData, filters, title }) => {
    const { t, language } = useLanguage();
    const [sortBy, setSortBy] = useState<keyof VehicleTableData>('tons');
    const tableContainerRef = useRef<HTMLDivElement>(null);

    const headers = [
        { key: 'veh', label: t('th_veh_no') }, 
        { key: 'area', label: t('th_area') },
        { key: 'drivers', label: t('th_driver') }, 
        { key: 'year', label: t('th_year') },
        { key: 'cap_m3', label: t('th_cap_m3') }, 
        { key: 'cap_ton', label: t('th_cap_ton') },
        { key: 'trips', label: t('th_trips') }, 
        { key: 'tons', label: t('th_tons') },
        { key: 'fuel', label: t('th_fuel') }, 
        { key: 'maint', label: t('th_maint') },
        { key: 'cost_trip', label: t('th_cost_trip') }, 
        { key: 'cost_ton', label: t('th_cost_ton') },
        { key: 'distance', label: t('th_distance') },
        { key: 'km_per_trip', label: t('th_km_trip') },
    ];

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const sortedData = useMemo(() => {
        const sorted = [...tableData];
        sorted.sort((a, b) => {
            const valA = a[sortBy];
            const valB = b[sortBy];
            if (typeof valA === 'string' && typeof valB === 'string') {
                return valA.localeCompare(valB, language);
            }
            if (typeof valA === 'number' && typeof valB === 'number') {
                return valB - valA;
            }
            return 0;
        });
        return sorted;
    }, [tableData, sortBy, language]);

    const totals = useMemo(() => {
        if (sortedData.length === 0) return null;
        const totalTrips = sortedData.reduce((s, r) => s + r.trips, 0);
        const totalTons = sortedData.reduce((s, r) => s + r.tons, 0);
        const totalFuel = sortedData.reduce((s, r) => s + r.fuel, 0);
        const totalMaint = sortedData.reduce((s, r) => s + r.maint, 0);
        const totalDistance = sortedData.reduce((s, r) => s + r.distance, 0);
        const totalCost = totalFuel + totalMaint;

        const avgCostTrip = totalTrips > 0 ? totalCost / totalTrips : 0;
        const avgCostTon = totalTons > 0 ? totalCost / totalTons : 0;
        const avgKmTrip = totalTrips > 0 ? totalDistance / totalTrips : 0;

        return { totalTrips, totalTons, totalFuel, totalMaint, totalDistance, avgCostTrip, avgCostTon, avgKmTrip };
    }, [sortedData]);

    const handlePrint = () => {
        printTable(tableContainerRef, title || t('sec_veh_eff'), filters, t, language);
    };

    if (tableData.length === 0) return null;

    return (
        <CollapsibleSection title={title || t('sec_veh_eff')}>
             <div className="flex items-center gap-4 mb-4 text-sm">
                <div className="flex items-center gap-2">
                    <label className="font-semibold text-slate-700 dark:text-slate-300">{t('chart_grouping')}</label>
                    <select value={sortBy} onChange={e => setSortBy(e.target.value as keyof VehicleTableData)}
                        className="p-2 border border-slate-300 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100">
                        {headers.map(h => <option key={h.key} value={h.key}>{h.label}</option>)}
                    </select>
                </div>
                <button onClick={handlePrint} className="px-4 py-2 bg-emerald-500 text-white rounded-lg font-bold shadow-md hover:bg-emerald-600 transition-all">
                    {t('print')}
                </button>
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm" ref={tableContainerRef}>
                <table className="w-full text-sm text-center border-collapse bg-white dark:bg-slate-900">
                    <thead className="bg-slate-50 dark:bg-slate-800">
                        <tr>
                            {headers.map(h => <th key={h.key} className="p-4 border-b border-slate-200 dark:border-slate-700 font-black text-[11px] text-slate-500 dark:text-slate-400 uppercase tracking-widest">{h.label}</th>)}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                        {sortedData.map(row => (
                            <tr key={row.veh} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td className="p-4 font-bold text-slate-800 dark:text-slate-200">{row.veh}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300 font-bold">{areaMapping[row.area] || row.area}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{row.drivers}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{row.year}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.cap_m3, 1)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.cap_ton, 1)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.trips)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.tons, 1)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300 font-bold">{formatNumber(row.fuel)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.maint)}</td>
                                <td className="p-4 font-black text-blue-600 dark:text-blue-400">{formatNumber(row.cost_trip, 1)}</td>
                                <td className="p-4 font-black text-indigo-600 dark:text-indigo-400">{formatNumber(row.cost_ton, 1)}</td>
                                <td className="p-4 text-slate-700 dark:text-slate-300">{formatNumber(row.distance, 1)}</td>
                                <td className="p-4 font-black text-emerald-600 dark:text-emerald-400">{formatNumber(row.km_per_trip, 1)}</td>
                            </tr>
                        ))}
                        {totals && (
                            <tr className="font-black bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border-t-2 border-slate-200 dark:border-slate-700">
                                <td className="p-4">{t('total_avg')}</td>
                                <td colSpan={5} className="p-4"></td>
                                <td className="p-4">{formatNumber(totals.totalTrips)}</td>
                                <td className="p-4">{formatNumber(totals.totalTons, 1)}</td>
                                <td className="p-4">{formatNumber(totals.totalFuel)}</td>
                                <td className="p-4">{formatNumber(totals.totalMaint)}</td>
                                <td className="p-4 text-blue-700 dark:text-blue-400">{formatNumber(totals.avgCostTrip, 1)}</td>
                                <td className="p-4 text-indigo-700 dark:text-indigo-400">{formatNumber(totals.avgCostTon, 1)}</td>
                                <td className="p-4">{formatNumber(totals.totalDistance, 1)}</td>
                                <td className="p-4 text-emerald-700 dark:text-emerald-400">{formatNumber(totals.avgKmTrip, 1)}</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </CollapsibleSection>
    );
};

