{
  "name": "Waste Management AI Dashboard",
  "description": "An intelligent dashboard for analyzing waste management fleet data for the Mu'tah and Al-Mazar Municipality, featuring AI-powered reports and recommendations using the Gemini API.",
  "requestFramePermissions": [
    "geolocation"
