                        height="100%"
                        frameBorder="0"
                        style={{ border: 0 }}
                        src="https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d13636.56561571447!2d35.6961111!3d31.1444444!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e0!3m2!1sen!2sjo!4v1710000000000!5m2!1sen!2sjo"
                        allowFullScreen
                    ></iframe>

                    <div className={`absolute top-6 ${isRtl ? 'right-6' : 'left-6'} bg-white/90 dark:bg-slate-900/90 backdrop-blur-md p-4 rounded-2xl shadow-lg border border-slate-100 dark:border-slate-800 z-10 max-w-xs`}>
                        <div className="flex items-center gap-2 mb-2">
                            <span className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></span>
                            <span className="text-xs font-black text-slate-800 dark:text-slate-100">{t('map_landfill')}</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="w-3 h-3 bg-blue-500 rounded-full"></span>
                            <span className="text-xs font-black text-slate-800 dark:text-slate-100">{t('map_vehicle_pos')}</span>
                        </div>
                        <p className="mt-3 text-[10px] text-slate-500 font-bold leading-tight">{t('grounding_info')}</p>
                    </div>
                </div>

                {/* Vehicle Specific Routes & Distance */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {vehicleData.map((veh, idx) => (
                        <div 
                            key={veh.veh} 
                            className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 hover:shadow-xl transition-all group"
                        >
                            <div className="flex justify-between items-start mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-12 h-12 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-xl shadow-inner">
                                        🚛
                                    </div>
                                    <div>
