                                </div>
                                <div className="text-right">
                                    <div className="text-xs font-black text-slate-400 uppercase">{t('th_distance')}</div>
                                    <div className="text-lg font-black text-slate-800 dark:text-slate-100">{veh.distance} <span className="text-[10px] text-slate-500">كم</span></div>
