export async function fetchRoutePlanningInfo(startLocation: string): Promise<{ distance: string, mapLink: string }> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const targetLandfill = "مكب نفايات اللجون";

    const prompt = `Find the optimal driving route distance in kilometers from "${startLocation}" to "${targetLandfill}" in Jordan. Provide only the distance (number only) and a link to the route on Google Maps. Format: { "distance": "XX.X", "link": "url" }`;

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
            tools: [{ googleMaps: {} }],
        }
    });

    const text = response.text || '';
    // Basic extraction logic if model returns text. GroundingChunks are also available.
    const distanceMatch = text.match(/(\d+(\.\d+)?)/);
    const linkMatch = text.match(/(https:\/\/www\.google\.com\/maps\/[^\s]+)/);

    const grounding = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const mapUri = grounding?.find(c => c.maps?.uri)?.maps?.uri || linkMatch?.[1] || `https://www.google.com/maps/dir/${encodeURIComponent(startLocation)}/${encodeURIComponent(targetLandfill)}`;

    return {
        distance: distanceMatch?.[1] || "—",
        mapLink: mapUri
    };
}

