import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Trip, Vehicle, Fuel, Maintenance, Area, VehicleTableData, DriverStatsData, Population, AreaPopulationStats, Worker, Revenue, WasteTreatment, Distance, AdditionalCost } from './types';
import { CONFIG, MONTHS_ORDER } from './constants';
import { loadAllData } from './services/dataService';
import { generateFleetReport } from './services/geminiService';
import Header from './components/Header';
import KpiGrid from './components/KpiGrid';
import ChartSection from './components/ChartSection';
import TableSection from './components/TableSection';
import AiAnalysisSection from './components/AiAnalysisSection';
import UtilizationSection from './components/UtilizationSection';
import Loader from './components/Loader';
import AreaIntelligenceSection from './components/AreaIntelligenceSection';
import DriverStatsSection from './components/DriverStatsSection';
import PopulationAnalysisSection from './components/PopulationAnalysisSection';
import SalaryAnalysisSection from './components/SalaryAnalysisSection';
import FinancialManagementSection from './components/FinancialManagementSection';
import AnnualSummarySection from './components/AnnualSummarySection';
import RoutePlanningSection from './components/RoutePlanningSection';
import AiChat from './components/AiChat';
import Sidebar from './components/Sidebar';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';
import { ThemeProvider } from './contexts/ThemeContext';

const AppContent: React.FC = () => {
    const { language, t } = useLanguage();
    const [loading, setStatusLoading] = useState(true);
    const [tripsData, setTripsData] = useState<Trip[]>([]);
    const [vehiclesData, setVehiclesData] = useState<Vehicle[]>([]);
    const [fuelData, setFuelData] = useState<Fuel[]>([]);
    const [maintData, setMaintData] = useState<Maintenance[]>([]);
    const [areasData, setAreasData] = useState<Area[]>([]);
    const [populationData, setPopulationData] = useState<Population[]>([]);
    const [workersData, setWorkersData] = useState<Worker[]>([]);
    const [revenuesData, setRevenuesData] = useState<Revenue[]>([]);
    const [treatmentData, setTreatmentData] = useState<WasteTreatment[]>([]);
    const [distanceData, setDistanceData] = useState<Distance[]>([]);
    const [additionalCosts, setAdditionalCosts] = useState<AdditionalCost[]>([]);

    const [selectedYear, setSelectedYear] = useState<string>('');
    const [comparisonYear, setComparisonYear] = useState<string>('');
    const [activeTab, setActiveTab] = useState<string>('summary');
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    const [filters, setFilters] = useState<{ vehicles: Set<string>; months: Set<string> }>({
        vehicles: new Set(),
        months: new Set(),
    });
    const [isFiltering, setIsFiltering] = useState(false);

    const [aiReport, setAiReport] = useState<string>('');
    const [aiLoading, setAiLoading] = useState<boolean>(false);
    const [aiError, setAiError] = useState<string>('');

    const lineChartRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchData = async () => {
            setStatusLoading(true);
            try {
                const data = await loadAllData();
                setTripsData(data.trips);
                setVehiclesData(data.vehicles);
                setFuelData(data.fuel);
                setMaintData(data.maint);
                setAreasData(data.areas);
                setPopulationData(data.population || []);
                setWorkersData(data.workers || []);
                setRevenuesData(data.revenues || []);
                setTreatmentData(data.treatment || []);
                setDistanceData(data.distance || []);
                setAdditionalCosts(data.additionalCosts || []);

                const years = [...new Set(data.trips.map(t => t['السنة']).filter(Boolean))].sort().reverse();
                if (years.length > 0) {
                    setSelectedYear(years[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
            } finally {
                setStatusLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleYearChange = (year: string) => {
        setIsFiltering(true);
        setSelectedYear(year);
    };

    const handleComparisonYearChange = (year: string) => {
        setIsFiltering(true);
        setComparisonYear(year);
    };

    const handleFilterToggle = useCallback((type: 'vehicles' | 'months', value: string) => {
        setIsFiltering(true);
        setFilters(prev => {
            const newSet = new Set(prev[type]);
            if (newSet.has(value)) {
                newSet.delete(value);
            } else {
                newSet.add(value);
            }
            return { ...prev, [type]: newSet };
        });
    }, []);

    const resetFilters = useCallback(() => {
        setIsFiltering(true);
        setFilters({ vehicles: new Set(), months: new Set() });
        setComparisonYear('');
    }, []);

    const filteredTrips = useMemo(() => {
        let data = tripsData.filter(r => r['السنة'] === selectedYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, selectedYear, filters]);

    const comparisonTrips = useMemo(() => {
        if (!comparisonYear) return [];
        let data = tripsData.filter(r => r['السنة'] === comparisonYear);
        if (filters.vehicles.size > 0) {
            data = data.filter(r => r['رقم المركبة'] && filters.vehicles.has(r['رقم المركبة']));
        }
        if (filters.months.size > 0) {
            data = data.filter(r => r['الشهر'] && filters.months.has(r['الشهر'].toLowerCase()));
        }
        return data;
    }, [tripsData, comparisonYear, filters]);

    useEffect(() => {
        if (isFiltering) {
            const timer = setTimeout(() => setIsFiltering(false), 300);
            return () => clearTimeout(timer);
        }
    }, [filteredTrips, isFiltering]);

    const allVehiclesList = useMemo(() => {
        return [...new Set(tripsData.map(r => r['رقم المركبة']).filter(Boolean))].sort();
    }, [tripsData]);

    const getVehicleTableData = (trips: Trip[], year: string) => {
        const vehGroups: { [key: string]: { trips: number; tons: number; drivers: Set<string> } } = {};

        trips.forEach(r => {
            const v = r['رقم المركبة'];
            if (!v) return;
            if (!vehGroups[v]) vehGroups[v] = { trips: 0, tons: 0, drivers: new Set() };
            vehGroups[v].trips += 1;
            vehGroups[v].tons += (Number(r['صافي التحميل']) || 0) / 1000;
            if (r['السائق']) vehGroups[v].drivers.add(r['السائق']);
        });

        return Object.keys(vehGroups).map(v => {
            const { trips, tons, drivers } = vehGroups[v];
            const vehRow = vehiclesData.find(x => x['رقم المركبة'] === v) || {};
            const areaRow = areasData.find(x => x['رقم المركبة'] === v && (x['السنة'] === year || !x['السنة'])) || {};
            const fuelRow = fuelData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const maintRow = maintData.find(x => x['رقم المركبة'] === v && x['السنة'] === year) || {};
            const distRow = distanceData.find(x => x['رقم المركبة'] === v && x['السنة'] === year);

            let fuel = 0;
            if(fuelRow) {
                const monthsToSum = filters.months.size > 0 ? Array.from(filters.months) : MONTHS_ORDER;
                monthsToSum.forEach(m => {
                    fuel += (Number(fuelRow[m as keyof Fuel]) || 0);
                });
            }

            const maint = Number(maintRow?.['كلفة الصيانة'] || 0);
            const cap_m3 = parseFloat(vehRow['سعة المركبة بالمتر المكعب'] || '0');
            const density = parseFloat(vehRow['كثافة التحميل'] || '0');
            const cap_ton = cap_m3 * density;
            const mfgYear = parseInt(vehRow['سنة التصنيع'] || year);
            const age = parseInt(year) - mfgYear;
            let efficiencyRate = age < 7 ? 1.0 : (age <= 11 ? 0.5 : 0.0);
            const actual_daily_cap = cap_m3 * 1 * 0.625 * 0.9 * 0.86 * efficiencyRate;
            const totalCost = fuel + maint;
            const cost_trip = trips ? totalCost / trips : 0;
            const cost_ton = tons ? totalCost / tons : 0;
            const distance = distRow ? (Number(distRow['المسافة المقطوعة (كم)']) || 0) : 0;
            const km_per_trip = trips ? distance / trips : 0;

            return {
                veh: v, area: areaRow['المنطقة'] || '', drivers: [...drivers].join(', '), year: vehRow['سنة التصنيع'] || '',
                cap_m3, cap_ton, actual_daily_cap, trips, tons, fuel, maint, cost_trip, cost_ton, distance, km_per_trip
            };
        });
    };

    const filteredVehicleTableData = useMemo<VehicleTableData[]>(() => 
        getVehicleTableData(filteredTrips, selectedYear), 
    [filteredTrips, vehiclesData, areasData, fuelData, maintData, filters.months, selectedYear, distanceData]);

    const comparisonVehicleTableData = useMemo<VehicleTableData[]>(() => 
        comparisonYear ? getVehicleTableData(comparisonTrips, comparisonYear) : [], 
    [comparisonTrips, vehiclesData, areasData, fuelData, maintData, filters.months, comparisonYear, distanceData]);

    const currentAdditionalCosts = useMemo(() => {
        return additionalCosts.find(c => c.year === selectedYear) || null;
    }, [additionalCosts, selectedYear]);

    const currentRevenueDetail = useMemo(() => {
        const yearData = revenuesData.filter(r => r.year === selectedYear);
        const hh = yearData.reduce((sum, r) => sum + r.hhFees, 0);
        const commercial = yearData.reduce((sum, r) => sum + r.commercialFees, 0);
        const recycling = yearData.reduce((sum, r) => sum + r.recyclingRevenue, 0);
        return { total: hh + commercial + recycling, hh, commercial, recycling };
    }, [revenuesData, selectedYear]);

    const comparisonRevenueDetail = useMemo(() => {
        if (!comparisonYear) return null;
        const yearData = revenuesData.filter(r => r.year === comparisonYear);
        const hh = yearData.reduce((sum, r) => sum + r.hhFees, 0);
        const commercial = yearData.reduce((sum, r) => sum + r.commercialFees, 0);
        const recycling = yearData.reduce((sum, r) => sum + r.recyclingRevenue, 0);
        return { total: hh + commercial + recycling, hh, commercial, recycling };
    }, [revenuesData, comparisonYear]);

    const areaPopulationStats = useMemo<AreaPopulationStats[]>(() => {
        const vehAreaMap = new Map<string, string>();
        areasData.forEach(a => {
            if (a['رقم المركبة'] && a['المنطقة'] && (a['السنة'] === selectedYear || !a['السنة'])) {
                vehAreaMap.set(a['رقم المركبة'].trim(), a['المنطقة'].trim());
            }
        });
        const tonsByArea: { [key: string]: number } = {};
        filteredTrips.forEach(trip => {
            const vehicleId = (trip['رقم المركبة'] || '').trim();
            const area = vehAreaMap.get(vehicleId) || 'غير محدد';
            tonsByArea[area] = (tonsByArea[area] || 0) + (Number(trip['صافي التحميل'] || 0) / 1000);
        });
        const popDataForYear = populationData.filter(p => p.year === selectedYear);
        return popDataForYear.map(pop => {
            const areaName = pop.area.trim();
            const tons = tonsByArea[areaName] || 0;
            const population = pop.population || 0;
            const served = pop.served || 0;
            return {
                area: areaName, population, served, totalTons: tons,
                kgPerCapita: population > 0 ? (tons * 1000) / population : 0,
                coverageRate: population > 0 ? (served / population) * 100 : 0
            };
        }).sort((a, b) => b.kgPerCapita - a.kgPerCapita);
    }, [filteredTrips, areasData, populationData, selectedYear]);

    const populationTotals = useMemo(() => {
        let targetData = areaPopulationStats;
        if (filters.vehicles.size > 0) {
            const activeAreas = new Set(filteredVehicleTableData.map(v => v.area));
            targetData = areaPopulationStats.filter(p => activeAreas.has(p.area));
        }
        const totalPop = targetData.reduce((sum, item) => sum + item.population, 0);
        const totalServed = targetData.reduce((sum, item) => sum + item.served, 0);
        return { totalPop, totalServed, coverageRate: totalPop > 0 ? (totalServed / totalPop) * 100 : 0 };
    }, [areaPopulationStats, filters.vehicles, filteredVehicleTableData]);

    const handleGenerateReport = async (analysisType: string, options: any) => {
        setAiLoading(true);
        setAiError('');
        try {
            const report = await generateFleetReport(filteredVehicleTableData, analysisType, options, language);
            setAiReport(report);
        } catch (err: any) {
            setAiError(err.message || 'Error generating report');
        } finally {
            setAiLoading(false);
        }
    };

    return (
        <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 flex ${language === 'ar' ? 'flex-row-reverse' : 'flex-row'}`}>
            <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
            <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? (language === 'ar' ? 'mr-72' : 'ml-72') : (language === 'ar' ? 'mr-20' : 'ml-20')}`}>
                <Header 
                    tripsData={tripsData} filters={filters} selectedYear={selectedYear} 
                    comparisonYear={comparisonYear} activeTab={activeTab} onYearChange={handleYearChange} 
                    onComparisonYearChange={handleComparisonYearChange} onFilterToggle={handleFilterToggle} onResetFilters={resetFilters} 
                />

                {loading || isFiltering ? <Loader /> : (
                    <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-8">
                        {activeTab === 'summary' && (
                            <AnnualSummarySection 
                                filteredTrips={filteredTrips} 
                                treatment={treatmentData.find(t => t.year === selectedYear)} 
                                populationData={populationData} workers={workersData} 
                                revenues={revenuesData} vehicleTableData={filteredVehicleTableData} 
                                selectedYear={selectedYear} filters={filters} 
                                additionalCosts={currentAdditionalCosts}
                            />
                        )}
                        {activeTab === 'kpi' && (
                            <KpiGrid 
                                filteredTrips={filteredTrips} comparisonTrips={comparisonTrips} 
                                fuelData={fuelData} maintData={maintData} filters={filters} 
                                selectedYear={selectedYear} comparisonYear={comparisonYear} 
                                vehicleTableData={filteredVehicleTableData} comparisonVehicleTableData={comparisonVehicleTableData}
                                totalPopulation={populationTotals.totalPop}
                                totalServed={populationTotals.totalServed}
                                coverageRate={populationTotals.coverageRate}
                                workers={workersData}
                                revenueDetail={currentRevenueDetail}
                                comparisonRevenueDetail={comparisonRevenueDetail}
                                additionalCosts={currentAdditionalCosts}
                                comparisonAdditionalCosts={additionalCosts.find(c => c.year === comparisonYear) || null}
                            />
                        )}
                        {activeTab === 'charts' && (
                            <ChartSection data={filteredTrips} comparisonData={comparisonTrips} isLoading={false} filters={filters} selectedYear={selectedYear} comparisonYear={comparisonYear} chartRef={lineChartRef} />
                        )}
                        {activeTab === 'ai' && (
                            <AiAnalysisSection 
                                vehicles={allVehiclesList} onGenerateReport={handleGenerateReport} 
                                report={aiReport} isLoading={aiLoading} error={aiError} filters={filters} 
                            />
                        )}
                        {activeTab === 'vehicles' && (
                            <TableSection tableData={filteredVehicleTableData} filters={filters} />
                        )}
                        {activeTab === 'utilization' && (
                            <UtilizationSection tableData={filteredVehicleTableData} filters={filters} />
                        )}
                        {activeTab === 'salaries' && (
                            <SalaryAnalysisSection workers={workersData} filters={filters} />
                        )}
                        {activeTab === 'financial' && (
                            <FinancialManagementSection 
                                workers={workersData} 
                                vehicleData={filteredVehicleTableData} 
                                additionalCosts={additionalCosts} 
                                revenues={revenuesData}
                                selectedYear={selectedYear} 
                                comparisonYear={comparisonYear}
                                filters={filters} 
                            />
                        )}
                        {activeTab === 'intelligence' && (
                            <AreaIntelligenceSection workers={workersData} vehicleData={filteredVehicleTableData} population={populationData.filter(p => p.year === selectedYear)} selectedYear={selectedYear} filters={filters} />
                        )}
                        {activeTab === 'route_planning' && (
                            <RoutePlanningSection vehicles={filteredVehicleTableData} />
                        )}
                        {activeTab === 'population' && (
                            <PopulationAnalysisSection tableData={areaPopulationStats} filters={filters} />
                        )}
                    </div>
                )}
                <AiChat currentData={filteredVehicleTableData} comparisonData={comparisonVehicleTableData} selectedYear={selectedYear} comparisonYear={comparisonYear} />
            </main>
        </div>
    );
};

const App: React.FC = () => (
    <ThemeProvider>
        <LanguageProvider>
            <AppContent />
        </LanguageProvider>
    </ThemeProvider>
);

export default App;

import React, { useMemo, useRef, useState } from 'react';
import { Worker, VehicleTableData, AdditionalCost, Revenue } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import { exportToExcel, exportToImage, extractTableData } from '../services/exportService';
import ExportDropdown from './ExportDropdown';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
    PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend,
    BarChart, Bar, XAxis, YAxis, CartesianGrid
} from 'recharts';

interface FinancialManagementSectionProps {
    workers: Worker[];
    vehicleData: VehicleTableData[];
    additionalCosts: AdditionalCost[];
    revenues: Revenue[];
    selectedYear: string;
    comparisonYear: string;
    filters: { vehicles: Set<string>; months: Set<string> };
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6', '#4f46e5', '#ec4899', '#06b6d4'];
const REV_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

const FinancialManagementSection: React.FC<FinancialManagementSectionProps> = ({ 
    workers, vehicleData, additionalCosts, revenues, selectedYear, comparisonYear, filters 
}) => {
    const { t, language } = useLanguage();
    const { theme } = useTheme();
    const isDark = theme === 'dark';
    const axisColor = isDark ? '#94a3b8' : '#64748b';
    const gridColor = isDark ? '#334155' : '#e2e8f0';

    const tableContainerRef = useRef<HTMLDivElement>(null);
    const [viewMode, setViewMode] = useState<'expenses' | 'revenues' | 'comparison'>('comparison');

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const currentYearExtras = useMemo(() => {
        return additionalCosts.find(c => c.year === selectedYear) || { insurance: 0, clothing: 0, cleaning: 0, containers: 0, year: selectedYear };
    }, [additionalCosts, selectedYear]);

    const financialStats = useMemo(() => {
        const monthsCount = filters.months.size > 0 ? filters.months.size : 12;

        // Expenses Calculation
        const totalSalaries = workers.reduce((sum, w) => sum + (w.salary / 12) * monthsCount, 0);
        const totalFuel = vehicleData.reduce((sum, v) => sum + v.fuel, 0);
        const totalMaint = vehicleData.reduce((sum, v) => sum + v.maint, 0);
        const totalTons = vehicleData.reduce((sum, v) => sum + v.tons, 0);
        const extrasTotal = currentYearExtras.insurance + currentYearExtras.clothing + currentYearExtras.cleaning + currentYearExtras.containers;
        const grandTotalExpenses = totalSalaries + totalFuel + totalMaint + extrasTotal;

        // Revenue Calculation
        const currentYearRevenues = revenues.filter(r => r.year === selectedYear);
        const hhFees = currentYearRevenues.reduce((s, r) => s + r.hhFees, 0);
        const commercialFees = currentYearRevenues.reduce((s, r) => s + r.commercialFees, 0);
        const recyclingRevenue = currentYearRevenues.reduce((s, r) => s + r.recyclingRevenue, 0);
        const totalRevenue = hhFees + commercialFees + recyclingRevenue;

        const costRecovery = grandTotalExpenses > 0 ? (totalRevenue / grandTotalExpenses) * 100 : 0;
        const costPerTon = totalTons > 0 ? grandTotalExpenses / totalTons : 0;

        // Comparisons
        const compYearRevenues = revenues.filter(r => r.year === comparisonYear);
        const totalCompRevenue = compYearRevenues.reduce((s, r) => s + (r.hhFees + r.commercialFees + r.recyclingRevenue), 0);

        // Chart Data
        const expenseAllocation = [
            { name: t('th_total_salaries'), value: totalSalaries },
            { name: t('kpi_fuel_cost'), value: totalFuel },
            { name: t('kpi_maint_cost'), value: totalMaint },
            { name: t('th_insurance'), value: currentYearExtras.insurance },
            { name: t('th_clothing'), value: currentYearExtras.clothing },
            { name: t('th_cleaning'), value: currentYearExtras.cleaning },
            { name: t('th_containers'), value: currentYearExtras.containers }
        ].filter(item => item.value > 0);

        const revenueAllocation = [
            { name: t('th_hh_fees'), value: hhFees },
            { name: t('th_commercial_fees'), value: commercialFees },
            { name: t('th_recycling_revenue'), value: recyclingRevenue }
        ].filter(item => item.value > 0);

        return {
            totalSalaries, totalFuel, totalMaint, extrasTotal, grandTotalExpenses,
            hhFees, commercialFees, recyclingRevenue, totalRevenue,
            costRecovery, costPerTon, totalCompRevenue,
            expenseAllocation, revenueAllocation
        };
    }, [workers, vehicleData, currentYearExtras, revenues, selectedYear, comparisonYear, t, filters.months]);

    const areaFinancials = useMemo(() => {
        const stats = new Map<string, { exp: number; rev: number; salaries: number; op: number; hh: number; comm: number; rec: number }>();

        // 1. Operational Expenses
        vehicleData.forEach(v => {
            const area = v.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };
            current.op += (v.fuel + v.maint);
            current.exp += (v.fuel + v.maint);
            stats.set(area, current);
        });

        // 2. Salaries
        const monthsCount = filters.months.size > 0 ? filters.months.size : 12;
        workers.forEach(w => {
            const area = w.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };
            const salary = (w.salary / 12) * monthsCount;
            current.salaries += salary;
            current.exp += salary;
            stats.set(area, current);
        });

        // 3. Revenues
        revenues.filter(r => r.year === selectedYear).forEach(r => {
            const area = r.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };
            current.hh += r.hhFees;
            current.comm += r.commercialFees;
            current.rec += r.recyclingRevenue;
            current.rev += (r.hhFees + r.commercialFees + r.recyclingRevenue);
            stats.set(area, current);
        });

        return Array.from(stats.entries()).map(([area, data]) => ({
            name: area,
            displayName: areaMapping[area] || area,
            ...data,
            balance: data.rev - data.exp,
            recovery: data.exp > 0 ? (data.rev / data.exp) * 100 : 0
        })).sort((a, b) => b.exp - a.exp);
    }, [workers, vehicleData, revenues, selectedYear, t, filters.months]);

    const formatCurrency = (val: number) => formatNumber(Math.round(val)) + ' ' + t('unit_jd');

    const handleExportExcel = () => {
        const rawData = extractTableData(tableContainerRef);
        exportToExcel(rawData, `Consolidated_Financial_Management`);
    };

    return (
        <CollapsibleSection title={t('sec_financial_mgmt')}>
            <div className="flex flex-wrap items-center justify-between gap-4 mb-8">
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-2xl">
                    <button 
                        onClick={() => setViewMode('comparison')}
                        className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${viewMode === 'comparison' ? 'bg-white dark:bg-slate-700 shadow-sm text-blue-600 dark:text-blue-400' : 'text-slate-500'}`}
                    >
                        المقارنة المالية
                    </button>
                    <button 
                        onClick={() => setViewMode('expenses')}
                        className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${viewMode === 'expenses' ? 'bg-white dark:bg-slate-700 shadow-sm text-red-600 dark:text-red-400' : 'text-slate-500'}`}
                    >
                        المصاريف
                    </button>
                    <button 
                        onClick={() => setViewMode('revenues')}
                        className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${viewMode === 'revenues' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600 dark:text-emerald-400' : 'text-slate-500'}`}
                    >
                        الإيرادات
                    </button>
                </div>
                <ExportDropdown 
                    onExportPdf={() => printTable(tableContainerRef, t('sec_financial_mgmt'), filters, t, language)}
                    onExportExcel={handleExportExcel}
                    onExportCsv={handleExportExcel}
                    onExportImage={() => exportToImage(tableContainerRef, `Financial_Consolidated_Export`)}
                />
            </div>

            {/* Combined KPI Row */}
            <div className="grid grid-cols-1 md:grid-cols-5 gap-4 mb-10">
                <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-[2.5rem] shadow-lg text-white">
                    <div className="text-slate-400 text-[10px] font-black mb-2 uppercase text-right">إجمالي المصاريف</div>
                    <div className="text-2xl font-black">{formatCurrency(financialStats.grandTotalExpenses)}</div>
                </div>
                <div className="bg-gradient-to-br from-blue-600 to-blue-800 p-6 rounded-[2.5rem] shadow-lg text-white">
                    <div className="text-blue-200 text-[10px] font-black mb-2 uppercase text-right">إجمالي الإيرادات</div>
                    <div className="text-2xl font-black">{formatCurrency(financialStats.totalRevenue)}</div>
                </div>
                <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-md border-b-8 border-indigo-500 transition-colors">
                    <div className="text-slate-400 dark:text-slate-500 text-[10px] font-black mb-2 uppercase text-right">نسبة الاسترداد</div>
                    <div className="text-3xl font-black text-indigo-600 dark:text-indigo-400">{formatNumber(financialStats.costRecovery, 1)}%</div>
                </div>
                <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-md border-b-8 border-red-500 transition-colors">
                    <div className="text-slate-400 dark:text-slate-500 text-[10px] font-black mb-2 uppercase text-right">تكلفة الطن</div>
                    <div className="text-2xl font-black text-red-600 dark:text-red-400">{formatNumber(financialStats.costPerTon, 1)} <span className="text-xs font-bold">{t('unit_jd')}</span></div>
                </div>
                <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-md border-b-8 border-emerald-500 transition-colors">
                    <div className="text-slate-400 dark:text-slate-500 text-[10px] font-black mb-2 uppercase text-right">صافي الربح/الخسارة</div>
                    <div className={`text-2xl font-black ${financialStats.totalRevenue - financialStats.grandTotalExpenses >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                        {formatCurrency(financialStats.totalRevenue - financialStats.grandTotalExpenses)}
                    </div>
                </div>
            </div>

            {/* Charts Row */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
                {/* Expense Allocation */}
                <div className="bg-white dark:bg-slate-800/50 p-8 rounded-[3rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                    <h4 className="text-sm font-black text-slate-700 dark:text-slate-300 mb-6 text-right">توزيع المصاريف التشغيلية ({selectedYear})</h4>
                    <div className="h-72 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={financialStats.expenseAllocation}
                                    cx="50%" cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={4}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {financialStats.expenseAllocation.map((entry, index) => (
                                        <Cell key={`exp-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: isDark ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', color: isDark ? '#fff' : '#000', textAlign: 'right' }}
                                    formatter={(val: number) => formatCurrency(val)} 
                                />
                                <Legend layout="vertical" align="right" verticalAlign="middle" wrapperStyle={{ color: axisColor, paddingLeft: '20px', fontSize: '11px', fontWeight: 700 }} />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Revenue Allocation */}
                <div className="bg-white dark:bg-slate-800/50 p-8 rounded-[3rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                    <h4 className="text-sm font-black text-slate-700 dark:text-slate-300 mb-6 text-right">مصادر الدخل والإيرادات ({selectedYear})</h4>
                    <div className="h-72 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={financialStats.revenueAllocation}
                                    cx="50%" cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={4}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {financialStats.revenueAllocation.map((entry, index) => (
                                        <Cell key={`rev-${index}`} fill={REV_COLORS[index % REV_COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: isDark ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', color: isDark ? '#fff' : '#000', textAlign: 'right' }}
                                    formatter={(val: number) => formatCurrency(val)} 
                                />
                                <Legend layout="vertical" align="right" verticalAlign="middle" wrapperStyle={{ color: axisColor, paddingLeft: '20px', fontSize: '11px', fontWeight: 700 }} />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>

            {/* Performance Comparison Chart (Expenses vs Revenues per Area) */}
            <div className="bg-white dark:bg-slate-800/50 p-8 rounded-[3rem] border border-slate-100 dark:border-slate-700 shadow-sm mb-10">
                <h4 className="text-sm font-black text-slate-700 dark:text-slate-300 mb-6 text-right">كفاءة استرداد التكاليف حسب المنطقة</h4>
                <div className="h-80 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={areaFinancials}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
                            <XAxis dataKey="displayName" tick={{fontSize: 10, fontWeight: 700, fill: axisColor}} axisLine={false} tickLine={false} />
                            <YAxis tick={{fontSize: 10, fill: axisColor}} axisLine={false} tickLine={false} />
                            <Tooltip 
                                cursor={{fill: isDark ? '#334155' : '#f8fafc'}}
                                contentStyle={{ backgroundColor: isDark ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', color: isDark ? '#fff' : '#000', textAlign: 'right' }}
                                formatter={(val: number) => formatCurrency(val)} 
                            />
                            <Legend wrapperStyle={{paddingTop: '20px'}} />
                            <Bar dataKey="exp" name="المصاريف" fill="#ef4444" radius={[6, 6, 0, 0]} barSize={25} />
                            <Bar dataKey="rev" name="الإيرادات" fill="#10b981" radius={[6, 6, 0, 0]} barSize={25} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            {/* Consolidated Financial Table */}
            <div className="overflow-x-auto rounded-[2.5rem] border border-slate-200 dark:border-slate-700 shadow-sm mb-10" ref={tableContainerRef}>
                <table className="w-full text-[11px] text-center border-collapse bg-white dark:bg-slate-900">
                    <thead className="bg-slate-50 dark:bg-slate-800">
                        <tr>
                            <th className="p-4 border-b border-slate-200 dark:border-slate-700 text-slate-500 font-black uppercase text-right pr-10">{t('th_area')}</th>
                            <th className="p-4 border-b border-slate-200 dark:border-slate-700 text-slate-500 font-black uppercase">المصاريف (رواتب+تشغيل)</th>
                            <th className="p-4 border-b border-slate-200 dark:border-slate-700 text-slate-500 font-black uppercase">الإيرادات المحصلة</th>
                            <th className="p-4 border-b border-slate-200 dark:border-slate-700 text-slate-500 font-black uppercase">الصافي المالي</th>
                            <th className="p-4 border-b border-slate-200 dark:border-slate-700 text-slate-500 font-black uppercase">نسبة التغطية الذاتية</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                        {areaFinancials.map((area, idx) => (
                            <tr key={idx} className="hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                                <td className="p-4 font-black text-slate-800 dark:text-slate-200 text-right pr-10">{area.displayName}</td>
                                <td className="p-4 text-red-600 dark:text-red-400 font-bold">{formatCurrency(area.exp)}</td>
                                <td className="p-4 text-emerald-600 dark:text-emerald-400 font-bold">{formatCurrency(area.rev)}</td>
                                <td className={`p-4 font-black ${area.balance >= 0 ? 'text-emerald-700 dark:text-emerald-400' : 'text-red-700 dark:text-red-400'}`}>
                                    {formatCurrency(area.balance)}
                                </td>
                                <td className="p-4">
                                    <div className="flex items-center justify-center gap-2">
                                        <div className="w-16 bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden">
                                            <div 
                                                className={`h-full ${area.recovery >= 100 ? 'bg-emerald-500' : area.recovery > 50 ? 'bg-amber-500' : 'bg-red-500'}`}
                                                style={{ width: `${Math.min(area.recovery, 100)}%` }}
                                            ></div>
                                        </div>
                                        <span className="font-black w-10">{formatNumber(area.recovery, 0)}%</span>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot className="bg-slate-50 dark:bg-slate-800 font-black text-slate-800 dark:text-slate-100 border-t-2 border-slate-200 dark:border-slate-700">
                        <tr>
                            <td className="p-4 text-right pr-10 uppercase">المجموع الكلي</td>
                            <td className="p-4 text-red-600">{formatCurrency(financialStats.grandTotalExpenses - financialStats.extrasTotal)}</td>
                            <td className="p-4 text-emerald-600">{formatCurrency(financialStats.totalRevenue)}</td>
                            <td className="p-4">{formatCurrency(financialStats.totalRevenue - (financialStats.grandTotalExpenses - financialStats.extrasTotal))}</td>
                            <td className="p-4 text-indigo-600">{formatNumber(financialStats.costRecovery, 1)}%</td>
                        </tr>
                    </tfoot>
                </table>
            </div>

            {/* Additional Costs Detailed Section */}
            <div className="bg-slate-900 dark:bg-slate-950 p-10 rounded-[3.5rem] text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-80 h-80 bg-blue-600/10 rounded-full blur-[100px] -mr-40 -mt-40"></div>
                <div className="relative z-10">
                    <div className="flex justify-between items-center mb-8">
                        <h4 className="text-xl font-black flex items-center gap-3">
                            <span className="bg-white/20 p-3 rounded-2xl">🧾</span>
                            التكاليف الإضافية السنوية
                        </h4>
                        <div className="px-6 py-2 bg-white/10 rounded-full text-xs font-black border border-white/20">
                            إجمالي: {formatCurrency(financialStats.extrasTotal)}
                        </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                        <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-colors">
                            <div className="text-blue-300 text-[10px] font-black uppercase mb-2 tracking-widest">{t('th_insurance')}</div>
                            <div className="text-3xl font-black">{formatCurrency(currentYearExtras.insurance)}</div>
                        </div>
                        <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-colors">
                            <div className="text-emerald-300 text-[10px] font-black uppercase mb-2 tracking-widest">{t('th_clothing')}</div>
                            <div className="text-3xl font-black">{formatCurrency(currentYearExtras.clothing)}</div>
                        </div>
                        <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-colors">
                            <div className="text-amber-300 text-[10px] font-black uppercase mb-2 tracking-widest">{t('th_cleaning')}</div>
                            <div className="text-3xl font-black">{formatCurrency(currentYearExtras.cleaning)}</div>
                        </div>
                        <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-colors">
                            <div className="text-pink-300 text-[10px] font-black uppercase mb-2 tracking-widest">{t('th_containers')}</div>
                            <div className="text-3xl font-black">{formatCurrency(currentYearExtras.containers)}</div>
                        </div>
                    </div>
                </div>
            </div>
        </CollapsibleSection>
    );
};

export default FinancialManagementSection;

import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

interface SidebarProps {
    activeTab: string;
    setActiveTab: (tab: string) => void;
    isOpen: boolean;
    setIsOpen: (isOpen: boolean) => void;
}

