        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const handleVehicleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedVehId(e.target.value);
        setIsCustomMode(false);
        setRouteData(null);
