import { GoogleGenAI } from "@google/genai";
import { VehicleTableData, RouteInfo, RouteOption } from "../types";

export async function getOptimalRoute(start: string, destination: string): Promise<RouteInfo> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Find the 3 best driving routes from "${start}" to "${destination}" in Jordan.
    For each route, provide:
    1. A descriptive name (e.g., "Main Highway", "Scenic Route", "Shortest Path").
    2. The distance in kilometers.
    3. The estimated travel time (duration).
    4. A direct Google Maps URL for that specific route if possible.

    Return the response ONLY as a JSON object in this format:
    {
      "routes": [
        {"name": "...", "distance": "XX.X km", "duration": "XX mins", "mapLink": "https://..."},
        ...
      ],
      "summary": "Brief overall advice on which route is best for waste management vehicles."
    }`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                tools: [{ googleMaps: {} }],
            }
        });

        const text = response.text || "{}";
        const jsonStr = text.substring(text.indexOf('{'), text.lastIndexOf('}') + 1);
        const data = JSON.parse(jsonStr);

        // Fallback for empty or invalid routes
        if (!data.routes || data.routes.length === 0) {
            return {
                routes: [{
                    name: "Default Route",
                    distance: "—",
                    duration: "—",
                    mapLink: `https://www.google.com/maps/dir/${encodeURIComponent(start)}/${encodeURIComponent(destination)}`
                }],
                summary: "Standard route via main roads."
            };
        }

        return data as RouteInfo;
    } catch (e) {
        console.error("Route calculation error:", e);
        return {
            routes: [{
                name: "Primary Route",
                distance: "—",
                duration: "—",
                mapLink: `https://www.google.com/maps/dir/${encodeURIComponent(start)}/${encodeURIComponent(destination)}`
            }],
            summary: "Error occurred while calculating alternative routes. Falling back to primary link."
        };
    }
}

export async function generateFleetReport(
    data: VehicleTableData[],
    analysisType: string,
    options: { vehicleId?: string; vehicleIds?: string[]; customPrompt?: string },
    language: string = 'ar'
): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-3-pro-preview';
    let userRequest = '';
    const isEn = language === 'en';

    switch (analysisType) {
        case 'general':
            userRequest = "Provide a general fleet-wide analysis, including the holistic ranking of all vehicles as specified in the critical instructions. Conclude with an overall assessment of the fleet's health and provide high-level strategic recommendations.";
            break;
        case 'holistic_ranking':
            userRequest = "Perform a holistic ranking of all vehicles from best to worst, as specified in the critical instructions. The ranking must be the primary focus of the report. Provide a detailed justification for each vehicle's position, explaining its strengths and weaknesses based on the provided data.";
            break;
        case 'municipality_reality':
            userRequest = `
            أنت نظام تحليل ذكي مدمج داخل لوحة تحكم لإدارة النفايات الصلبة في بلدية.
            لديك وصول مباشر إلى بيانات اللوحة للفترة الزمنية المختارة، وتشمل البيانات السكانية، التشغيلية، والمالية.

            المطلوب:
            أنشئ تقريرًا تحليليًا متكاملًا عن واقع البلدية اعتمادًا فقط على البيانات المتاحة في لوحة التحكم، دون افتراض أو معلومات خارجية.

            يجب أن يتضمن التقرير الأقسام التالية، مع تعبئتها تلقائيًا من البيانات:
            1. لمحة عامة عن البلدية والفترة الزمنية محل التحليل
            2. الخصائص السكانية المخدومة
            3. حجم النفايات المتولدة والمنقولة (إجمالي، متوسط يومي، اتجاه زمني)
            4. الأداء التشغيلي (عدد الرحلات، المركبات العاملة، كفاءة التشغيل)
            5. التحليل المالي (كلفة الوقود، كلفة الصيانة، كلفة الرحلة، كلفة الطن)
            6. قراءة تحليلية للعلاقة بين الكلفة والأداء
            7. أبرز نقاط القوة
            8. أبرز التحديات والملاحظات التشغيلية
            9. توصيات عملية مبنية على الأرقام

            أسلوب التقرير:
            - رسمي ومهني
            - لغة واضحة غير معقدة
            - يربط الأرقام بالتحليل (لا يكتفي بعرضها)
            - مناسب لعرضه على إدارة بلدية أو جهة رقابية أو مانح

            ملاحظات مهمة:
            - لا تذكر أسماء مؤشرات أو أعمدة تقنية
            - لا تستخدم عبارات عامة أو إنشائية
            - إذا كان هناك نقص بيانات، أشر إليه بوضوح
            - اعتمد على المقارنات الداخلية والاتجاهات الزمنية إن وجدت
            `;
            break;
        case 'detailed':
            userRequest = "Provide a detailed report for each vehicle individually. Analyze its performance, costs, and efficiency, and provide specific recommendations for each one.";
            break;
        case 'specific':
            if (!options.vehicleId) throw new Error('Vehicle ID is required for specific report.');
            userRequest = `Provide a detailed performance and cost analysis exclusively for vehicle number ${options.vehicleId}. Compare its performance to the fleet average if possible.`;
            break;
        case 'comparison':
            if (!options.vehicleIds || options.vehicleIds.length < 2) throw new Error('At least two Vehicle IDs are required for comparison.');
            userRequest = `Directly compare the performance, costs, and efficiency of the following vehicles: ${options.vehicleIds.join(', ')}. Highlight the key differences and declare a winner for different categories (e.g., most cost-effective, highest workload).`;
            break;
        case 'best_worst':
            userRequest = "Identify the top 3 best-performing and bottom 3 worst-performing vehicles. Base your evaluation on a combination of key metrics, primarily cost per ton and total tons collected. Justify your selections with data and provide clear reasons.";
            break;
        case 'custom':
            if (!options.customPrompt) throw new Error('A custom prompt is required.');
            userRequest = options.customPrompt;
            break;
        default:
            throw new Error('Invalid analysis type');
    }

    const fullPrompt = `
        You are an expert fleet management analyst. Your task is to analyze waste management vehicle data for the Mu'tah and Al-Mazar Municipality.

        **CRITICAL INSTRUCTIONS:**
        1.  All responses MUST be in ${isEn ? 'formal English' : 'formal Arabic'}.
        2.  All numbers in your response MUST be English numerals (e.g., 123, 45.6, 2024).
        3.  **Holistic Ranking:** When requested to perform a general analysis or ranking, you MUST rank all vehicles from best to worst. This ranking must be holistic, considering a combination of all provided variables, not just one. Key factors to weigh include cost-effectiveness (cost_ton, cost_trip), productivity (tons, trips), and manufacturing year (year). Present the ranking clearly (e.g., a numbered list) and provide a justification for each vehicle's position, explaining its strengths and weaknesses.
        4.  Provide specific, testable, and actionable recommendations.
        5.  The data provides total costs for the period.
        6.  Columns: veh (ID), area (zone), drivers, year (mfg), cap_m3, cap_ton (theoretical ton capacity), trips (total count), tons (total weight), fuel (total cost), maint (total cost), cost_trip (avg), cost_ton (avg).

        **VEHICLE DATA (in JSON format):**
        ${JSON.stringify(data, null, 2)}

        **USER REQUEST:**
        ${userRequest}
    `;

    const response = await ai.models.generateContent({
        model: model,
        contents: fullPrompt,
        config: {
            thinkingConfig: { thinkingBudget: 32768 }
        }
    });

    return response.text || '';
}

export async function* chatWithDataStream(
    query: string,
    currentData: VehicleTableData[],
    comparisonData: VehicleTableData[],
    years: { selected: string, comparison: string },
    language: string = 'ar'
) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const isEn = language === 'en';

    const systemInstruction = `
        You are an AI fleet management expert for the Mu'tah and Al-Mazar Municipality.
        Current Year: ${years.selected}
        Comparison Year: ${years.comparison || 'None'}

        CRITICAL:
        1. Respond strictly in ${isEn ? 'English' : 'Arabic'}.
        2. Use English numerals.
        3. Be concise and data-driven.

        Current Data:
        ${JSON.stringify(currentData)}

        Comparison Data:
        ${JSON.stringify(comparisonData)}
    `;

    const responseStream = await ai.models.generateContentStream({
        model: 'gemini-flash-lite-latest',
        contents: query,
        config: {
            systemInstruction: systemInstruction,
            temperature: 0.1, 
            thinkingConfig: { thinkingBudget: 0 }
        }
    });

    for await (const chunk of responseStream) {
        yield chunk.text || '';
    }
}

import React, { useMemo, useRef, useState } from 'react';
import { Worker, VehicleTableData, AdditionalCost, Revenue } from '../types';
import { formatNumber } from '../services/dataService';
import { printTable } from '../services/printService';
import { exportToExcel, exportToImage, extractTableData } from '../services/exportService';
import ExportDropdown from './ExportDropdown';
import CollapsibleSection from './CollapsibleSection';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
    PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend,
    BarChart, Bar, XAxis, YAxis, CartesianGrid, LabelList
} from 'recharts';

interface FinancialManagementSectionProps {
    workers: Worker[];
    vehicleData: VehicleTableData[];
    additionalCosts: AdditionalCost[];
    revenues: Revenue[];
    selectedYear: string;
    comparisonYear: string;
    filters: { vehicles: Set<string>; months: Set<string> };
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6', '#4f46e5', '#ec4899', '#06b6d4'];
const REV_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

const FinancialManagementSection: React.FC<FinancialManagementSectionProps> = ({ 
    workers, vehicleData, additionalCosts, revenues, selectedYear, comparisonYear, filters 
}) => {
    const { t, language } = useLanguage();
    const { theme } = useTheme();
    const isDark = theme === 'dark';
    const axisColor = isDark ? '#94a3b8' : '#64748b';
    const gridColor = isDark ? '#334155' : '#e2e8f0';

    const tableContainerRef = useRef<HTMLDivElement>(null);
    const [viewMode, setViewMode] = useState<'comparison' | 'expenses' | 'revenues'>('comparison');

    const areaMapping: {[key: string]: string} = {
        'الطيبة': t('area_taybeh'),
        'مؤته': t('area_mutah'),
        'مؤتة': t('area_mutah'),
        'المزار': t('area_mazar'),
        'العراق': t('area_iraq'),
        'الهاشمية': t('area_hashimiah'),
        'سول': t('area_sol'),
        'جعفر': t('area_jaffar'),
        'غير محدد': t('area_undefined')
    };

    const currentYearExtras = useMemo(() => {
        return additionalCosts.find(c => c.year === selectedYear) || { insurance: 0, clothing: 0, cleaning: 0, containers: 0, year: selectedYear };
    }, [additionalCosts, selectedYear]);

    const financialStats = useMemo(() => {
        // Calculate the time ratio. If specific months are selected, we prorate annual costs (Maint, Extras).
        // Fuel is already summed based on selected months in the parent component.
        // Salaries are calculated monthly below.
        const monthsCount = filters.months.size > 0 ? filters.months.size : 12;
        const timeRatio = monthsCount / 12; 

        // 1. Salaries: Monthly Salary * Number of Selected Months
        const totalSalaries = workers.reduce((sum, w) => sum + (w.salary / 12) * monthsCount, 0);

        // 2. Fuel: Already filtered by month in App.tsx before being passed here
        const totalFuel = vehicleData.reduce((sum, v) => sum + v.fuel, 0);

        // 3. Maintenance: Annual cost * Time Ratio
        const totalMaint = vehicleData.reduce((sum, v) => sum + v.maint, 0) * timeRatio;

        // 4. Non-Operational (Extras): Annual cost * Time Ratio
        const extrasRaw = {
            insurance: currentYearExtras.insurance * timeRatio,
            clothing: currentYearExtras.clothing * timeRatio,
            cleaning: currentYearExtras.cleaning * timeRatio,
            containers: currentYearExtras.containers * timeRatio
        };
        const extrasTotal = extrasRaw.insurance + extrasRaw.clothing + extrasRaw.cleaning + extrasRaw.containers;

        // 5. Grand Total Expenses
        const grandTotalExpenses = totalSalaries + totalFuel + totalMaint + extrasTotal;

        const totalTons = vehicleData.reduce((sum, v) => sum + v.tons, 0);

        // Revenue Calculations
        const currentYearRevenues = revenues.filter(r => r.year === selectedYear);
        // Note: Revenues usually come as annual totals in this dataset. We apply the same time ratio for fair comparison.
        const applyRatio = (val: number) => val * (filters.months.size > 0 ? 1 : 1); // Revenues might be realized annually, keep as is or prorate? 
        // Usually revenues like fees are annual. If comparing vs 1 month of expenses, we should arguably prorate revenue too.
        // For safety/standard display, we'll prorate revenue to match the expense window.

        const hhFees = currentYearRevenues.reduce((s, r) => s + r.hhFees, 0) * timeRatio;
        const commercialFees = currentYearRevenues.reduce((s, r) => s + r.commercialFees, 0) * timeRatio;
        const recyclingRevenue = currentYearRevenues.reduce((s, r) => s + r.recyclingRevenue, 0) * timeRatio;
        const totalRevenue = hhFees + commercialFees + recyclingRevenue;

        const costRecovery = grandTotalExpenses > 0 ? (totalRevenue / grandTotalExpenses) * 100 : 0;
        const costPerTon = totalTons > 0 ? grandTotalExpenses / totalTons : 0;

        const expenseAllocation = [
            { name: t('th_total_salaries'), value: totalSalaries },
            { name: t('kpi_fuel_cost'), value: totalFuel },
            { name: t('kpi_maint_cost'), value: totalMaint },
            { name: t('th_insurance'), value: extrasRaw.insurance },
            { name: t('th_clothing'), value: extrasRaw.clothing },
            { name: t('th_cleaning'), value: extrasRaw.cleaning },
            { name: t('th_containers'), value: extrasRaw.containers }
        ].filter(item => item.value > 0);

        const revenueAllocation = [
            { name: t('th_hh_fees'), value: hhFees },
            { name: t('th_commercial_fees'), value: commercialFees },
            { name: t('th_recycling_revenue'), value: recyclingRevenue }
        ].filter(item => item.value > 0);

        return {
            totalSalaries, totalFuel, totalMaint, extrasTotal, grandTotalExpenses,
            hhFees, commercialFees, recyclingRevenue, totalRevenue,
            costRecovery, costPerTon,
            expenseAllocation, revenueAllocation, totalTons,
            extrasRaw
        };
    }, [workers, vehicleData, currentYearExtras, revenues, selectedYear, comparisonYear, t, filters.months]);

    const areaFinancials = useMemo(() => {
        const stats = new Map<string, { exp: number; rev: number; salaries: number; op: number; hh: number; comm: number; rec: number }>();
        const monthsCount = filters.months.size > 0 ? filters.months.size : 12;
        const timeRatio = monthsCount / 12;

        // Distribute Operational Costs (Fuel + Maint)
        vehicleData.forEach(v => {
            const area = v.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };

            // Fuel is already sum of months. Maint is annual, so prorate it.
            const operationalCost = v.fuel + (v.maint * timeRatio);

            current.op += operationalCost;
            current.exp += operationalCost;
            stats.set(area, current);
        });

        // Distribute Salaries
        workers.forEach(w => {
            const area = w.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };
            const salary = (w.salary / 12) * monthsCount;
            current.salaries += salary;
            current.exp += salary;
            stats.set(area, current);
        });

        // Distribute Revenues (Prorated)
        revenues.filter(r => r.year === selectedYear).forEach(r => {
            const area = r.area || 'غير محدد';
            const current = stats.get(area) || { exp: 0, rev: 0, salaries: 0, op: 0, hh: 0, comm: 0, rec: 0 };

            const r_hh = r.hhFees * timeRatio;
            const r_comm = r.commercialFees * timeRatio;
            const r_rec = r.recyclingRevenue * timeRatio;

            current.hh += r_hh;
            current.comm += r_comm;
            current.rec += r_rec;
            current.rev += (r_hh + r_comm + r_rec);
            stats.set(area, current);
        });

        // NOTE: Additional Costs (Non-operational) are generally not distributed by Area in the source data.
        // The table totals will sum up to (Salaries + Fuel + Maint).
        // The "Grand Total" card includes Extras. This explains the difference if any.

        return Array.from(stats.entries()).map(([area, data]) => ({
            name: area,
            displayName: areaMapping[area] || area,
            ...data,
            balance: data.rev - data.exp,
            recovery: data.exp > 0 ? (data.rev / data.exp) * 100 : 0
        })).sort((a, b) => b.exp - a.exp);
    }, [workers, vehicleData, revenues, selectedYear, t, filters.months]);

    const formatCurrency = (val: number) => formatNumber(Math.round(val)) + ' ' + t('unit_jd');

    const handleExportExcel = () => {
        const rawData = extractTableData(tableContainerRef);
        exportToExcel(rawData, `Consolidated_Financial_Management_${selectedYear}`);
    };

    return (
        <CollapsibleSection title={t('sec_financial_mgmt')}>
            <div className="flex flex-wrap items-center justify-between gap-6 mb-10">
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1.5 rounded-[1.5rem] shadow-inner border border-slate-200 dark:border-slate-700">
                    <button 
                        onClick={() => setViewMode('comparison')}
                        className={`tab-button px-6 py-2.5 rounded-xl text-xs font-black transition-all duration-300 ${viewMode === 'comparison' ? 'bg-white dark:bg-slate-700 shadow-xl text-indigo-600 dark:text-indigo-400 border border-slate-200 dark:border-slate-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        {t('btn_fin_comparison')}
                    </button>
                    <button 
                        onClick={() => setViewMode('expenses')}
                        className={`tab-button px-6 py-2.5 rounded-xl text-xs font-black transition-all duration-300 ${viewMode === 'expenses' ? 'bg-white dark:bg-slate-700 shadow-xl text-red-600 dark:text-red-400 border border-slate-200 dark:border-slate-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        {t('btn_fin_expenses')}
                    </button>
                    <button 
                        onClick={() => setViewMode('revenues')}
                        className={`tab-button px-6 py-2.5 rounded-xl text-xs font-black transition-all duration-300 ${viewMode === 'revenues' ? 'bg-white dark:bg-slate-700 shadow-xl text-emerald-600 dark:text-emerald-400 border border-slate-200 dark:border-slate-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        {t('btn_fin_revenues')}
                    </button>
                </div>
                <ExportDropdown 
                    onExportPdf={() => printTable(tableContainerRef, t('sec_financial_mgmt'), filters, t, language)}
                    onExportExcel={handleExportExcel}
                    onExportCsv={handleExportExcel}
                    onExportImage={() => exportToImage(tableContainerRef, `Financial_Consolidated_Export`)}
                />
            </div>

            {/* Comprehensive Financial KPIs */}
            <div className="grid grid-cols-1 md:grid-cols-5 gap-5 mb-10">
                <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-7 rounded-[2.5rem] shadow-xl text-white transform transition-transform hover:scale-105">
