            <div className="text-[9px] md:text-[11px] font-black text-slate-400 dark:text-slate-500 leading-tight mb-2 md:mb-4 uppercase tracking-widest group-hover:text-slate-700 dark:group-hover:text-slate-200 transition-colors">
